00055 void  VLCReader::xReadCodeTr(uint32_t length, uint32_t& rValue, const char *pSymbolName)
00056 {
00057 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00058   xReadCode (length, rValue, pSymbolName);
00059 #else
00060   xReadCode (length, rValue);
00061 #endif
00062   if (length < 10)
00063   {
00064     DTRACE( g_trace_ctx, D_HEADER, "%-50s u(%d)  : %u\n", pSymbolName, length, rValue );
00065   }
00066   else
00067   {
00068     DTRACE( g_trace_ctx, D_HEADER, "%-50s u(%d) : %u\n", pSymbolName, length, rValue );
00069   }
00070 }
