00104 #if RExt__DECODER_DEBUG_BIT_STATISTICS || ENABLE_TRACING
00105 void VLCReader::xReadSCode (uint32_t length, int& value, const char *pSymbolName)
00106 #else
00107 void VLCReader::xReadSCode (uint32_t length, int& value)
00108 #endif
00109 {
00110   uint32_t val;
00111   assert ( length > 0 && length<=32);
00112   m_pcBitstream->read (length, val);
00113   value= length>=32 ? int(val) : ( (-int( val & (uint32_t(1)<<(length-1)))) | int(val) );
00114 
00115 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00116   CodingStatistics::IncrementStatisticEP(pSymbolName, length, value);
00117 #endif
00118 #if ENABLE_TRACING
00119   if (length < 10)
00120   {
00121     DTRACE( g_trace_ctx, D_HEADER, "%-50s i(%d)  : %d\n", pSymbolName, length, value );
00122   }
00123   else
00124   {
00125     DTRACE( g_trace_ctx, D_HEADER, "%-50s i(%d) : %d\n", pSymbolName, length, value );
00126   }
00127 #endif
00128 }
