00130 // ====================================================================================================================
00131 // Protected member functions
00132 // ====================================================================================================================
00133 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00134 void VLCReader::xReadCode (uint32_t uiLength, uint32_t& ruiCode, const char *pSymbolName)
00135 #else
00136 void VLCReader::xReadCode (uint32_t uiLength, uint32_t& ruiCode)
00137 #endif
00138 {
00139   CHECK( uiLength == 0, "Reading a code of length '0'" );
00140   m_pcBitstream->read (uiLength, ruiCode);
00141 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00142   CodingStatistics::IncrementStatisticEP(pSymbolName, uiLength, ruiCode);
00143 #endif
