00145 
00146 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00147 void VLCReader::xReadUvlc( uint32_t& ruiVal, const char *pSymbolName)
00148 #else
00149 void VLCReader::xReadUvlc( uint32_t& ruiVal)
00150 #endif
00151 {
00152   uint32_t uiVal = 0;
00153   uint32_t uiCode = 0;
00154   uint32_t uiLength;
00155   m_pcBitstream->read( 1, uiCode );
00156 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00157   uint32_t totalLen=1;
00158 #endif
00159 
00160   if( 0 == uiCode )
00161   {
00162     uiLength = 0;
00163 
00164     while( ! ( uiCode & 1 ))
00165     {
00166       m_pcBitstream->read( 1, uiCode );
00167       uiLength++;
00168     }
00169 
00170     m_pcBitstream->read( uiLength, uiVal );
00171 
00172     uiVal += (1 << uiLength)-1;
00173 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00174     totalLen+=uiLength+uiLength;
00175 #endif
00176   }
00177 
00178   ruiVal = uiVal;
00179 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00180   CodingStatistics::IncrementStatisticEP(pSymbolName, int(totalLen), ruiVal);
00181 #endif
00182 }
00183 
00184 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00185 void VLCReader::xReadSvlc( int& riVal, const char *pSymbolName)
00186 #else
00187 void VLCReader::xReadSvlc( int& riVal)
00188 #endif
00189 {
00190   uint32_t uiBits = 0;
00191   m_pcBitstream->read( 1, uiBits );
00192 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00193   uint32_t totalLen=1;
00194 #endif
00195   if( 0 == uiBits )
00196   {
00197     uint32_t uiLength = 0;
00198 
00199     while( ! ( uiBits & 1 ))
00200     {
00201       m_pcBitstream->read( 1, uiBits );
00202       uiLength++;
00203     }
00204 
00205     m_pcBitstream->read( uiLength, uiBits );
00206 
00207     uiBits += (1 << uiLength);
00208     riVal = ( uiBits & 1) ? -(int)(uiBits>>1) : (int)(uiBits>>1);
00209 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00210     totalLen+=uiLength+uiLength;
00211 #endif
00212   }
00213   else
00214   {
00215     riVal = 0;
00216   }
00217 #if RExt__DECODER_DEBUG_BIT_STATISTICS
00218   CodingStatistics::IncrementStatisticEP(pSymbolName, int(totalLen), uiBits);
00219 #endif
00220 }
