00234 void VLCReader::xReadRbspTrailingBits()
00235 {
00236   uint32_t bit;
00237   READ_FLAG( bit, "rbsp_stop_one_bit");
00238   CHECK(bit!=1, "Trailing bit not '1'");
00239   int cnt = 0;
00240   while (m_pcBitstream->getNumBitsUntilByteAligned())
00241   {
00242     READ_FLAG( bit, "rbsp_alignment_zero_bit");
00243     CHECK(bit!=0, "Alignment bit is not '0'");
00244     cnt++;
00245   }
00246   CHECK(cnt >= 8, "Read more than '8' trailing bits");
00247 }
