00249 void AUDReader::parseAccessUnitDelimiter(InputBitstream* bs, uint32_t &audIrapOrGdrAuFlag, uint32_t &picType)
00250 {
00251   setBitstream(bs);
00252 
00253 #if ENABLE_TRACING
00254   xTraceAccessUnitDelimiter();
00255 #endif
00256 
00257   READ_FLAG (audIrapOrGdrAuFlag, "aud_irap_or_gdr_au_flag");
00258   READ_CODE (3, picType, "pic_type");
00259   xReadRbspTrailingBits();
00260 }
00261 
00262 void FDReader::parseFillerData(InputBitstream* bs, uint32_t &fdSize)
00263 {
00264   setBitstream(bs);
00265 #if ENABLE_TRACING
00266   xTraceFillerData();
00267 #endif
00268   uint32_t ffByte;
00269   fdSize = 0;
00270   while( m_pcBitstream->getNumBitsLeft() >8 )
00271   {
00272     READ_CODE (8, ffByte, "ff_byte");
00273     CHECK(ffByte!=0xff, "Invalid filler data : not '0xff'");
00274     fdSize++;
00275   }
00276   xReadRbspTrailingBits();
00277 }
