00296 void HLSyntaxReader::copyRefPicList(SPS* sps, ReferencePictureList* source_rpl, ReferencePictureList* dest_rp)
00297 {
00298   dest_rp->setNumberOfShorttermPictures(source_rpl->getNumberOfShorttermPictures());
00299 
00300   dest_rp->setNumberOfInterLayerPictures( sps->getInterLayerPresentFlag() ? source_rpl->getNumberOfInterLayerPictures() : 0 );
00301 
00302   if( sps->getLongTermRefsPresent() )
00303   {
00304     dest_rp->setLtrpInSliceHeaderFlag(source_rpl->getLtrpInSliceHeaderFlag());
00305     dest_rp->setNumberOfLongtermPictures( source_rpl->getNumberOfLongtermPictures() );
00306   }
00307   else
00308     dest_rp->setNumberOfLongtermPictures(0);
00309 
00310   uint32_t numRefPic = dest_rp->getNumberOfShorttermPictures() + dest_rp->getNumberOfLongtermPictures();
00311 
00312   for( int ii = 0; ii < numRefPic; ii++ )
00313   {
00314     dest_rp->setRefPicIdentifier( ii, source_rpl->getRefPicIdentifier( ii ), source_rpl->isRefPicLongterm( ii ), source_rpl->isInterLayerRefPic( ii ), source_rpl->getInterLayerRefPicIdx( ii ) );
00315   }
00316 }
00317 
00318 void HLSyntaxReader::parseRefPicList(SPS* sps, ReferencePictureList* rpl, int rplIdx)
00319 {
00320   uint32_t code;
00321   READ_UVLC(code, "num_ref_entries[ listIdx ][ rplsIdx ]");
00322   uint32_t numRefPic = code;
00323   uint32_t numStrp = 0;
00324   uint32_t numLtrp = 0;
00325   uint32_t numIlrp = 0;
00326 
00327   if (sps->getLongTermRefsPresent() && numRefPic > 0 && rplIdx != -1)
00328   {
00329     READ_FLAG(code, "ltrp_in_slice_header_flag[ listIdx ][ rplsIdx ]");
00330     rpl->setLtrpInSliceHeaderFlag(code);
00331   }
00332   else if(sps->getLongTermRefsPresent())
00333   {
00334     rpl->setLtrpInSliceHeaderFlag( 1 );
00335   }
00336 
00337   bool isLongTerm;
00338   int prevDelta = MAX_INT;
00339   int deltaValue = 0;
00340   bool firstSTRP = true;
00341 
00342   rpl->setInterLayerPresentFlag( sps->getInterLayerPresentFlag() );
00343 
00344   for (int ii = 0; ii < numRefPic; ii++)
00345   {
00346     uint32_t isInterLayerRefPic = 0;
00347 
00348     if( rpl->getInterLayerPresentFlag() )
00349     {
00350       READ_FLAG( isInterLayerRefPic, "inter_layer_ref_pic_flag[ listIdx ][ rplsIdx ][ i ]" );
00351 
00352       if( isInterLayerRefPic )
00353       {
00354         READ_UVLC( code, "ilrp_idx[ listIdx ][ rplsIdx ][ i ]" );
00355         rpl->setRefPicIdentifier( ii, 0, true, true, code );
00356         numIlrp++;
00357       }
00358     }
00359 
00360     if( !isInterLayerRefPic )
00361     {
00362     isLongTerm = false;
00363     if (sps->getLongTermRefsPresent())
00364     {
00365       READ_FLAG(code, "st_ref_pic_flag[ listIdx ][ rplsIdx ][ i ]");
00366       isLongTerm = (code == 1) ? false : true;
00367     }
00368     else
00369       isLongTerm = false;
00370 
00371     if (!isLongTerm)
00372     {
00373       READ_UVLC(code, "abs_delta_poc_st[ listIdx ][ rplsIdx ][ i ]");
00374       if ((!sps->getUseWP() && !sps->getUseWPBiPred()) || (ii == 0))
00375       {
00376         code++;
00377       }
00378       int readValue = code;
00379       if (readValue > 0)
00380       {
00381         READ_FLAG(code, "strp_entry_sign_flag[ listIdx ][ rplsIdx ][ i ]");
00382         if (code)
00383         {
00384           readValue = -readValue;
00385         }
00386       }
00387       if (firstSTRP)
00388       {
00389         firstSTRP = false;
00390         prevDelta = deltaValue = readValue;
00391       }
00392       else
00393       {
00394         deltaValue = prevDelta + readValue;
00395         prevDelta = deltaValue;
00396       }
00397 
00398       rpl->setRefPicIdentifier( ii, deltaValue, isLongTerm, false, 0 );
00399       numStrp++;
00400     }
00401     else
00402     {
00403       if (!rpl->getLtrpInSliceHeaderFlag())
00404         READ_CODE(sps->getBitsForPOC(), code, "poc_lsb_lt[listIdx][rplsIdx][j]");
00405       rpl->setRefPicIdentifier( ii, code, isLongTerm, false, 0 );
00406       numLtrp++;
00407     }
00408     }
00409   }
00410   rpl->setNumberOfShorttermPictures(numStrp);
00411   rpl->setNumberOfLongtermPictures(numLtrp);
00412   rpl->setNumberOfInterLayerPictures( numIlrp );
00413 }
00414 
00415 void HLSyntaxReader::parsePPS( PPS* pcPPS )
00416 {
00417 #if ENABLE_TRACING
00418   xTracePPSHeader ();
00419 #endif
00420   uint32_t  uiCode;
00421 
00422   int   iCode;
00423   READ_CODE(6, uiCode, "pps_pic_parameter_set_id");
00424   CHECK(uiCode > 63, "PPS id exceeds boundary (63)");
00425   pcPPS->setPPSId (uiCode);
00426 
00427   READ_CODE(4, uiCode, "pps_seq_parameter_set_id");
00428   pcPPS->setSPSId (uiCode);
00429 
00430   READ_FLAG( uiCode, "pps_mixed_nalu_types_in_pic_flag" );       pcPPS->setMixedNaluTypesInPicFlag( uiCode == 1 );
00431 
00432   READ_UVLC( uiCode, "pps_pic_width_in_luma_samples" );          pcPPS->setPicWidthInLumaSamples( uiCode );
00433   READ_UVLC( uiCode, "pps_pic_height_in_luma_samples" );         pcPPS->setPicHeightInLumaSamples( uiCode );
00434   READ_FLAG( uiCode, "pps_conformance_window_flag");
00435   pcPPS->setConformanceWindowFlag( uiCode );
00436   if (uiCode != 0)
00437   {
00438     Window& conf = pcPPS->getConformanceWindow();
00439     READ_UVLC(uiCode, "pps_conf_win_left_offset");               conf.setWindowLeftOffset(uiCode);
00440     READ_UVLC(uiCode, "pps_conf_win_right_offset");              conf.setWindowRightOffset(uiCode);
00441     READ_UVLC(uiCode, "pps_conf_win_top_offset");                conf.setWindowTopOffset(uiCode);
00442     READ_UVLC(uiCode, "pps_conf_win_bottom_offset");             conf.setWindowBottomOffset(uiCode);
00443   }
00444   READ_FLAG( uiCode, "pps_scaling_window_explicit_signalling_flag" );
00445   if( uiCode != 0 )
00446   {
00447     Window &scalingWindow = pcPPS->getScalingWindow();
00448     READ_SVLC( iCode, "pps_scaling_win_left_offset" );               scalingWindow.setWindowLeftOffset( iCode );
00449     READ_SVLC( iCode, "pps_scaling_win_right_offset" );              scalingWindow.setWindowRightOffset( iCode );
00450     READ_SVLC( iCode, "pps_scaling_win_top_offset" );                scalingWindow.setWindowTopOffset( iCode );
00451     READ_SVLC( iCode, "pps_scaling_win_bottom_offset" );             scalingWindow.setWindowBottomOffset( iCode );
00452   }
00453   else
00454   {
00455     Window &scalingWindow = pcPPS->getScalingWindow();
00456     Window& conf = pcPPS->getConformanceWindow();
00457     scalingWindow.setWindowLeftOffset( conf.getWindowLeftOffset() );
00458     scalingWindow.setWindowRightOffset( conf.getWindowRightOffset() );
00459     scalingWindow.setWindowTopOffset( conf.getWindowTopOffset() );
00460     scalingWindow.setWindowBottomOffset( conf.getWindowBottomOffset() );
00461   }
00462 
00463   READ_FLAG( uiCode, "pps_output_flag_present_flag" );                    pcPPS->setOutputFlagPresentFlag( uiCode==1 );
00464 
00465   READ_FLAG( uiCode, "pps_no_pic_partition_flag");                     pcPPS->setNoPicPartitionFlag(uiCode == 1);
00466   READ_FLAG( uiCode, "pps_subpic_id_mapping_present_flag" );           pcPPS->setSubPicIdMappingInPpsFlag( uiCode != 0 );
00467   if( pcPPS->getSubPicIdMappingInPpsFlag() )
00468   {
00469     if( !pcPPS->getNoPicPartitionFlag() )
00470     {
00471       READ_UVLC(uiCode, "pps_num_subpics_minus1");                         pcPPS->setNumSubPics(uiCode + 1);
00472     }
00473     else
00474     {
00475       pcPPS->setNumSubPics(1);
00476     }
00477     CHECK( uiCode > MAX_NUM_SUB_PICS-1,  "Number of sub-pictures exceeds limit");
00478 
00479     READ_UVLC( uiCode, "pps_subpic_id_len_minus1" );                       pcPPS->setSubPicIdLen( uiCode + 1 );
00480     CHECK( uiCode > 15, "Invalid pps_subpic_id_len_minus1 signalled");
00481 
00482     CHECK((1 << pcPPS->getSubPicIdLen()) < pcPPS->getNumSubPics(), "pps_subpic_id_len exceeds valid range");
00483     for( int picIdx = 0; picIdx < pcPPS->getNumSubPics( ); picIdx++ )
00484     {
00485       READ_CODE( pcPPS->getSubPicIdLen( ), uiCode, "pps_subpic_id[i]" );   pcPPS->setSubPicId( picIdx, uiCode );
00486     }
00487   }
00488   if(!pcPPS->getNoPicPartitionFlag())
00489   {
00490     int colIdx, rowIdx;
00491     pcPPS->resetTileSliceInfo();
00492 
00493     // CTU size - required to match size in SPS
00494     READ_CODE(2, uiCode, "pps_log2_ctu_size_minus5");                 pcPPS->setLog2CtuSize(uiCode + 5);
00495     CHECK(uiCode > 2, "pps_log2_ctu_size_minus5 must be less than or equal to 2");
00496 
00497     // number of explicit tile columns/rows
00498     READ_UVLC( uiCode, "pps_num_exp_tile_columns_minus1" );               pcPPS->setNumExpTileColumns( uiCode + 1 );
00499     READ_UVLC( uiCode, "pps_num_exp_tile_rows_minus1" );                  pcPPS->setNumExpTileRows( uiCode + 1 );
00500     CHECK(pcPPS->getNumExpTileColumns() > MAX_TILE_COLS,              "Number of explicit tile columns exceeds valid range");
00501 
00502     // tile sizes
00503     for( colIdx = 0; colIdx < pcPPS->getNumExpTileColumns(); colIdx++ )
00504     {
00505       READ_UVLC( uiCode, "pps_tile_column_width_minus1[i]" );             pcPPS->addTileColumnWidth( uiCode + 1 );
00506       CHECK(uiCode  > (pcPPS->getPicWidthInCtu()-1),                 "The value of pps_tile_column_width_minus1[i] shall be in the range of 0 to PicWidthInCtbY-1, inclusive");
00507     }
00508     for( rowIdx = 0; rowIdx < pcPPS->getNumExpTileRows(); rowIdx++ )
00509     {
00510       READ_UVLC( uiCode, "pps_tile_row_height_minus1[i]" );               pcPPS->addTileRowHeight( uiCode + 1 );
00511       CHECK(uiCode > (pcPPS->getPicHeightInCtu() - 1),                "The value of pps_tile_row_height_minus shall be in the range of 0 to PicHeightInCtbY-1, inclusive");
00512     }
00513     pcPPS->initTiles();
00514     // rectangular slice signalling
00515     if (pcPPS->getNumTiles() > 1)
00516     {
00517       READ_CODE(1, uiCode, "pps_loop_filter_across_tiles_enabled_flag");    pcPPS->setLoopFilterAcrossTilesEnabledFlag(uiCode == 1);
00518       READ_CODE(1, uiCode, "pps_rect_slice_flag");
00519     }
00520     else
00521     {
00522       pcPPS->setLoopFilterAcrossTilesEnabledFlag(false);
00523       uiCode = 1;
00524     }
00525     pcPPS->setRectSliceFlag(uiCode == 1);
00526     if (pcPPS->getRectSliceFlag())
00527     {
00528       READ_FLAG(uiCode, "pps_single_slice_per_subpic_flag");            pcPPS->setSingleSlicePerSubPicFlag(uiCode == 1);
00529     }
00530     else
00531     {
00532       pcPPS->setSingleSlicePerSubPicFlag(0);
00533     }
00534     if (pcPPS->getRectSliceFlag() & !(pcPPS->getSingleSlicePerSubPicFlag()))
00535     {
00536       int32_t tileIdx = 0;
00537 
00538       READ_UVLC( uiCode, "pps_num_slices_in_pic_minus1" );                pcPPS->setNumSlicesInPic( uiCode + 1 );
00539       CHECK(pcPPS->getNumSlicesInPic() > MAX_SLICES,                  "Number of slices in picture exceeds valid range");
00540       if ((pcPPS->getNumSlicesInPic() - 1) > 1)
00541       {
00542         READ_CODE(1, uiCode, "pps_tile_idx_delta_present_flag");
00543         pcPPS->setTileIdxDeltaPresentFlag(uiCode == 1);
00544       }
00545       else
00546       {
00547         pcPPS->setTileIdxDeltaPresentFlag(0);
00548       }
00549       pcPPS->initRectSlices();
00550 
00551       // read rectangular slice parameters
00552       for( int i = 0; i < pcPPS->getNumSlicesInPic()-1; i++ )
00553       {
00554         pcPPS->setSliceTileIdx( i, tileIdx );
00555 
00556         // complete tiles within a single slice
00557         if( ( tileIdx % pcPPS->getNumTileColumns() ) != pcPPS->getNumTileColumns() - 1 )
00558         {
00559           READ_UVLC( uiCode, "pps_slice_width_in_tiles_minus1[i]" );
00560           pcPPS->setSliceWidthInTiles ( i, uiCode + 1 );
00561         }
00562         else
00563         {
00564           pcPPS->setSliceWidthInTiles( i, 1 );
00565         }
00566 
00567         if( tileIdx / pcPPS->getNumTileColumns() != pcPPS->getNumTileRows() - 1  &&
00568          ( pcPPS->getTileIdxDeltaPresentFlag() || tileIdx % pcPPS->getNumTileColumns() == 0 ) ) 
00569         {
00570           READ_UVLC( uiCode, "pps_slice_height_in_tiles_minus1[i]" );
00571           pcPPS->setSliceHeightInTiles( i, uiCode + 1 );
00572         }
00573         else
00574         {
00575           if( ( tileIdx / pcPPS->getNumTileColumns() ) == pcPPS->getNumTileRows() - 1 )
00576           {
00577             pcPPS->setSliceHeightInTiles( i, 1 );
00578           }
00579           else
00580           {
00581             pcPPS->setSliceHeightInTiles( i, pcPPS->getSliceHeightInTiles( i - 1 ) );
00582           }
00583       }
00584 
00585         // multiple slices within a single tile special case
00586         if( pcPPS->getSliceWidthInTiles(i) == 1 && pcPPS->getSliceHeightInTiles(i) == 1 )
00587         {
00588           if( pcPPS->getTileRowHeight(tileIdx / pcPPS->getNumTileColumns()) > 1 )
00589           {
00590             READ_UVLC(uiCode, "pps_num_exp_slices_in_tile[i]");
00591             if (uiCode == 0)
00592             {
00593               pcPPS->setNumSlicesInTile(i, 1);
00594               pcPPS->setSliceHeightInCtu(i, pcPPS->getTileRowHeight(tileIdx / pcPPS->getNumTileColumns()));
00595             }
00596             else
00597             {
00598               uint32_t numExpSliceInTile = uiCode;
00599               uint32_t remTileRowHeight  = pcPPS->getTileRowHeight(tileIdx / pcPPS->getNumTileColumns());
00600               int j = 0;
00601 
00602               for( ; j < numExpSliceInTile; j++ )
00603               {
00604                 READ_UVLC(uiCode, "pps_exp_slice_height_in_ctus_minus1[i]");
00605                 pcPPS->setSliceHeightInCtu(i + j, uiCode + 1);
00606                 remTileRowHeight -= (uiCode + 1);
00607               }
00608               uint32_t uniformSliceHeight = uiCode + 1;
00609 
00610               while( remTileRowHeight >= uniformSliceHeight )
00611               {
00612                 pcPPS->setSliceHeightInCtu(i + j, uniformSliceHeight);
00613                 remTileRowHeight -= uniformSliceHeight;
00614                 j++;
00615               }
00616               if( remTileRowHeight > 0 )
00617               {
00618                 pcPPS->setSliceHeightInCtu(i + j, remTileRowHeight);
00619                 j++;
00620               }
00621               for( int k = 0; k < j; k++ )
00622               {
00623                 pcPPS->setNumSlicesInTile(i + k, j);
00624                 pcPPS->setSliceWidthInTiles(i + k, 1);
00625                 pcPPS->setSliceHeightInTiles(i + k, 1);
00626                 pcPPS->setSliceTileIdx(i + k, tileIdx);
00627               }
00628               i += (j - 1);
00629             }
00630           }
00631           else
00632           {
00633             pcPPS->setNumSlicesInTile(i, 1);
00634             pcPPS->setSliceHeightInCtu(i, pcPPS->getTileRowHeight(tileIdx / pcPPS->getNumTileColumns()));
00635           }
00636         }
00637 
00638         // tile index offset to start of next slice
00639         if( i < pcPPS->getNumSlicesInPic()-1 )
00640         {
00641           if( pcPPS->getTileIdxDeltaPresentFlag() )
00642           {
00643             int32_t  tileIdxDelta;
00644             READ_SVLC( tileIdxDelta, "pps_tile_idx_delta[i]" );
00645             tileIdx += tileIdxDelta;
00646             CHECK( tileIdx < 0 || tileIdx >= pcPPS->getNumTiles(), "Invalid pps_tile_idx_delta.");
00647           }
00648           else
00649           {
00650             tileIdx += pcPPS->getSliceWidthInTiles( i );
00651             if( tileIdx % pcPPS->getNumTileColumns() == 0)
00652             {
00653               tileIdx += (pcPPS->getSliceHeightInTiles( i ) - 1) * pcPPS->getNumTileColumns();
00654             }
00655           }
00656         }
00657       }
00658       pcPPS->setSliceTileIdx(pcPPS->getNumSlicesInPic()-1, tileIdx );
00659     }
00660 
00661     if (pcPPS->getRectSliceFlag() == 0 || pcPPS->getSingleSlicePerSubPicFlag() || pcPPS->getNumSlicesInPic() > 1)
00662     {
00663       READ_CODE(1, uiCode, "pps_loop_filter_across_slices_enabled_flag");   pcPPS->setLoopFilterAcrossSlicesEnabledFlag( uiCode == 1 );
00664     }
00665     else
00666     {
00667       pcPPS->setLoopFilterAcrossSlicesEnabledFlag( false );
00668     }
00669   }
00670   else
00671   {
00672     pcPPS->setSingleSlicePerSubPicFlag(1);
00673   }
00674 
00675   READ_FLAG( uiCode,   "pps_cabac_init_present_flag" );            pcPPS->setCabacInitPresentFlag( uiCode ? true : false );
00676 
00677   READ_UVLC(uiCode, "pps_num_ref_idx_default_active_minus1[0]");
00678   CHECK(uiCode > 14, "Invalid code read");
00679   pcPPS->setNumRefIdxL0DefaultActive(uiCode+1);
00680 
00681   READ_UVLC(uiCode, "pps_num_ref_idx_default_active_minus1[1]");
00682   CHECK(uiCode > 14, "Invalid code read");
00683   pcPPS->setNumRefIdxL1DefaultActive(uiCode+1);
00684 
00685   READ_FLAG(uiCode, "pps_rpl1_idx_present_flag");
00686   pcPPS->setRpl1IdxPresentFlag(uiCode);
00687   READ_FLAG( uiCode, "pps_weighted_pred_flag" );          // Use of Weighting Prediction (P_SLICE)
00688   pcPPS->setUseWP( uiCode==1 );
00689   READ_FLAG( uiCode, "pps_weighted_bipred_flag" );         // Use of Bi-Directional Weighting Prediction (B_SLICE)
00690   pcPPS->setWPBiPred( uiCode==1 );
00691   READ_FLAG(uiCode, "pps_ref_wraparound_enabled_flag");           pcPPS->setWrapAroundEnabledFlag( uiCode ? true : false );
00692   if (pcPPS->getWrapAroundEnabledFlag())
00693   {
00694     READ_UVLC(uiCode, "pps_ref_wraparound_offset");               
00695     pcPPS->setPicWidthMinusWrapAroundOffset(uiCode);
00696   }
00697   else
00698   {
00699     pcPPS->setPicWidthMinusWrapAroundOffset(0);
00700   }
00701 
00702   READ_SVLC(iCode, "pps_init_qp_minus26" );                            pcPPS->setPicInitQPMinus26(iCode);
00703   READ_FLAG( uiCode, "pps_cu_qp_delta_enabled_flag" );            pcPPS->setUseDQP( uiCode ? true : false );
00704   READ_FLAG(uiCode, "pps_chroma_tool_offsets_present_flag");
00705   pcPPS->setPPSChromaToolFlag(uiCode ? true : false);
00706   if (pcPPS->getPPSChromaToolFlag())
00707   {
00708   READ_SVLC( iCode, "pps_cb_qp_offset");
00709   pcPPS->setQpOffset(COMPONENT_Cb, iCode);
00710   CHECK( pcPPS->getQpOffset(COMPONENT_Cb) < -12, "Invalid Cb QP offset" );
00711   CHECK( pcPPS->getQpOffset(COMPONENT_Cb) >  12, "Invalid Cb QP offset" );
00712 
00713   READ_SVLC( iCode, "pps_cr_qp_offset");
00714   pcPPS->setQpOffset(COMPONENT_Cr, iCode);
00715   CHECK( pcPPS->getQpOffset(COMPONENT_Cr) < -12, "Invalid Cr QP offset" );
00716   CHECK( pcPPS->getQpOffset(COMPONENT_Cr) >  12, "Invalid Cr QP offset" );
00717 
00718   READ_FLAG(uiCode, "pps_joint_cbcr_qp_offset_present_flag");
00719   pcPPS->setJointCbCrQpOffsetPresentFlag(uiCode ? true : false);
00720 
00721   if (pcPPS->getJointCbCrQpOffsetPresentFlag())
00722   {
00723     READ_SVLC(iCode, "pps_joint_cbcr_qp_offset_value");
00724   }
00725   else
00726   {
00727     iCode = 0;
00728   }
00729   pcPPS->setQpOffset(JOINT_CbCr, iCode);
00730 
00731   CHECK( pcPPS->getQpOffset(JOINT_CbCr) < -12, "Invalid CbCr QP offset" );
00732   CHECK( pcPPS->getQpOffset(JOINT_CbCr) >  12, "Invalid CbCr QP offset" );
00733 
00734   CHECK(MAX_NUM_COMPONENT>3, "Invalid maximal number of components");
00735 
00736   READ_FLAG( uiCode, "pps_slice_chroma_qp_offsets_present_flag" );
00737   pcPPS->setSliceChromaQpFlag( uiCode ? true : false );
00738 
00739   READ_FLAG( uiCode, "pps_cu_chroma_qp_offset_list_enabled_flag");
00740   if (uiCode == 0)
00741   {
00742     pcPPS->clearChromaQpOffsetList();
00743   }
00744   else
00745   {
00746     uint32_t tableSizeMinus1 = 0;
00747     READ_UVLC(tableSizeMinus1, "pps_chroma_qp_offset_list_len_minus1");
00748     CHECK(tableSizeMinus1 >= MAX_QP_OFFSET_LIST_SIZE, "Table size exceeds maximum");
00749 
00750     for (int cuChromaQpOffsetIdx = 0; cuChromaQpOffsetIdx <= (tableSizeMinus1); cuChromaQpOffsetIdx++)
00751     {
00752       int cbOffset;
00753       int crOffset;
00754       int jointCbCrOffset;
00755       READ_SVLC(cbOffset, "pps_cb_qp_offset_list[i]");
00756       CHECK(cbOffset < -12 || cbOffset > 12, "Invalid chroma QP offset");
00757       READ_SVLC(crOffset, "pps_cr_qp_offset_list[i]");
00758       CHECK(crOffset < -12 || crOffset > 12, "Invalid chroma QP offset");
00759       if (pcPPS->getJointCbCrQpOffsetPresentFlag())
00760       {
00761         READ_SVLC(jointCbCrOffset, "pps_joint_cbcr_qp_offset_list[i]");
00762       }
00763       else
00764       {
00765         jointCbCrOffset = 0;
00766       }
00767       CHECK(jointCbCrOffset < -12 || jointCbCrOffset > 12, "Invalid chroma QP offset");
00768       // table uses +1 for index (see comment inside the function)
00769       pcPPS->setChromaQpOffsetListEntry(cuChromaQpOffsetIdx + 1, cbOffset, crOffset, jointCbCrOffset);
00770     }
00771     CHECK(pcPPS->getChromaQpOffsetListLen() != tableSizeMinus1 + 1, "Invalid chroma QP offset list length");
00772   }
00773   }
00774   else
00775   {
00776     pcPPS->setQpOffset(COMPONENT_Cb, 0);
00777     pcPPS->setQpOffset(COMPONENT_Cr, 0);
00778     pcPPS->setJointCbCrQpOffsetPresentFlag(0);
00779     pcPPS->setSliceChromaQpFlag(0);
00780     pcPPS->clearChromaQpOffsetList();
00781   }
00782   READ_FLAG( uiCode, "pps_deblocking_filter_control_present_flag" );       pcPPS->setDeblockingFilterControlPresentFlag( uiCode ? true : false );
00783   if(pcPPS->getDeblockingFilterControlPresentFlag())
00784   {
00785     READ_FLAG( uiCode, "pps_deblocking_filter_override_enabled_flag" );    pcPPS->setDeblockingFilterOverrideEnabledFlag( uiCode ? true : false );
00786     READ_FLAG( uiCode, "pps_deblocking_filter_disabled_flag" );        pcPPS->setPPSDeblockingFilterDisabledFlag(uiCode ? true : false );
00787     if (!pcPPS->getNoPicPartitionFlag() && pcPPS->getDeblockingFilterOverrideEnabledFlag())
00788     {
00789       READ_FLAG(uiCode, "pps_dbf_info_in_ph_flag");
00790       pcPPS->setDbfInfoInPhFlag(uiCode ? true : false);
00791     }
00792     else
00793     {
00794       pcPPS->setDbfInfoInPhFlag(false);
00795     }
00796     if(!pcPPS->getPPSDeblockingFilterDisabledFlag())
00797     {
00798       READ_SVLC( iCode, "pps_beta_offset_div2" );                    pcPPS->setDeblockingFilterBetaOffsetDiv2( iCode );
00799       CHECK(  pcPPS->getDeblockingFilterBetaOffsetDiv2() < -12 ||
00800               pcPPS->getDeblockingFilterBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
00801 
00802       READ_SVLC( iCode, "pps_tc_offset_div2");                       pcPPS->setDeblockingFilterTcOffsetDiv2( iCode );
00803       CHECK(  pcPPS->getDeblockingFilterTcOffsetDiv2() < -12 ||
00804               pcPPS->getDeblockingFilterTcOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
00805 
00806       if( pcPPS->getPPSChromaToolFlag() )
00807       {
00808         READ_SVLC( iCode, "pps_cb_beta_offset_div2" );                   pcPPS->setDeblockingFilterCbBetaOffsetDiv2( iCode );
00809         CHECK( pcPPS->getDeblockingFilterCbBetaOffsetDiv2() < -12 ||
00810           pcPPS->getDeblockingFilterCbBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
00811 
00812         READ_SVLC( iCode, "pps_cb_tc_offset_div2" );                     pcPPS->setDeblockingFilterCbTcOffsetDiv2( iCode );
00813         CHECK( pcPPS->getDeblockingFilterCbTcOffsetDiv2() < -12 ||
00814           pcPPS->getDeblockingFilterCbTcOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
00815 
00816         READ_SVLC( iCode, "pps_cr_beta_offset_div2") ;                   pcPPS->setDeblockingFilterCrBetaOffsetDiv2( iCode );
00817         CHECK( pcPPS->getDeblockingFilterCrBetaOffsetDiv2() < -12 ||
00818           pcPPS->getDeblockingFilterCrBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
00819 
00820         READ_SVLC( iCode, "pps_cr_tc_offset_div2" );                     pcPPS->setDeblockingFilterCrTcOffsetDiv2( iCode );
00821         CHECK(pcPPS->getDeblockingFilterCrTcOffsetDiv2() < -12 ||
00822           pcPPS->getDeblockingFilterCrTcOffsetDiv2() > 12, "Invalid deblocking filter configuration");
00823       }
00824       else
00825       {
00826         pcPPS->setDeblockingFilterCbBetaOffsetDiv2 ( pcPPS->getDeblockingFilterBetaOffsetDiv2() );
00827         pcPPS->setDeblockingFilterCbTcOffsetDiv2   ( pcPPS->getDeblockingFilterTcOffsetDiv2()   );
00828         pcPPS->setDeblockingFilterCrBetaOffsetDiv2 ( pcPPS->getDeblockingFilterBetaOffsetDiv2() );
00829         pcPPS->setDeblockingFilterCrTcOffsetDiv2   ( pcPPS->getDeblockingFilterTcOffsetDiv2()   );
00830       }
00831     }
00832   }
00833   else
00834   {
00835     pcPPS->setDeblockingFilterOverrideEnabledFlag(false);
00836     pcPPS->setDbfInfoInPhFlag(false);
00837   }
00838 
00839   if (!pcPPS->getNoPicPartitionFlag())
00840   {
00841     READ_FLAG(uiCode, "pps_rpl_info_in_ph_flag");                    pcPPS->setRplInfoInPhFlag(uiCode ? true : false);
00842     READ_FLAG(uiCode, "pps_sao_info_in_ph_flag");                    pcPPS->setSaoInfoInPhFlag(uiCode ? true : false);
00843     READ_FLAG(uiCode, "pps_alf_info_in_ph_flag");                    pcPPS->setAlfInfoInPhFlag(uiCode ? true : false);
00844     if ((pcPPS->getUseWP() || pcPPS->getWPBiPred()) && pcPPS->getRplInfoInPhFlag())
00845     {
00846       READ_FLAG(uiCode, "pps_wp_info_in_ph_flag");                   pcPPS->setWpInfoInPhFlag(uiCode ? true : false);
00847     }
00848     else
00849     {
00850       pcPPS->setWpInfoInPhFlag(false);
00851     }
00852     READ_FLAG(uiCode, "pps_qp_delta_info_in_ph_flag");               pcPPS->setQpDeltaInfoInPhFlag(uiCode ? true : false);
00853   }
00854   else
00855   {
00856     pcPPS->setRplInfoInPhFlag(false);
00857     pcPPS->setSaoInfoInPhFlag(false);
00858     pcPPS->setAlfInfoInPhFlag(false);
00859     pcPPS->setWpInfoInPhFlag(false);
00860     pcPPS->setQpDeltaInfoInPhFlag(false);
00861   }
00862 
00863   READ_FLAG( uiCode, "pps_picture_header_extension_present_flag");
00864   pcPPS->setPictureHeaderExtensionPresentFlag(uiCode);
00865   READ_FLAG( uiCode, "pps_slice_header_extension_present_flag");
00866   pcPPS->setSliceHeaderExtensionPresentFlag(uiCode);
00867 
00868   READ_FLAG( uiCode, "pps_extension_flag");
00869 
00870   if (uiCode)
00871   {
00872       while ( xMoreRbspData() )
00873       {
00874         READ_FLAG( uiCode, "pps_extension_data_flag");
00875       }
00876   }
00877   xReadRbspTrailingBits();
00878 }
00879 
00880 void HLSyntaxReader::parseAPS( APS* aps )
00881 {
00882 #if ENABLE_TRACING
00883   xTraceAPSHeader();
00884 #endif
00885 
00886   uint32_t  code;
00887   READ_CODE(3, code, "aps_params_type");
00888   aps->setAPSType(ApsType(code));
00889 
00890   READ_CODE(5, code, "adaptation_parameter_set_id");
00891   aps->setAPSId(code);
00892   uint32_t codeApsChromaPresentFlag;
00893   READ_FLAG(codeApsChromaPresentFlag, "aps_chroma_present_flag");
00894   aps->chromaPresentFlag = codeApsChromaPresentFlag;
00895 
00896   const ApsType apsType = aps->getAPSType();
00897 
00898   if (apsType == ALF_APS)
00899   {
00900     parseAlfAps( aps );
00901   }
00902   else if (apsType == LMCS_APS)
00903   {
00904     parseLmcsAps( aps );
00905   }
00906   else if (apsType == SCALING_LIST_APS)
00907   {
00908     parseScalingListAps( aps );
00909   }
00910   READ_FLAG(code, "aps_extension_flag");
00911   if (code)
00912   {
00913     while (xMoreRbspData())
00914     {
00915       READ_FLAG(code, "aps_extension_data_flag");
00916     }
00917   }
00918   xReadRbspTrailingBits();
00919 }
00920 
00921 void HLSyntaxReader::parseAlfAps( APS* aps )
00922 {
00923   uint32_t  code;
00924 
00925   AlfParam param = aps->getAlfAPSParam();
00926   param.reset();
00927   param.enabledFlag[COMPONENT_Y] = param.enabledFlag[COMPONENT_Cb] = param.enabledFlag[COMPONENT_Cr] = true;
00928   READ_FLAG(code, "alf_luma_new_filter");
00929   param.newFilterFlag[CHANNEL_TYPE_LUMA] = code;
00930 
00931   if (aps->chromaPresentFlag)
00932   {
00933     READ_FLAG(code, "alf_chroma_new_filter");
00934     param.newFilterFlag[CHANNEL_TYPE_CHROMA] = code;
00935   }
00936   else
00937   {
00938     param.newFilterFlag[CHANNEL_TYPE_CHROMA] = 0;
00939   }
00940 
00941   CcAlfFilterParam ccAlfParam = aps->getCcAlfAPSParam();
00942   if (aps->chromaPresentFlag)
00943   {
00944   READ_FLAG(code, "alf_cc_cb_filter_signal_flag");
00945   ccAlfParam.newCcAlfFilter[COMPONENT_Cb - 1] = code;
00946   }
00947   else
00948   {
00949     ccAlfParam.newCcAlfFilter[COMPONENT_Cb - 1] = 0;
00950   }
00951   if (aps->chromaPresentFlag)
00952   {
00953   READ_FLAG(code, "alf_cc_cr_filter_signal_flag");
00954   ccAlfParam.newCcAlfFilter[COMPONENT_Cr - 1] = code;
00955   }
00956   else
00957   {
00958     ccAlfParam.newCcAlfFilter[COMPONENT_Cr - 1] = 0;
00959   }
00960   CHECK(param.newFilterFlag[CHANNEL_TYPE_LUMA] == 0 && param.newFilterFlag[CHANNEL_TYPE_CHROMA] == 0
00961           && ccAlfParam.newCcAlfFilter[COMPONENT_Cb - 1] == 0 && ccAlfParam.newCcAlfFilter[COMPONENT_Cr - 1] == 0,
00962         "bitstream conformance error: one of alf_luma_filter_signal_flag, alf_chroma_filter_signal_flag, "
00963         "alf_cross_component_cb_filter_signal_flag, and alf_cross_component_cr_filter_signal_flag shall be nonzero");
00964 
00965   if (param.newFilterFlag[CHANNEL_TYPE_LUMA])
00966   {
00967     READ_FLAG(code, "alf_luma_clip");
00968     param.nonLinearFlag[CHANNEL_TYPE_LUMA] = code ? true : false;
00969     READ_UVLC(code, "alf_luma_num_filters_signalled_minus1");
00970     param.numLumaFilters = code + 1;
00971     if (param.numLumaFilters > 1)
00972     {
00973       const int length =  ceilLog2(param.numLumaFilters);
00974       for (int i = 0; i < MAX_NUM_ALF_CLASSES; i++)
00975       {
00976         READ_CODE(length, code, "alf_luma_coeff_delta_idx");
00977         param.filterCoeffDeltaIdx[i] = code;
00978       }
00979     }
00980     else
00981     {
00982       memset(param.filterCoeffDeltaIdx, 0, sizeof(param.filterCoeffDeltaIdx));
00983     }
00984     alfFilter( param, false, 0 );
00985   }
00986   if (param.newFilterFlag[CHANNEL_TYPE_CHROMA])
00987   {
00988     READ_FLAG(code, "alf_nonlinear_enable_flag_chroma");
00989     param.nonLinearFlag[CHANNEL_TYPE_CHROMA] = code ? true : false;
00990 
00991     if( MAX_NUM_ALF_ALTERNATIVES_CHROMA > 1 )
00992       READ_UVLC( code, "alf_chroma_num_alts_minus1" );
00993     else
00994       code = 0;
00995 
00996     param.numAlternativesChroma = code + 1;
00997 
00998     for( int altIdx=0; altIdx < param.numAlternativesChroma; ++altIdx )
00999     {
01000       alfFilter( param, true, altIdx );
01001     }
01002   }
01003 
01004   for (int ccIdx = 0; ccIdx < 2; ccIdx++)
01005   {
01006     if (ccAlfParam.newCcAlfFilter[ccIdx])
01007     {
01008       if (MAX_NUM_CC_ALF_FILTERS > 1)
01009       {
01010         READ_UVLC(code, ccIdx == 0 ? "alf_cc_cb_filters_signalled_minus1" : "alf_cc_cr_filters_signalled_minus1");
01011       }
01012       else
01013       {
01014         code = 0;
01015       }
01016       ccAlfParam.ccAlfFilterCount[ccIdx] = code + 1;
01017 
01018       for (int filterIdx = 0; filterIdx < ccAlfParam.ccAlfFilterCount[ccIdx]; filterIdx++)
01019       {
01020         ccAlfParam.ccAlfFilterIdxEnabled[ccIdx][filterIdx] = true;
01021         AlfFilterShape alfShape(size_CC_ALF);
01022 
01023         short *coeff = ccAlfParam.ccAlfCoeff[ccIdx][filterIdx];
01024         // Filter coefficients
01025         for (int i = 0; i < alfShape.numCoeff - 1; i++)
01026         {
01027           READ_CODE(CCALF_BITS_PER_COEFF_LEVEL, code,
01028                     ccIdx == 0 ? "alf_cc_cb_mapped_coeff_abs" : "alf_cc_cr_mapped_coeff_abs");
01029           if (code == 0)
01030           {
01031             coeff[i] = 0;
01032           }
01033           else
01034           {
01035             coeff[i] = 1 << (code - 1);
01036             READ_FLAG(code, ccIdx == 0 ? "alf_cc_cb_coeff_sign" : "alf_cc_cr_coeff_sign");
01037             coeff[i] *= 1 - 2 * code;
01038           }
01039         }
01040 
01041         DTRACE(g_trace_ctx, D_SYNTAX, "%s coeff filterIdx %d: ", ccIdx == 0 ? "Cb" : "Cr", filterIdx);
01042         for (int i = 0; i < alfShape.numCoeff; i++)
01043         {
01044           DTRACE(g_trace_ctx, D_SYNTAX, "%d ", coeff[i]);
01045         }
01046         DTRACE(g_trace_ctx, D_SYNTAX, "\n");
01047       }
01048 
01049       for (int filterIdx = ccAlfParam.ccAlfFilterCount[ccIdx]; filterIdx < MAX_NUM_CC_ALF_FILTERS; filterIdx++)
01050       {
01051         ccAlfParam.ccAlfFilterIdxEnabled[ccIdx][filterIdx] = false;
01052       }
01053     }
01054   }
01055   aps->setCcAlfAPSParam(ccAlfParam);
01056 
01057   aps->setAlfAPSParam(param);
01058 }
01059 
01060 void HLSyntaxReader::parseLmcsAps( APS* aps )
01061 {
01062   uint32_t  code;
01063 
01064   SliceReshapeInfo& info = aps->getReshaperAPSInfo();
01065   memset(info.reshaperModelBinCWDelta, 0, PIC_CODE_CW_BINS * sizeof(int));
01066   READ_UVLC(code, "lmcs_min_bin_idx");                             info.reshaperModelMinBinIdx = code;
01067   READ_UVLC(code, "lmcs_delta_max_bin_idx");                       info.reshaperModelMaxBinIdx = PIC_CODE_CW_BINS - 1 - code;
01068   READ_UVLC(code, "lmcs_delta_cw_prec_minus1");                    info.maxNbitsNeededDeltaCW = code + 1;
01069   assert(info.maxNbitsNeededDeltaCW > 0);
01070   for (uint32_t i = info.reshaperModelMinBinIdx; i <= info.reshaperModelMaxBinIdx; i++)
01071   {
01072     READ_CODE(info.maxNbitsNeededDeltaCW, code, "lmcs_delta_abs_cw[ i ]");
01073     int absCW = code;
01074     if (absCW > 0)
01075     {
01076       READ_CODE(1, code, "lmcs_delta_sign_cw_flag[ i ]");
01077     }
01078     int signCW = code;
01079     info.reshaperModelBinCWDelta[i] = (1 - 2 * signCW) * absCW;
01080   }
01081   if (aps->chromaPresentFlag)
01082   {
01083   READ_CODE(3, code, "lmcs_delta_abs_crs");
01084   }
01085   int absCW = aps->chromaPresentFlag ? code : 0;
01086   if (absCW > 0)
01087   {
01088     READ_CODE(1, code, "lmcs_delta_sign_crs_flag");
01089   }
01090   int signCW = code;
01091   info.chrResScalingOffset = (1 - 2 * signCW) * absCW;
01092 
01093   aps->setReshaperAPSInfo(info);
01094 }
