01102 void  HLSyntaxReader::parseVUI(VUI* pcVUI, SPS *pcSPS)
01103 {
01104 #if ENABLE_TRACING
01105   DTRACE( g_trace_ctx, D_HEADER, "----------- vui_parameters -----------\n");
01106 #endif
01107   unsigned vuiPayloadSize = pcSPS->getVuiPayloadSize();
01108   InputBitstream *bs = getBitstream();
01109   setBitstream(bs->extractSubstream(vuiPayloadSize * 8));
01110 
01111   uint32_t  symbol;
01112 
01113   READ_FLAG(symbol,  "vui_progressive_source_flag"          ); pcVUI->setProgressiveSourceFlag(symbol ? true : false);
01114   READ_FLAG(symbol,  "vui_interlaced_source_flag"           ); pcVUI->setInterlacedSourceFlag(symbol ? true : false);
01115   READ_FLAG(symbol, "vui_non_packed_constraint_flag");         pcVUI->setNonPackedFlag(symbol ? true : false);
01116   READ_FLAG(symbol, "vui_non_projected_constraint_flag");      pcVUI->setNonProjectedFlag(symbol ? true : false);
01117   READ_FLAG( symbol, "vui_aspect_ratio_info_present_flag");           pcVUI->setAspectRatioInfoPresentFlag(symbol);
01118   if (pcVUI->getAspectRatioInfoPresentFlag())
01119   {
01120     READ_FLAG( symbol, "vui_aspect_ratio_constant_flag");           pcVUI->setAspectRatioConstantFlag(symbol);
01121     READ_CODE(8, symbol, "vui_aspect_ratio_idc");                         pcVUI->setAspectRatioIdc(symbol);
01122     if (pcVUI->getAspectRatioIdc() == 255)
01123     {
01124       READ_CODE(16, symbol, "vui_sar_width");                             pcVUI->setSarWidth(symbol);
01125       READ_CODE(16, symbol, "vui_sar_height");                            pcVUI->setSarHeight(symbol);
01126     }
01127   }
01128 
01129   READ_FLAG(     symbol, "vui_overscan_info_present_flag");               pcVUI->setOverscanInfoPresentFlag(symbol);
01130   if (pcVUI->getOverscanInfoPresentFlag())
01131   {
01132     READ_FLAG(   symbol, "vui_overscan_appropriate_flag");                pcVUI->setOverscanAppropriateFlag(symbol);
01133   }
01134 
01135   READ_FLAG(   symbol, "vui_colour_description_present_flag");          pcVUI->setColourDescriptionPresentFlag(symbol);
01136   if (pcVUI->getColourDescriptionPresentFlag())
01137   {
01138     READ_CODE(8, symbol, "vui_colour_primaries");                       pcVUI->setColourPrimaries(symbol);
01139     READ_CODE(8, symbol, "vui_transfer_characteristics");               pcVUI->setTransferCharacteristics(symbol);
01140     READ_CODE(8, symbol, "vui_matrix_coeffs");                          pcVUI->setMatrixCoefficients(symbol);
01141     READ_FLAG(   symbol, "vui_full_range_flag");                    pcVUI->setVideoFullRangeFlag(symbol);
01142   }
01143 
01144   READ_FLAG(     symbol, "vui_chroma_loc_info_present_flag");             pcVUI->setChromaLocInfoPresentFlag(symbol);
01145   if (pcVUI->getChromaLocInfoPresentFlag())
01146   {
01147     if(pcVUI->getProgressiveSourceFlag() && !pcVUI->getInterlacedSourceFlag())
01148     {
01149       READ_UVLC(   symbol, "vui_chroma_sample_loc_type" );        pcVUI->setChromaSampleLocType(symbol);
01150     }
01151     else
01152     {
01153       READ_UVLC(   symbol, "vui_chroma_sample_loc_type_top_field" );        pcVUI->setChromaSampleLocTypeTopField(symbol);
01154       READ_UVLC(   symbol, "vui_chroma_sample_loc_type_bottom_field" );     pcVUI->setChromaSampleLocTypeBottomField(symbol);
01155     }
01156   }
01157 
01158   int payloadBitsRem = getBitstream()->getNumBitsLeft();
01159   if(payloadBitsRem)      //Corresponds to more_data_in_payload()
01160   {
01161     while(payloadBitsRem > 9)    //payload_extension_present()
01162     {
01163       READ_CODE(1, symbol, "vui_reserved_payload_extension_data");
01164       payloadBitsRem--;
01165     }
01166     int finalBits = getBitstream()->peekBits(payloadBitsRem);
01167     int numFinalZeroBits = 0;
01168     int mask = 0xff;
01169     while(finalBits & (mask >> numFinalZeroBits))
01170     {
01171       numFinalZeroBits++;
01172     }
01173     while(payloadBitsRem > 9-numFinalZeroBits)     //payload_extension_present()
01174     {
01175       READ_CODE(1, symbol, "vui_reserved_payload_extension_data");
01176       payloadBitsRem--;
01177     }
01178     READ_FLAG(symbol, "vui_payload_bit_equal_to_one");
01179     CHECK(symbol != 1, "vui_payload_bit_equal_to_one not equal to 1");
01180     payloadBitsRem--;
01181     while(payloadBitsRem)
01182     {
01183       READ_FLAG(symbol, "vui_payload_bit_equal_to_zero");
01184       CHECK(symbol != 0, "vui_payload_bit_equal_to_zero not equal to 0");
01185       payloadBitsRem--;
01186     }
01187   }
01188   delete getBitstream();
01189   setBitstream(bs);
01190 }
01191 
01192 void HLSyntaxReader::parseGeneralHrdParameters(GeneralHrdParams *hrd)
01193 {
01194   uint32_t  symbol;
01195   READ_CODE(32, symbol, "num_units_in_tick");                hrd->setNumUnitsInTick(symbol);
01196   READ_CODE(32, symbol, "time_scale");                       hrd->setTimeScale(symbol);
01197   READ_FLAG(symbol, "general_nal_hrd_parameters_present_flag");           hrd->setGeneralNalHrdParametersPresentFlag(symbol == 1 ? true : false);
01198   READ_FLAG(symbol, "general_vcl_hrd_parameters_present_flag");           hrd->setGeneralVclHrdParametersPresentFlag(symbol == 1 ? true : false);
01199 #if JVET_S0175_ASPECT6
01200   if(  hrd->getGeneralNalHrdParametersPresentFlag() || hrd->getGeneralVclHrdParametersPresentFlag() )
01201   {
01202 #else
01203   CHECK((hrd->getGeneralNalHrdParametersPresentFlag() == 0) && (hrd->getGeneralVclHrdParametersPresentFlag() == 0), "general_nal_hrd_params_present_flag and general_vcl_hrd_params_present_flag in each general_hrd_parameters( ) syntax structure shall not be both equal to 0.");
01204 #endif
01205     READ_FLAG(symbol, "general_same_pic_timing_in_all_ols_flag");           hrd->setGeneralSamePicTimingInAllOlsFlag(symbol == 1 ? true : false);
01206     READ_FLAG(symbol, "general_decoding_unit_hrd_params_present_flag");     hrd->setGeneralDecodingUnitHrdParamsPresentFlag(symbol == 1 ? true : false);
01207     if (hrd->getGeneralDecodingUnitHrdParamsPresentFlag())
01208     {
01209       READ_CODE(8, symbol, "tick_divisor_minus2");                        hrd->setTickDivisorMinus2(symbol);
01210     }
01211     READ_CODE(4, symbol, "bit_rate_scale");                       hrd->setBitRateScale(symbol);
01212     READ_CODE(4, symbol, "cpb_size_scale");                       hrd->setCpbSizeScale(symbol);
01213     if (hrd->getGeneralDecodingUnitHrdParamsPresentFlag())
01214     {
01215       READ_CODE(4, symbol, "cpb_size_du_scale");                  hrd->setCpbSizeDuScale(symbol);
01216     }
01217     READ_UVLC(symbol, "hrd_cpb_cnt_minus1");                      hrd->setHrdCpbCntMinus1(symbol);
01218     CHECK(symbol > 31,"The value of hrd_cpb_cnt_minus1 shall be in the range of 0 to 31, inclusive");
01219 #if JVET_S0175_ASPECT6
01220   }
01221 #endif
01222 }
01223 void HLSyntaxReader::parseOlsHrdParameters(GeneralHrdParams * generalHrd, OlsHrdParams *olsHrd, uint32_t firstSubLayer, uint32_t maxNumSubLayersMinus1)
01224 {
01225   uint32_t  symbol;
01226 
01227   for( int i = firstSubLayer; i <= maxNumSubLayersMinus1; i ++ )
01228   {
01229     OlsHrdParams *hrd = &(olsHrd[i]);
01230     READ_FLAG(symbol, "fixed_pic_rate_general_flag");                     hrd->setFixedPicRateGeneralFlag(symbol == 1 ? true : false);
01231     if (!hrd->getFixedPicRateGeneralFlag())
01232     {
01233       READ_FLAG(symbol, "fixed_pic_rate_within_cvs_flag");                hrd->setFixedPicRateWithinCvsFlag(symbol == 1 ? true : false);
01234     }
01235     else
01236     {
01237       hrd->setFixedPicRateWithinCvsFlag(true);
01238     }
01239 
01240     hrd->setLowDelayHrdFlag(false); // Inferred to be 0 when not present
01241 
01242     if (hrd->getFixedPicRateWithinCvsFlag())
01243     {
01244       READ_UVLC(symbol, "elemental_duration_in_tc_minus1");             hrd->setElementDurationInTcMinus1(symbol);
01245     }
01246 #if JVET_S0175_ASPECT6
01247     else if((generalHrd->getGeneralNalHrdParametersPresentFlag() || generalHrd->getGeneralVclHrdParametersPresentFlag()) && generalHrd->getHrdCpbCntMinus1() == 0)
01248 #else
01249     else if(generalHrd->getHrdCpbCntMinus1() == 0)
01250 #endif
01251     {
01252       READ_FLAG(symbol, "low_delay_hrd_flag");                      hrd->setLowDelayHrdFlag(symbol == 1 ? true : false);
01253     }
01254 
01255     for( int nalOrVcl = 0; nalOrVcl < 2; nalOrVcl ++ )
01256     {
01257       if (((nalOrVcl == 0) && (generalHrd->getGeneralNalHrdParametersPresentFlag())) || ((nalOrVcl == 1) && (generalHrd->getGeneralVclHrdParametersPresentFlag())))
01258       {
01259         for (int j = 0; j <= (generalHrd->getHrdCpbCntMinus1()); j++)
01260         {
01261           READ_UVLC(symbol, "bit_rate_value_minus1");             hrd->setBitRateValueMinus1(j, nalOrVcl, symbol);
01262           READ_UVLC(symbol, "cpb_size_value_minus1");             hrd->setCpbSizeValueMinus1(j, nalOrVcl, symbol);
01263           if (generalHrd->getGeneralDecodingUnitHrdParamsPresentFlag())
01264           {
01265             READ_UVLC(symbol, "cpb_size_du_value_minus1");             hrd->setDuCpbSizeValueMinus1(j, nalOrVcl, symbol);
01266             READ_UVLC(symbol, "bit_rate_du_value_minus1");             hrd->setDuBitRateValueMinus1(j, nalOrVcl, symbol);
01267           }
01268           READ_FLAG(symbol, "cbr_flag");                          hrd->setCbrFlag(j, nalOrVcl, symbol == 1 ? true : false);
01269         }
01270       }
01271     }
01272   }
01273   for (int i = 0; i < firstSubLayer; i++)
01274   {
01275     OlsHrdParams* hrdHighestTLayer = &(olsHrd[maxNumSubLayersMinus1]);
01276     OlsHrdParams* hrdTemp = &(olsHrd[i]);
01277     bool tempFlag = hrdHighestTLayer->getFixedPicRateGeneralFlag();
01278     hrdTemp->setFixedPicRateGeneralFlag(tempFlag);
01279     tempFlag = hrdHighestTLayer->getFixedPicRateWithinCvsFlag();
01280     hrdTemp->setFixedPicRateWithinCvsFlag(tempFlag);
01281     uint32_t tempElementDurationInTcMinus1 = hrdHighestTLayer->getElementDurationInTcMinus1();
01282     hrdTemp->setElementDurationInTcMinus1(tempElementDurationInTcMinus1);
01283     for (int nalOrVcl = 0; nalOrVcl < 2; nalOrVcl++)
01284     {
01285       if (((nalOrVcl == 0) && (generalHrd->getGeneralNalHrdParametersPresentFlag())) || ((nalOrVcl == 1) && (generalHrd->getGeneralVclHrdParametersPresentFlag())))
01286       {
01287         for (int j = 0; j <= (generalHrd->getHrdCpbCntMinus1()); j++)
01288         {
01289           uint32_t bitRate = hrdHighestTLayer->getBitRateValueMinus1(j, nalOrVcl);
01290           hrdTemp->setBitRateValueMinus1(j, nalOrVcl, bitRate);
01291           uint32_t cpbSize = hrdHighestTLayer->getCpbSizeValueMinus1(j, nalOrVcl);
01292           hrdTemp->setCpbSizeValueMinus1(j, nalOrVcl, cpbSize);
01293           if (generalHrd->getGeneralDecodingUnitHrdParamsPresentFlag())
01294           {
01295             uint32_t bitRateDu = hrdHighestTLayer->getDuBitRateValueMinus1(j, nalOrVcl);
01296             hrdTemp->setDuBitRateValueMinus1(j, nalOrVcl, bitRateDu);
01297             uint32_t cpbSizeDu = hrdHighestTLayer->getDuCpbSizeValueMinus1(j, nalOrVcl);
01298             hrdTemp->setDuCpbSizeValueMinus1(j, nalOrVcl, cpbSizeDu);
01299           }
01300           bool flag = hrdHighestTLayer->getCbrFlag(j, nalOrVcl);
01301           hrdTemp->setCbrFlag(j, nalOrVcl, flag);
01302         }
01303       }
01304     }
01305   }
01306 }
01307 
01308 void HLSyntaxReader::dpb_parameters(int maxSubLayersMinus1, bool subLayerInfoFlag, SPS *pcSPS)
01309 {
01310   uint32_t code;
01311   for (int i = (subLayerInfoFlag ? 0 : maxSubLayersMinus1); i <= maxSubLayersMinus1; i++)
01312   {
01313     READ_UVLC(code, "dpb_max_dec_pic_buffering_minus1[i]");
01314     pcSPS->setMaxDecPicBuffering(code + 1, i);
01315     READ_UVLC(code, "dpb_max_num_reorder_pics[i]");
01316     pcSPS->setMaxNumReorderPics(code, i);
01317     CHECK( pcSPS->getMaxNumReorderPics(i) >= pcSPS->getMaxDecPicBuffering(i), "The value of dpb_max_num_reorder_pics[ i ] shall be in the range of 0 to dpb_max_dec_pic_buffering_minus1[ i ], inclusive" );
01318     READ_UVLC(code, "dpb_max_latency_increase_plus1[i]");
01319     pcSPS->setMaxLatencyIncreasePlus1(code, i);
01320   }
01321 }
