01323 
01324 void HLSyntaxReader::parseSPS(SPS* pcSPS)
01325 {
01326   uint32_t  uiCode;
01327 
01328 #if ENABLE_TRACING
01329   xTraceSPSHeader ();
01330 #endif
01331 
01332   READ_CODE(4, uiCode, "sps_seq_parameter_set_id");              pcSPS->setSPSId(uiCode);
01333   READ_CODE( 4,  uiCode, "sps_video_parameter_set_id" );      pcSPS->setVPSId( uiCode );
01334   READ_CODE(3, uiCode, "sps_max_sub_layers_minus1");          pcSPS->setMaxTLayers   (uiCode + 1);
01335   CHECK(uiCode > 6, "Invalid maximum number of T-layer signalled");
01336   READ_CODE(2, uiCode, "sps_chroma_format_idc");
01337   pcSPS->setChromaFormatIdc(ChromaFormat(uiCode));
01338 
01339   READ_CODE(2, uiCode, "sps_log2_ctu_size_minus5");
01340   pcSPS->setCTUSize(1 << (uiCode + 5));
01341   CHECK(uiCode > 2, "sps_log2_ctu_size_minus5 must be less than or equal to 2");
01342   unsigned ctbLog2SizeY = uiCode + 5;
01343   pcSPS->setMaxCUWidth(pcSPS->getCTUSize());
01344   pcSPS->setMaxCUHeight(pcSPS->getCTUSize());
01345   READ_FLAG(uiCode, "sps_ptl_dpb_hrd_params_present_flag"); pcSPS->setPtlDpbHrdParamsPresentFlag(uiCode);
01346 
01347   if( !pcSPS->getVPSId() )
01348   {
01349     CHECK( !pcSPS->getPtlDpbHrdParamsPresentFlag(), "When sps_video_parameter_set_id is equal to 0, the value of sps_ptl_dpb_hrd_params_present_flag shall be equal to 1" );
01350   }
01351 
01352   if (pcSPS->getPtlDpbHrdParamsPresentFlag())
01353   {
01354 
01355     parseProfileTierLevel(pcSPS->getProfileTierLevel(), true, pcSPS->getMaxTLayers() - 1);
01356 
01357   }
01358 
01359   READ_FLAG(uiCode, "sps_gdr_enabled_flag");
01360   pcSPS->setGDREnabledFlag(uiCode);
01361 
01362 #if JVET_R0266_GCI
01363   if (pcSPS->getProfileTierLevel()->getConstraintInfo()->getNoGdrConstraintFlag())
01364   {
01365     CHECK(uiCode != 0, "When gci_no_gdr_constraint_flag equal to 1 , the value of sps_gdr_enabled_flag shall be equal to 0");
01366   }
01367 #endif
01368 
01369   READ_FLAG(uiCode, "sps_ref_pic_resampling_enabled_flag");          pcSPS->setRprEnabledFlag(uiCode);
01370   if (pcSPS->getProfileTierLevel()->getConstraintInfo()->getNoRprConstraintFlag())
01371   {
01372     CHECK(uiCode != 0, "When gci_no_ref_pic_resampling_constraint_flag is equal to 1, sps_ref_pic_resampling_enabled_flag shall be equal to 0");
01373   }
01374   if (uiCode)
01375   {
01376     READ_FLAG(uiCode, "sps_res_change_in_clvs_allowed_flag");        pcSPS->setResChangeInClvsEnabledFlag(uiCode);
01377   }
01378   else
01379   {
01380     pcSPS->setResChangeInClvsEnabledFlag(0);
01381   }
01382 
01383   if (pcSPS->getProfileTierLevel()->getConstraintInfo()->getNoResChangeInClvsConstraintFlag())
01384   {
01385     CHECK(uiCode != 0, "When no_res_change_in_clvs_constraint_flag is equal to 1, sps_res_change_in_clvs_allowed_flag shall be equal to 0");
01386   }
01387 
01388   READ_UVLC( uiCode, "sps_pic_width_max_in_luma_samples" );          pcSPS->setMaxPicWidthInLumaSamples( uiCode );
01389   READ_UVLC( uiCode, "sps_pic_height_max_in_luma_samples" );         pcSPS->setMaxPicHeightInLumaSamples( uiCode );
01390   READ_FLAG( uiCode, "sps_conformance_window_flag");
01391   if (uiCode != 0)
01392   {
01393     Window& conf = pcSPS->getConformanceWindow();
01394     READ_UVLC(uiCode, "sps_conf_win_left_offset");               conf.setWindowLeftOffset(uiCode);
01395     READ_UVLC(uiCode, "sps_conf_win_right_offset");              conf.setWindowRightOffset(uiCode);
01396     READ_UVLC(uiCode, "sps_conf_win_top_offset");                conf.setWindowTopOffset(uiCode);
01397     READ_UVLC(uiCode, "sps_conf_win_bottom_offset");             conf.setWindowBottomOffset(uiCode);
01398   }
01399 
01400 
01401   READ_FLAG( uiCode, "sps_subpic_info_present_flag" );               pcSPS->setSubPicInfoPresentFlag(uiCode);
01402   if (pcSPS->getProfileTierLevel()->getConstraintInfo()->getNoSubpicInfoConstraintFlag())
01403   {
01404     CHECK(uiCode != 0, "When gci_no_subpic_info_constraint_flag is equal to 1, the value of sps_subpic_info_present_flag shall be equal to 0");
01405   }
01406 
01407   if (pcSPS->getSubPicInfoPresentFlag())
01408   {
01409     READ_UVLC(uiCode, "sps_num_subpics_minus1"); pcSPS->setNumSubPics(uiCode + 1);
01410     CHECK(uiCode > (pcSPS->getMaxPicWidthInLumaSamples() / (1 << pcSPS->getCTUSize())) * (pcSPS->getMaxPicHeightInLumaSamples() / (1 << pcSPS->getCTUSize())) - 1, "Invalid sps_num_subpics_minus1 value");
01411     if( pcSPS->getNumSubPics() == 1 )
01412     {
01413       pcSPS->setSubPicCtuTopLeftX( 0, 0 );
01414       pcSPS->setSubPicCtuTopLeftY( 0, 0 );
01415       pcSPS->setSubPicWidth( 0, ( pcSPS->getMaxPicWidthInLumaSamples() + pcSPS->getCTUSize() - 1 ) >> floorLog2( pcSPS->getCTUSize() ) );
01416       pcSPS->setSubPicHeight( 0, ( pcSPS->getMaxPicHeightInLumaSamples() + pcSPS->getCTUSize() - 1 ) >> floorLog2( pcSPS->getCTUSize() ) );
01417 
01418       pcSPS->setIndependentSubPicsFlag(1);
01419       pcSPS->setSubPicSameSizeFlag(0);
01420 
01421       pcSPS->setSubPicTreatedAsPicFlag(0, 1);
01422       pcSPS->setLoopFilterAcrossSubpicEnabledFlag(0, 0);
01423     }
01424     else
01425     {
01426       READ_FLAG(uiCode, "sps_independent_subpics_flag"); pcSPS->setIndependentSubPicsFlag(uiCode != 0);
01427       READ_FLAG(uiCode, "sps_subpic_same_size_flag"); pcSPS->setSubPicSameSizeFlag(uiCode);
01428       uint32_t tmpWidthVal = (pcSPS->getMaxPicWidthInLumaSamples() + pcSPS->getCTUSize() - 1) / pcSPS->getCTUSize();
01429       uint32_t tmpHeightVal = (pcSPS->getMaxPicHeightInLumaSamples() + pcSPS->getCTUSize() - 1) / pcSPS->getCTUSize();
01430       uint32_t numSubpicCols = 1;
01431       for (int picIdx = 0; picIdx < pcSPS->getNumSubPics(); picIdx++)
01432       {
01433         if (!pcSPS->getSubPicSameSizeFlag() || picIdx == 0)
01434         {
01435           if ((picIdx > 0) && (pcSPS->getMaxPicWidthInLumaSamples() > pcSPS->getCTUSize()))
01436           {
01437             READ_CODE(ceilLog2(tmpWidthVal), uiCode, "sps_subpic_ctu_top_left_x[ i ]");
01438             pcSPS->setSubPicCtuTopLeftX(picIdx, uiCode);
01439           }
01440           else
01441           {
01442             pcSPS->setSubPicCtuTopLeftX(picIdx, 0);
01443           }
01444           if ((picIdx > 0) && (pcSPS->getMaxPicHeightInLumaSamples() > pcSPS->getCTUSize()))
01445           {
01446             READ_CODE(ceilLog2(tmpHeightVal), uiCode, "sps_subpic_ctu_top_left_y[ i ]");
01447             pcSPS->setSubPicCtuTopLeftY(picIdx, uiCode);
01448           }
01449           else
01450           {
01451             pcSPS->setSubPicCtuTopLeftY(picIdx, 0);
01452           }
01453           if (picIdx <pcSPS->getNumSubPics() - 1 && pcSPS->getMaxPicWidthInLumaSamples() > pcSPS->getCTUSize())
01454           {
01455             READ_CODE(ceilLog2(tmpWidthVal), uiCode, "sps_subpic_width_minus1[ i ]");
01456             pcSPS->setSubPicWidth(picIdx, uiCode + 1);
01457           }
01458           else
01459           {
01460             pcSPS->setSubPicWidth(picIdx, tmpWidthVal - pcSPS->getSubPicCtuTopLeftX(picIdx));
01461           }
01462           if (picIdx <pcSPS->getNumSubPics() - 1 && pcSPS->getMaxPicHeightInLumaSamples() > pcSPS->getCTUSize())
01463           {
01464             READ_CODE(ceilLog2(tmpHeightVal), uiCode, "sps_subpic_height_minus1[ i ]");
01465             pcSPS->setSubPicHeight(picIdx, uiCode + 1);
01466           }
01467           else
01468           {
01469             pcSPS->setSubPicHeight(picIdx, tmpHeightVal - pcSPS->getSubPicCtuTopLeftY(picIdx));
01470           }
