01820     READ_FLAG(uiCode, "sps_bdof_control_present_in_ph_flag");        pcSPS->setBdofControlPresentInPhFlag( uiCode != 0 );
01821   }
01822   else {
01823     pcSPS->setBdofControlPresentInPhFlag( false );
01824   }
01825   READ_FLAG(uiCode, "sps_smvd_enabled_flag");                       pcSPS->setUseSMVD( uiCode != 0 );
01826   READ_FLAG(uiCode, "sps_dmvr_enabled_flag");                        pcSPS->setUseDMVR(uiCode != 0);
01827   if (pcSPS->getUseDMVR())
01828   {
01829     READ_FLAG(uiCode, "sps_dmvr_control_present_in_ph_flag");                 pcSPS->setDmvrControlPresentInPhFlag( uiCode != 0 );
01830   }
01831   else {
01832     pcSPS->setDmvrControlPresentInPhFlag( false );
01833   }
01834   READ_FLAG(uiCode, "sps_mmvd_enabled_flag");                        pcSPS->setUseMMVD(uiCode != 0);
01835   if (pcSPS->getUseMMVD())
01836   {
01837     READ_FLAG(uiCode, "sps_mmvd_fullpel_only_flag");                pcSPS->setFpelMmvdEnabledFlag(uiCode != 0);
01838   }
01839   else
01840   {
01841     pcSPS->setFpelMmvdEnabledFlag( false );
01842   }
01843 
01844   READ_UVLC(uiCode, "sps_six_minus_max_num_merge_cand");
01845   CHECK(MRG_MAX_NUM_CANDS <= uiCode, "Incorrrect max number of merge candidates!");
01846   pcSPS->setMaxNumMergeCand(MRG_MAX_NUM_CANDS - uiCode);
01847   READ_FLAG(uiCode, "sps_sbt_enabled_flag");                        pcSPS->setUseSBT                 ( uiCode != 0 );
01848   READ_FLAG( uiCode,    "sps_affine_enabled_flag" );                            pcSPS->setUseAffine              ( uiCode != 0 );
01849   if ( pcSPS->getUseAffine() )
01850   {
01851     READ_UVLC(uiCode, "sps_five_minus_max_num_subblock_merge_cand");
01852     CHECK(
01853       uiCode > 5 - (pcSPS->getSbTMVPEnabledFlag() ? 1 : 0),
01854       "The value of sps_five_minus_max_num_subblock_merge_cand shall be in the range of 0 to 5 - sps_sbtmvp_enabled_flag");
01855     CHECK(AFFINE_MRG_MAX_NUM_CANDS < uiCode, "The value of sps_five_minus_max_num_subblock_merge_cand shall be in the range of 0 to 5 - sps_sbtmvp_enabled_flag");
01856     pcSPS->setMaxNumAffineMergeCand(AFFINE_MRG_MAX_NUM_CANDS - uiCode);
01857     READ_FLAG( uiCode,  "sps_affine_type_flag" );                       pcSPS->setUseAffineType          ( uiCode != 0 );
01858     if( pcSPS->getAMVREnabledFlag())
01859     {
01860       READ_FLAG( uiCode, "sps_affine_amvr_enabled_flag" );            pcSPS->setAffineAmvrEnabledFlag  ( uiCode != 0 );
01861     }
01862     READ_FLAG( uiCode, "sps_affine_prof_enabled_flag" );            pcSPS->setUsePROF                ( uiCode != 0 );
01863     if (pcSPS->getUsePROF())
01864     {
01865       READ_FLAG(uiCode, "sps_prof_control_present_in_ph_flag");               pcSPS->setProfControlPresentInPhFlag ( uiCode != 0 );
01866     }
01867     else {
01868       pcSPS->setProfControlPresentInPhFlag( false );
01869     }
01870   }
01871 
01872   READ_FLAG( uiCode,    "sps_bcw_enabled_flag" );                   pcSPS->setUseBcw( uiCode != 0 );
01873 
01874   READ_FLAG( uiCode,     "sps_ciip_enabled_flag" );                           pcSPS->setUseCiip             ( uiCode != 0 );
01875   if (pcSPS->getMaxNumMergeCand() >= 2)
01876   {
01877     READ_FLAG(uiCode, "sps_gpm_enabled_flag");
01878     pcSPS->setUseGeo(uiCode != 0);
01879     if (pcSPS->getUseGeo())
01880     {
01881       if (pcSPS->getMaxNumMergeCand() >= 3)
01882       {
01883         READ_UVLC(uiCode, "sps_max_num_merge_cand_minus_max_num_gpm_cand");
01884         CHECK(pcSPS->getMaxNumMergeCand() - 2 < uiCode,
01885               "sps_max_num_merge_cand_minus_max_num_gpm_cand must not be greater than the number of merge candidates minus 2");
01886         pcSPS->setMaxNumGeoCand((uint32_t)(pcSPS->getMaxNumMergeCand() - uiCode));
01887       }
01888       else
01889       {
01890         pcSPS->setMaxNumGeoCand(2);
01891       }
01892     }
01893   }
01894   else
01895   {
01896     pcSPS->setUseGeo(0);
01897     pcSPS->setMaxNumGeoCand(0);
01898   }
01899 
01900   READ_UVLC(uiCode, "sps_log2_parallel_merge_level_minus2");
01901   CHECK(uiCode + 2 > ctbLog2SizeY, "The value of sps_log2_parallel_merge_level_minus2 shall be in the range of 0 to ctbLog2SizeY - 2");
01902   pcSPS->setLog2ParallelMergeLevelMinus2(uiCode);
01903 
01904 
01905   READ_FLAG(uiCode, "sps_isp_enabled_flag");                        pcSPS->setUseISP( uiCode != 0 );
01906   READ_FLAG(uiCode, "sps_mrl_enabled_flag");                        pcSPS->setUseMRL( uiCode != 0 );
01907   READ_FLAG(uiCode, "sps_mip_enabled_flag");                        pcSPS->setUseMIP( uiCode != 0 );
01908   if( pcSPS->getChromaFormatIdc() != CHROMA_400)
01909   {
01910     READ_FLAG( uiCode, "sps_cclm_enabled_flag" );                   pcSPS->setUseLMChroma( uiCode != 0 );
01911   }
01912   else
01913   {
01914     pcSPS->setUseLMChroma(0);
01915   }
01916   if( pcSPS->getChromaFormatIdc() == CHROMA_420 )
01917   {
01918     READ_FLAG( uiCode, "sps_chroma_horizontal_collocated_flag" );   pcSPS->setHorCollocatedChromaFlag( uiCode != 0 );
01919     READ_FLAG( uiCode, "sps_chroma_vertical_collocated_flag" );     pcSPS->setVerCollocatedChromaFlag( uiCode != 0 );
01920   }
01921   else
01922   {
01923     pcSPS->setHorCollocatedChromaFlag(true);
01924     pcSPS->setVerCollocatedChromaFlag(true);
01925   }
01926   READ_FLAG( uiCode,  "sps_palette_enabled_flag");                                pcSPS->setPLTMode                ( uiCode != 0 );
01927   if (pcSPS->getChromaFormatIdc() == CHROMA_444 && pcSPS->getLog2MaxTbSize() != 6)
01928   {
01929     READ_FLAG(uiCode, "sps_act_enabled_flag");                                pcSPS->setUseColorTrans(uiCode != 0);
01930   }
01931   else
01932   {
01933     pcSPS->setUseColorTrans(false);
01934   }
01935   if (pcSPS->getTransformSkipEnabledFlag() || pcSPS->getPLTMode())
01936   {
01937     READ_UVLC(uiCode, "sps_internal_bit_depth_minus_input_bit_depth");
01938     pcSPS->setInternalMinusInputBitDepth(CHANNEL_TYPE_LUMA, uiCode);
01939     CHECK(uiCode > 8, "Invalid sps_internal_bit_depth_minus_input_bit_depth signalled");
01940     pcSPS->setInternalMinusInputBitDepth(CHANNEL_TYPE_CHROMA, uiCode);
01941   }
01942   READ_FLAG(uiCode, "sps_ibc_enabled_flag");                                    pcSPS->setIBCFlag(uiCode);
01943   if (pcSPS->getIBCFlag())
01944   {
01945     READ_UVLC(uiCode, "sps_six_minus_max_num_ibc_merge_cand");
01946     CHECK(IBC_MRG_MAX_NUM_CANDS <= uiCode, "Incorrect max number of IBC merge candidates!");
01947     pcSPS->setMaxNumIBCMergeCand(IBC_MRG_MAX_NUM_CANDS - uiCode);
01948   }
01949   else
01950     pcSPS->setMaxNumIBCMergeCand(0);
01951 
01952 
01953 #if LUMA_ADAPTIVE_DEBLOCKING_FILTER_QP_OFFSET
01954   READ_FLAG( uiCode, "sps_ladf_enabled_flag" );                     pcSPS->setLadfEnabled( uiCode != 0 );
01955   if ( pcSPS->getLadfEnabled() )
01956   {
01957     int signedSymbol = 0;
01958     READ_CODE( 2, uiCode, "sps_num_ladf_intervals_minus2");         pcSPS->setLadfNumIntervals( uiCode + 2 );
01959     READ_SVLC(signedSymbol, "sps_ladf_lowest_interval_qp_offset" );      pcSPS->setLadfQpOffset( signedSymbol, 0 );
01960     for ( int k = 1; k < pcSPS->getLadfNumIntervals(); k++ )
01961     {
01962       READ_SVLC(signedSymbol, "sps_ladf_qp_offset" );                    pcSPS->setLadfQpOffset( signedSymbol, k );
01963       READ_UVLC( uiCode, "sps_ladf_delta_threshold_minus1");
01964       pcSPS->setLadfIntervalLowerBound(uiCode + pcSPS->getLadfIntervalLowerBound(k - 1) + 1, k);
01965     }
01966   }
01967 #endif
01968   READ_FLAG(uiCode, "sps_explicit_scaling_list_enabled_flag");                 pcSPS->setScalingListFlag(uiCode);
01969   if (pcSPS->getProfileTierLevel()->getConstraintInfo()->getNoExplicitScaleListConstraintFlag())
01970   {
01971     CHECK(uiCode != 0, "When gci_no_explicit_scaling_list_constraint_flag is equal to 1, sps_explicit_scaling_list_enabled_flag shall be equal to 0");
01972   }
01973 
01974   if (pcSPS->getUseLFNST() && pcSPS->getScalingListFlag())
01975   {
01976     READ_FLAG(uiCode, "sps_scaling_matrix_for_lfnst_disabled_flag"); pcSPS->setDisableScalingMatrixForLfnstBlks(uiCode ? true : false);
01977   }
01978 
01979   if (pcSPS->getUseColorTrans() && pcSPS->getScalingListFlag())
01980   {
01981     READ_FLAG(uiCode, "sps_scaling_matrix_for_alternative_colour_space_disabled_flag"); pcSPS->setScalingMatrixForAlternativeColourSpaceDisabledFlag(uiCode);
01982   }
01983   if (pcSPS->getScalingMatrixForAlternativeColourSpaceDisabledFlag())
01984   {
01985     READ_FLAG(uiCode, "sps_scaling_matrix_designated_colour_space_flag"); pcSPS->setScalingMatrixDesignatedColourSpaceFlag(uiCode);
01986   }
01987   READ_FLAG(uiCode, "sps_dep_quant_enabled_flag"); pcSPS->setDepQuantEnabledFlag(uiCode);
01988   READ_FLAG(uiCode, "sps_sign_data_hiding_enabled_flag"); pcSPS->setSignDataHidingEnabledFlag(uiCode);
01989 
01990   READ_FLAG( uiCode, "sps_virtual_boundaries_enabled_flag" ); pcSPS->setVirtualBoundariesEnabledFlag( uiCode != 0 );
01991   if (pcSPS->getProfileTierLevel()->getConstraintInfo()->getNoVirtualBoundaryConstraintFlag())
01992   {
01993     CHECK(uiCode != 0, "When gci_no_virtual_boundaries_constraint_flag is equal to 1, sps_virtual_boundaries_enabled_flag shall be equal to 0");
01994   }
01995 
01996   if( pcSPS->getVirtualBoundariesEnabledFlag() )
01997   {
01998     READ_FLAG( uiCode, "sps_loop_filter_across_virtual_boundaries_present_flag" ); pcSPS->setVirtualBoundariesPresentFlag( uiCode != 0 );
01999     if( pcSPS->getVirtualBoundariesPresentFlag() )
02000     {
02001     READ_UVLC(uiCode, "sps_num_ver_virtual_boundaries");        pcSPS->setNumVerVirtualBoundaries( uiCode );
02002     if (pcSPS->getMaxPicWidthInLumaSamples() <= 8)
02003     {
02004       CHECK(pcSPS->getNumVerVirtualBoundaries() != 0, "SPS: When picture width is less than or equal to 8, the number of vertical virtual boundaries shall be equal to 0");
02005     }
02006     else
02007     {
02008       CHECK(pcSPS->getNumVerVirtualBoundaries() > 3, "SPS: The number of vertical virtual boundaries shall be in the range of 0 to 3");
02009     }
02010     for( unsigned i = 0; i < pcSPS->getNumVerVirtualBoundaries(); i++ )
02011     {
02012       READ_UVLC(uiCode, "sps_virtual_boundary_pos_x_minus1[i]");        pcSPS->setVirtualBoundariesPosX((uiCode + 1) << 3, i);
02013       CHECK(uiCode > (((pcSPS->getMaxPicWidthInLumaSamples() + 7) >> 3) - 2), "The value of sps_virtual_boundary_pos_x_minus1[ i ] shall be in the range of 0 to Ceil( sps_pic_width_max_in_luma_samples / 8 ) - 2, inclusive.");
02014     }
02015     READ_UVLC(uiCode, "sps_num_hor_virtual_boundaries");        pcSPS->setNumHorVirtualBoundaries( uiCode );
02016     if (pcSPS->getMaxPicHeightInLumaSamples() <= 8)
02017     {
02018       CHECK(pcSPS->getNumHorVirtualBoundaries() != 0, "SPS: When picture height is less than or equal to 8, the number of horizontal virtual boundaries shall be equal to 0");
02019     }
02020     else
02021     {
02022       CHECK(pcSPS->getNumHorVirtualBoundaries() > 3, "SPS: The number of horizontal virtual boundaries shall be in the range of 0 to 3");
02023     }
02024     for( unsigned i = 0; i < pcSPS->getNumHorVirtualBoundaries(); i++ )
02025     {
02026       READ_UVLC(uiCode, "sps_virtual_boundary_pos_y_minus1[i]");        pcSPS->setVirtualBoundariesPosY((uiCode + 1) << 3, i);
02027       CHECK(uiCode > (((pcSPS->getMaxPicHeightInLumaSamples() + 7) >> 3) - 2), "The value of sps_virtual_boundary_pos_y_minus1[ i ] shall be in the range of 0 to Ceil( sps_pic_height_max_in_luma_samples / 8 ) - 2, inclusive.");
02028     }
02029   }
02030   else
02031   {
02032     pcSPS->setNumVerVirtualBoundaries( 0 );
02033     pcSPS->setNumHorVirtualBoundaries( 0 );
02034   }
02035   }
02036   else
02037   {
02038     pcSPS->setVirtualBoundariesPresentFlag(false);
02039   }
02040 
02041   if (pcSPS->getPtlDpbHrdParamsPresentFlag())
02042   {
02043     READ_FLAG(uiCode, "sps_timing_hrd_params_present_flag");        pcSPS->setGeneralHrdParametersPresentFlag(uiCode);
02044     if (pcSPS->getGeneralHrdParametersPresentFlag())
02045     {
02046       parseGeneralHrdParameters(pcSPS->getGeneralHrdParameters());
02047       if ((pcSPS->getMaxTLayers()-1) > 0)
02048       {
02049         READ_FLAG(uiCode, "sps_sublayer_cpb_params_present_flag");  pcSPS->setSubLayerParametersPresentFlag(uiCode);
02050       }
02051       else if((pcSPS->getMaxTLayers()-1) == 0)
02052       {
02053         pcSPS->setSubLayerParametersPresentFlag(0);
02054       }
02055 
02056       uint32_t firstSubLayer = pcSPS->getSubLayerParametersPresentFlag() ? 0 : (pcSPS->getMaxTLayers() - 1);
02057       parseOlsHrdParameters(pcSPS->getGeneralHrdParameters(),pcSPS->getOlsHrdParameters(), firstSubLayer, pcSPS->getMaxTLayers() - 1);
02058     }
02059   }
02060 
02061   READ_FLAG(     uiCode, "sps_field_seq_flag");                       pcSPS->setFieldSeqFlag(uiCode);
02062   CHECK( pcSPS->getProfileTierLevel()->getFrameOnlyConstraintFlag() && uiCode, "When ptl_frame_only_constraint_flag equal to 1 , the value of sps_field_seq_flag shall be equal to 0");
02063 
02064   READ_FLAG( uiCode, "sps_vui_parameters_present_flag" );             pcSPS->setVuiParametersPresentFlag(uiCode);
02065 
02066   if (pcSPS->getVuiParametersPresentFlag())
02067   {
02068     READ_UVLC(uiCode, "sps_vui_payload_size_minus1");
02069     pcSPS->setVuiPayloadSize(uiCode+1);
02070     while (!isByteAligned())
02071     {
02072       READ_FLAG(uiCode, "sps_vui_alignment_zero_bit");
02073       CHECK(uiCode != 0, "sps_vui_alignment_zero_bit not equal to 0");
02074     }
02075     parseVUI(pcSPS->getVuiParameters(), pcSPS);
02076   }
02077 
02078   // KJS: no SPS extensions defined yet
02079 
02080   READ_FLAG( uiCode, "sps_extension_present_flag");
02081   if (uiCode)
02082   {
02083 #if ENABLE_TRACING || RExt__DECODER_DEBUG_BIT_STATISTICS
02084     static const char *syntaxStrings[]={ "sps_range_extension_flag",
02085       "sps_multilayer_extension_flag",
02086       "sps_extension_6bits[0]",
02087       "sps_extension_6bits[1]",
02088       "sps_extension_6bits[2]",
02089       "sps_extension_6bits[3]",
02090       "sps_extension_6bits[4]",
02091       "sps_extension_6bits[5]" };
02092 #endif
02093     bool sps_extension_flags[NUM_SPS_EXTENSION_FLAGS];
02094 
02095     for(int i=0; i<NUM_SPS_EXTENSION_FLAGS; i++)
02096     {
02097       READ_FLAG( uiCode, syntaxStrings[i] );
02098       sps_extension_flags[i] = uiCode!=0;
02099     }
02100 
02101     bool bSkipTrailingExtensionBits=false;
02102     for(int i=0; i<NUM_SPS_EXTENSION_FLAGS; i++) // loop used so that the order is determined by the enum.
02103     {
02104       if (sps_extension_flags[i])
02105       {
02106         switch (SPSExtensionFlagIndex(i))
02107         {
02108         case SPS_EXT__REXT:
02109           CHECK(bSkipTrailingExtensionBits, "Skipping trailing extension bits not supported");
02110           {
02111             SPSRExt &spsRangeExtension = pcSPS->getSpsRangeExtension();
02112             READ_FLAG( uiCode, "transform_skip_rotation_enabled_flag");     spsRangeExtension.setTransformSkipRotationEnabledFlag(uiCode != 0);
02113             READ_FLAG( uiCode, "transform_skip_context_enabled_flag");      spsRangeExtension.setTransformSkipContextEnabledFlag (uiCode != 0);
02114             READ_FLAG( uiCode, "extended_precision_processing_flag");       spsRangeExtension.setExtendedPrecisionProcessingFlag (uiCode != 0);
02115             READ_FLAG( uiCode, "intra_smoothing_disabled_flag");            spsRangeExtension.setIntraSmoothingDisabledFlag      (uiCode != 0);
02116             READ_FLAG( uiCode, "high_precision_offsets_enabled_flag");      spsRangeExtension.setHighPrecisionOffsetsEnabledFlag (uiCode != 0);
02117             READ_FLAG( uiCode, "persistent_rice_adaptation_enabled_flag");  spsRangeExtension.setPersistentRiceAdaptationEnabledFlag (uiCode != 0);
02118             READ_FLAG( uiCode, "cabac_bypass_alignment_enabled_flag");      spsRangeExtension.setCabacBypassAlignmentEnabledFlag  (uiCode != 0);
02119           }
02120           break;
02121         default:
02122           bSkipTrailingExtensionBits=true;
02123           break;
02124         }
02125       }
02126     }
02127     if (bSkipTrailingExtensionBits)
02128     {
02129       while ( xMoreRbspData() )
02130       {
02131         READ_FLAG( uiCode, "sps_extension_data_flag");
02132       }
02133     }
02134   }
02135   xReadRbspTrailingBits();
02136 }
