02176 void HLSyntaxReader::parseDCI(DCI* dci)
02177 {
02178 #if ENABLE_TRACING
02179   xTraceDCIHeader();
02180 #endif
02181   uint32_t  symbol;
02182 
02183   READ_CODE(4, symbol, "dci_reserved_zero_4bits");
02184 
02185   uint32_t numPTLs;
02186   READ_CODE(4, numPTLs, "dci_num_ptls_minus1");
02187   numPTLs += 1;
02188 
02189   std::vector<ProfileTierLevel> ptls;
02190   ptls.resize(numPTLs);
02191   for (int i = 0; i < numPTLs; i++)
02192   {
02193     parseProfileTierLevel(&ptls[i], true, 0);
02194   }
02195   dci->setProfileTierLevel(ptls);
02196 
02197   READ_FLAG(symbol, "dci_extension_flag");
02198   if (symbol)
02199   {
02200     while (xMoreRbspData())
02201     {
02202       READ_FLAG(symbol, "dci_extension_data_flag");
02203     }
02204   }
02205   xReadRbspTrailingBits();
02206 }
02207 
02208 void HLSyntaxReader::parseVPS(VPS* pcVPS)
02209 {
02210 #if ENABLE_TRACING
02211   xTraceVPSHeader();
02212 #endif
02213   uint32_t  uiCode;
02214 
02215   READ_CODE(4, uiCode, "vps_video_parameter_set_id");
02216   CHECK( uiCode == 0, "vps_video_parameter_set_id equal to zero is reserved and shall not be used in a bitstream" );
02217   pcVPS->setVPSId(uiCode);
02218 
02219   READ_CODE(6, uiCode, "vps_max_layers_minus1");              pcVPS->setMaxLayers(uiCode + 1);    CHECK(uiCode + 1 > MAX_VPS_LAYERS, "Signalled number of layers larger than MAX_VPS_LAYERS.");
02220   if (pcVPS->getMaxLayers() - 1 == 0)
02221   {
02222     pcVPS->setEachLayerIsAnOlsFlag(1);
02223   }
02224   READ_CODE(3, uiCode, "vps_max_sublayers_minus1");           pcVPS->setMaxSubLayers(uiCode + 1); CHECK(uiCode + 1 > MAX_VPS_SUBLAYERS, "Signalled number of sublayers larger than MAX_VPS_SUBLAYERS.");
02225   if( pcVPS->getMaxLayers() > 1 && pcVPS->getMaxSubLayers() > 1)
02226   {
02227     READ_FLAG(uiCode, "vps_default_ptl_dpb_hrd_max_tid_flag"); pcVPS->setDefaultPtlDpbHrdMaxTidFlag(uiCode);
02228   }
02229   else
02230   {
02231     pcVPS->setDefaultPtlDpbHrdMaxTidFlag(1);
02232   }
02233   if( pcVPS->getMaxLayers() > 1 )
02234   {
02235     READ_FLAG(uiCode, "vps_all_independent_layers_flag");  pcVPS->setAllIndependentLayersFlag(uiCode);
02236     if (pcVPS->getAllIndependentLayersFlag() == 0)
02237     {
02238       pcVPS->setEachLayerIsAnOlsFlag(0);
02239     }
02240   }
02241 #if JVET_R0193
02242   std::vector<std::vector<uint32_t>> maxTidilRefPicsPlus1;
02243   maxTidilRefPicsPlus1.resize(pcVPS->getMaxLayers(), std::vector<uint32_t>(pcVPS->getMaxLayers(), NOT_VALID));
02244   pcVPS->setMaxTidIlRefPicsPlus1(maxTidilRefPicsPlus1);
02245 #endif
02246   for (uint32_t i = 0; i < pcVPS->getMaxLayers(); i++)
02247   {
02248     READ_CODE(6, uiCode, "vps_layer_id");                     pcVPS->setLayerId(i, uiCode);
02249     pcVPS->setGeneralLayerIdx(uiCode, i);
02250 
02251     if (i > 0 && !pcVPS->getAllIndependentLayersFlag())
02252     {
02253       READ_FLAG(uiCode, "vps_independent_layer_flag");     pcVPS->setIndependentLayerFlag(i, uiCode);
02254       if (!pcVPS->getIndependentLayerFlag(i))
02255       {
02256 #if JVET_R0193
02257         READ_FLAG(uiCode, "max_tid_ref_present_flag[ i ]");
02258         bool presentFlag = uiCode;
02259         uint16_t sumUiCode = 0;
02260         for (int j = 0, k = 0; j < i; j++)
02261         {
02262           READ_FLAG(uiCode, "vps_direct_ref_layer_flag"); pcVPS->setDirectRefLayerFlag(i, j, uiCode);
02263           if (uiCode)
02264           {
02265             pcVPS->setInterLayerRefIdc(i, j, k);
02266             pcVPS->setDirectRefLayerIdx(i, k++, j);
02267             sumUiCode++;
02268           }
02269           if (presentFlag && pcVPS->getDirectRefLayerFlag(i, j))
02270           {
02271             READ_CODE(3, uiCode, "max_tid_il_ref_pics_plus1[ i ][ j ]");
02272             pcVPS->setMaxTidIlRefPicsPlus1(i, j, uiCode);
02273           }
02274           else
02275           {
02276             pcVPS->setMaxTidIlRefPicsPlus1(i, j, 7);
02277           }
02278         }
02279         CHECK(sumUiCode == 0, "There has to be at least one value of j such that the value of vps_direct_dependency_flag[ i ][ j ] is equal to 1,when vps_independent_layer_flag[ i ] is equal to 0 ");
02280 #else
02281         uint16_t sumUiCode = 0;
02282         for (int j = 0, k = 0; j < i; j++)
02283         {
02284           READ_FLAG(uiCode, "vps_direct_dependency_flag"); pcVPS->setDirectRefLayerFlag(i, j, uiCode);
02285           if( uiCode )
02286           {
02287             pcVPS->setInterLayerRefIdc( i, j, k );
02288             pcVPS->setDirectRefLayerIdx( i, k++, j );
02289             sumUiCode++;
02290           }
02291         }
02292         CHECK(sumUiCode == 0, "There has to be at least one value of j such that the value of vps_direct_dependency_flag[ i ][ j ] is equal to 1,when vps_independent_layer_flag[ i ] is equal to 0 ");
02293         READ_FLAG(uiCode, "vps_max_tid_ref_present_flag[ i ]");
02294         if (uiCode)
02295         {
02296           READ_CODE(3, uiCode, "vps_max_tid_il_ref_pics_plus1[ i ]");
02297           pcVPS->setMaxTidIlRefPicsPlus1(i, uiCode);
02298         }
02299         else
02300         {
02301           pcVPS->setMaxTidIlRefPicsPlus1(i, 7);
02302         }
02303 #endif
02304       }
02305     }
02306   }
02307 
02308   if (pcVPS->getMaxLayers() > 1)
02309   {
02310     if (pcVPS->getAllIndependentLayersFlag())
02311     {
02312       READ_FLAG(uiCode, "vps_each_layer_is_an_ols_flag");  pcVPS->setEachLayerIsAnOlsFlag(uiCode);
02313       if (pcVPS->getEachLayerIsAnOlsFlag() == 0)
02314       {
02315         pcVPS->setOlsModeIdc(2);
02316       }
02317     }
02318     if (!pcVPS->getEachLayerIsAnOlsFlag())
02319     {
02320       if (!pcVPS->getAllIndependentLayersFlag())
02321       {
02322         READ_CODE(2, uiCode, "vps_ols_mode_idc");         pcVPS->setOlsModeIdc(uiCode); CHECK(uiCode > MAX_VPS_OLS_MODE_IDC, "vps_ols_mode_idc shall be in the range of 0 to 2");
02323       }
02324       if (pcVPS->getOlsModeIdc() == 2)
02325       {
02326         READ_CODE(8, uiCode, "vps_num_output_layer_sets_minus2");   pcVPS->setNumOutputLayerSets(uiCode + 2);
02327         for (uint32_t i = 1; i <= pcVPS->getNumOutputLayerSets() - 1; i++)
02328         {
02329           for (uint32_t j = 0; j < pcVPS->getMaxLayers(); j++)
02330           {
02331             READ_FLAG(uiCode, "vps_ols_output_layer_flag");        pcVPS->setOlsOutputLayerFlag(i, j, uiCode);
02332           }
02333         }
02334       }
02335     }
02336     READ_CODE(8, uiCode, "vps_num_ptls_minus1");      pcVPS->setNumPtls(uiCode + 1);
02337   }
02338   else
02339   {
02340     pcVPS->setNumPtls(1);
02341   }
02342   pcVPS->deriveOutputLayerSets();
02343   CHECK( uiCode >= pcVPS->getTotalNumOLSs(),"The value of vps_num_ptls_minus1 shall be less than TotalNumOlss");
02344   std::vector<bool> isPTLReferred( pcVPS->getNumPtls(), false);
02345 
02346   for (int i = 0; i < pcVPS->getNumPtls(); i++)
02347   {
02348     if(i > 0)
02349     {
02350       READ_FLAG(uiCode, "vps_pt_present_flag");
02351       pcVPS->setPtPresentFlag(i, uiCode);
02352     }
02353     else
02354       pcVPS->setPtPresentFlag(0, 1);
02355     if (!pcVPS->getDefaultPtlDpbHrdMaxTidFlag())
02356     {
02357       READ_CODE(3, uiCode, "vps_ptl_max_tid");
02358       pcVPS->setPtlMaxTemporalId(i, uiCode);
02359     }
02360     else
02361     {
02362       pcVPS->setPtlMaxTemporalId(i, pcVPS->getMaxSubLayers() - 1);
02363     }
02364   }
02365   int cnt = 0;
02366   while (m_pcBitstream->getNumBitsUntilByteAligned())
02367   {
02368     READ_FLAG( uiCode, "vps_ptl_reserved_zero_bit");
02369     CHECK(uiCode!=0, "Alignment bit is not '0'");
02370     cnt++;
02371   }
02372   CHECK(cnt >= 8, "Read more than '8' alignment bits");
02373   std::vector<ProfileTierLevel> ptls;
02374   ptls.resize(pcVPS->getNumPtls());
02375   for (int i = 0; i < pcVPS->getNumPtls(); i++)
02376   {
02377     parseProfileTierLevel(&ptls[i], pcVPS->getPtPresentFlag(i), pcVPS->getPtlMaxTemporalId(i) - 1);
02378   }
02379   pcVPS->setProfileTierLevel(ptls);
02380   for (int i = 0; i < pcVPS->getTotalNumOLSs(); i++)
02381   {
02382     if (pcVPS->getNumPtls() > 1 && pcVPS->getNumPtls() != pcVPS->getTotalNumOLSs())
02383     {
02384       READ_CODE(8, uiCode, "vps_ols_ptl_idx");
02385       pcVPS->setOlsPtlIdx(i, uiCode);
02386     }
02387     else if (pcVPS->getNumPtls() == pcVPS->getTotalNumOLSs())
02388     {
02389       pcVPS->setOlsPtlIdx(i, i);
02390     }
02391     else
02392       pcVPS->setOlsPtlIdx(i, 0);
02393     isPTLReferred[pcVPS->getOlsPtlIdx(i)] = true;
02394   }
02395   for( int i = 0; i < pcVPS->getNumPtls(); i++ )
02396   {
02397     CHECK( !isPTLReferred[i],"Each profile_tier_level( ) syntax structure in the VPS shall be referred to by at least one value of vps_ols_ptl_idx[ i ] for i in the range of 0 to TotalNumOlss ? 1, inclusive");
02398   }
02399 
02400   if( !pcVPS->getEachLayerIsAnOlsFlag() )
02401   {
02402     READ_UVLC( uiCode, "vps_num_dpb_params_minus1" ); pcVPS->m_numDpbParams = uiCode + 1;
02403 
02404     CHECK( pcVPS->m_numDpbParams > pcVPS->getNumMultiLayeredOlss(),"The value of vps_num_dpb_params_minus1 shall be in the range of 0 to NumMultiLayerOlss - 1, inclusive");
02405     std::vector<bool> isDPBParamReferred(pcVPS->m_numDpbParams, false);
02406 
02407     if( pcVPS->m_numDpbParams > 0 && pcVPS->getMaxSubLayers() > 1 )
02408     {
02409       READ_FLAG( uiCode, "vps_sublayer_dpb_params_present_flag" ); pcVPS->m_sublayerDpbParamsPresentFlag = uiCode;
02410     }
02411 
02412     pcVPS->m_dpbParameters.resize( pcVPS->m_numDpbParams );
02413 
02414     for( int i = 0; i < pcVPS->m_numDpbParams; i++ )
02415     {
02416       if (!pcVPS->getDefaultPtlDpbHrdMaxTidFlag())
02417       {
02418         READ_CODE(3, uiCode, "vps_dpb_max_tid[i]");
02419         pcVPS->m_dpbMaxTemporalId.push_back(uiCode);
02420         CHECK (uiCode > (pcVPS->getMaxSubLayers() - 1), "The value of vps_dpb_max_tid[i] shall be in the range of 0 to vps_max_sublayers_minus1, inclusive." )
02421       }
02422       else
02423       {
02424         pcVPS->m_dpbMaxTemporalId.push_back(pcVPS->getMaxSubLayers() - 1);
02425       }
02426 
02427       for( int j = ( pcVPS->m_sublayerDpbParamsPresentFlag ? 0 : pcVPS->m_dpbMaxTemporalId[i] ); j <= pcVPS->m_dpbMaxTemporalId[i]; j++ )
02428       {
02429         READ_UVLC(uiCode, "dpb_max_dec_pic_buffering_minus1[i]");
02430         pcVPS->m_dpbParameters[i].m_maxDecPicBuffering[j] = uiCode + 1;
02431         READ_UVLC( uiCode, "dpb_max_num_reorder_pics[i]" );          pcVPS->m_dpbParameters[i].m_maxNumReorderPics[j] = uiCode;
02432         READ_UVLC( uiCode, "dpb_max_latency_increase_plus1[i]" );    pcVPS->m_dpbParameters[i].m_maxLatencyIncreasePlus1[j] = uiCode;
02433       }
02434 
02435       for( int j = ( pcVPS->m_sublayerDpbParamsPresentFlag ? pcVPS->m_dpbMaxTemporalId[i] : 0 ); j < pcVPS->m_dpbMaxTemporalId[i]; j++ )
02436       {
02437         // When dpb_max_dec_pic_buffering_minus1[ i ] is not present for i in the range of 0 to maxSubLayersMinus1 - 1, inclusive, due to subLayerInfoFlag being equal to 0, it is inferred to be equal to dpb_max_dec_pic_buffering_minus1[ maxSubLayersMinus1 ].
02438         pcVPS->m_dpbParameters[i].m_maxDecPicBuffering[j] = pcVPS->m_dpbParameters[i].m_maxDecPicBuffering[pcVPS->m_dpbMaxTemporalId[i]];
02439 
02440         // When dpb_max_num_reorder_pics[ i ] is not present for i in the range of 0 to maxSubLayersMinus1 - 1, inclusive, due to subLayerInfoFlag being equal to 0, it is inferred to be equal to dpb_max_num_reorder_pics[ maxSubLayersMinus1 ].
02441         pcVPS->m_dpbParameters[i].m_maxNumReorderPics[j] = pcVPS->m_dpbParameters[i].m_maxNumReorderPics[pcVPS->m_dpbMaxTemporalId[i]];
02442 
02443         // When dpb_max_latency_increase_plus1[ i ] is not present for i in the range of 0 to maxSubLayersMinus1 - 1, inclusive, due to subLayerInfoFlag being equal to 0, it is inferred to be equal to dpb_max_latency_increase_plus1[ maxSubLayersMinus1 ].
02444         pcVPS->m_dpbParameters[i].m_maxLatencyIncreasePlus1[j] = pcVPS->m_dpbParameters[i].m_maxLatencyIncreasePlus1[pcVPS->m_dpbMaxTemporalId[i]];
02445       }
02446     }
02447 
02448 
02449     for( int i = 0, j=0; i < pcVPS->getTotalNumOLSs(); i++ )
02450     {
02451       if( pcVPS->m_numLayersInOls[i] > 1 )
02452       {
02453         READ_UVLC( uiCode, "vps_ols_dpb_pic_width[i]" ); pcVPS->setOlsDpbPicWidth( i, uiCode );
02454         READ_UVLC( uiCode, "vps_ols_dpb_pic_height[i]" ); pcVPS->setOlsDpbPicHeight( i, uiCode );
02455         READ_CODE( 2, uiCode, "vps_ols_dpb_chroma_format[i]"); pcVPS->setOlsDpbChromaFormatIdc(i, uiCode);
02456         READ_UVLC( uiCode, "vps_ols_dpb_bitdepth_minus8[i]"); pcVPS->setOlsDpbBitDepthMinus8(i, uiCode);
02457         const Profile::Name profile = pcVPS->getProfileTierLevel(pcVPS->getOlsPtlIdx(i)).getProfileIdc();
02458         if (profile != Profile::NONE)
02459         {
02460           CHECK(uiCode + 8 > ProfileFeatures::getProfileFeatures(profile)->maxBitDepth, "vps_ols_dpb_bitdepth_minus8[ i ] exceeds range supported by signalled profile");
02461         }
02462         if ((pcVPS->m_numDpbParams > 1) && (pcVPS->m_numDpbParams != pcVPS->m_numMultiLayeredOlss))
02463         {
02464           READ_UVLC( uiCode, "vps_ols_dpb_params_idx[i]" ); pcVPS->setOlsDpbParamsIdx( i, uiCode );
02465         }
02466         else if (pcVPS->m_numDpbParams == 1)
02467         {
02468           pcVPS->setOlsDpbParamsIdx(i, 0);
02469         }
02470         else
02471         {
02472           pcVPS->setOlsDpbParamsIdx(i, j);
02473         }
02474         j += 1;
02475         isDPBParamReferred[pcVPS->getOlsDpbParamsIdx(i)] = true;
02476       }
02477     }
02478     for( int i = 0; i < pcVPS->m_numDpbParams; i++ )
02479     {
02480       CHECK( !isDPBParamReferred[i],"Each dpb_parameters( ) syntax structure in the VPS shall be referred to by at least one value of vps_ols_dpb_params_idx[i] for i in the range of 0 to NumMultiLayerOlss - 1, inclusive");
02481     }
02482   }
02483 
02484   if (!pcVPS->getEachLayerIsAnOlsFlag())
02485   {
02486     READ_FLAG(uiCode, "vps_general_hrd_params_present_flag");  pcVPS->setVPSGeneralHrdParamsPresentFlag(uiCode);
02487   }
02488   if (pcVPS->getVPSGeneralHrdParamsPresentFlag())
02489   {
02490     parseGeneralHrdParameters(pcVPS->getGeneralHrdParameters());
02491     if ((pcVPS->getMaxSubLayers() - 1) > 0)
02492     {
02493       READ_FLAG(uiCode, "vps_sublayer_cpb_params_present_flag");  pcVPS->setVPSSublayerCpbParamsPresentFlag(uiCode);
02494     }
02495     else
02496     {
02497       pcVPS->setVPSSublayerCpbParamsPresentFlag(0);
02498     }
02499     READ_UVLC(uiCode, "vps_num_ols_timing_hrd_params_minus1"); pcVPS->setNumOlsTimingHrdParamsMinus1(uiCode);
02500     CHECK( uiCode >= pcVPS->getNumMultiLayeredOlss(),"The value of vps_num_ols_timing_hrd_params_minus1 shall be in the range of 0 to NumMultiLayerOlss - 1, inclusive");
02501     std::vector<bool> isHRDParamReferred( uiCode + 1, false);
02502     pcVPS->m_olsHrdParams.clear();
02503     pcVPS->m_olsHrdParams.resize(pcVPS->getNumOlsTimingHrdParamsMinus1(), std::vector<OlsHrdParams>(pcVPS->getMaxSubLayers()));
02504     for (int i = 0; i <= pcVPS->getNumOlsTimingHrdParamsMinus1(); i++)
02505     {
02506       if (!pcVPS->getDefaultPtlDpbHrdMaxTidFlag())
02507       {
02508         READ_CODE(3, uiCode, "vps_hrd_max_tid[i]");  pcVPS->setHrdMaxTid(i, uiCode);
02509         CHECK (uiCode > (pcVPS->getMaxSubLayers() - 1), "The value of vps_hrd_max_tid[i] shall be in the range of 0 to vps_max_sublayers_minus1, inclusive." )
02510       }
02511       else
02512       {
02513         pcVPS->setHrdMaxTid(i, pcVPS->getMaxSubLayers() - 1);
02514       }
02515       uint32_t firstSublayer = pcVPS->getVPSSublayerCpbParamsPresentFlag() ? 0 : pcVPS->getHrdMaxTid(i);
02516       parseOlsHrdParameters(pcVPS->getGeneralHrdParameters(),pcVPS->getOlsHrdParameters(i), firstSublayer, pcVPS->getHrdMaxTid(i));
02517     }
02518     for (int i = pcVPS->getNumOlsTimingHrdParamsMinus1() + 1; i < pcVPS->getTotalNumOLSs(); i++)
02519     {
02520       pcVPS->setHrdMaxTid(i, pcVPS->getMaxSubLayers() - 1);
02521     }
02522     for (int i = 0; i < pcVPS->m_numMultiLayeredOlss; i++)
02523     {
02524       if (((pcVPS->getNumOlsTimingHrdParamsMinus1() + 1) != pcVPS->m_numMultiLayeredOlss) && (pcVPS->getNumOlsTimingHrdParamsMinus1() > 0))
02525       {
02526         READ_UVLC(uiCode, "vps_ols_timing_hrd_idx[i]"); pcVPS->setOlsTimingHrdIdx(i, uiCode);
02527         CHECK(uiCode > pcVPS->getNumOlsTimingHrdParamsMinus1(), "The value of vps_ols_timing_hrd_idx[[ i ] shall be in the range of 0 to vps_num_ols_timing_hrd_params_minus1, inclusive.");
02528       }
02529       else if (pcVPS->getNumOlsTimingHrdParamsMinus1() == 0)
02530       {
02531         pcVPS->setOlsTimingHrdIdx(i, 0);
02532       }
02533       else
02534       {
02535         pcVPS->setOlsTimingHrdIdx(i, i);
02536       }
02537       isHRDParamReferred[pcVPS->getOlsTimingHrdIdx(i)] = true;
02538     }
02539     for( int i = 0; i <= pcVPS->getNumOlsTimingHrdParamsMinus1(); i++ )
02540     {
02541       CHECK( !isHRDParamReferred[i], "Each vps_ols_timing_hrd_parameters( ) syntax structure in the VPS shall be referred to by at least one value of vps_ols_timing_hrd_idx[ i ] for i in the range of 1 to NumMultiLayerOlss - 1, inclusive");
02542     }
02543   }
02544   else
02545   {
02546     for (int i = 0; i < pcVPS->getTotalNumOLSs(); i++)
02547     {
02548       pcVPS->setHrdMaxTid(i, pcVPS->getMaxSubLayers() - 1);
02549     }
02550   }
02551 
02552 
02553   READ_FLAG(uiCode, "vps_extension_flag");
02554   if (uiCode)
02555   {
02556     while (xMoreRbspData())
02557     {
02558       READ_FLAG(uiCode, "vps_extension_data_flag");
02559     }
02560   }
02561   pcVPS->checkVPS();
02562   xReadRbspTrailingBits();
02563 }
02564 
02565 void HLSyntaxReader::parsePictureHeader( PicHeader* picHeader, ParameterSetManager *parameterSetManager, bool readRbspTrailingBits )
02566 {
02567   uint32_t  uiCode;
02568   int       iCode;
02569   PPS*      pps = NULL;
02570   SPS*      sps = NULL;
02571 
02572 #if ENABLE_TRACING
02573   xTracePictureHeader();
02574 #endif
02575 
02576   READ_FLAG(uiCode, "ph_gdr_or_irap_pic_flag");               picHeader->setGdrOrIrapPicFlag(uiCode != 0);
02577   READ_FLAG(uiCode, "ph_non_ref_pic_flag");                picHeader->setNonReferencePictureFlag(uiCode != 0);
02578   if (picHeader->getGdrOrIrapPicFlag())
02579   {
02580     READ_FLAG(uiCode, "ph_gdr_pic_flag");                     picHeader->setGdrPicFlag(uiCode != 0);
02581   }
02582   else
02583   {
02584     picHeader->setGdrPicFlag(false);
02585   }
02586   READ_FLAG(uiCode, "ph_inter_slice_allowed_flag");       picHeader->setPicInterSliceAllowedFlag(uiCode != 0);
02587   if (picHeader->getPicInterSliceAllowedFlag())
02588   {
02589     READ_FLAG(uiCode, "ph_intra_slice_allowed_flag");       picHeader->setPicIntraSliceAllowedFlag(uiCode != 0);
02590   }
02591   else
02592   {
02593     picHeader->setPicIntraSliceAllowedFlag(true);
02594   }
02595   CHECK(picHeader->getPicInterSliceAllowedFlag() == 0 && picHeader->getPicIntraSliceAllowedFlag() == 0, "Invalid picture without intra or inter slice");
02596   // parameter sets
02597   READ_UVLC(uiCode, "ph_pic_parameter_set_id");
02598   picHeader->setPPSId(uiCode);
02599   pps = parameterSetManager->getPPS(picHeader->getPPSId());
02600   CHECK(pps == 0, "Invalid PPS");
02601   picHeader->setSPSId(pps->getSPSId());
02602   sps = parameterSetManager->getSPS(picHeader->getSPSId());
02603   CHECK(sps == 0, "Invalid SPS");
02604   READ_CODE(sps->getBitsForPOC(), uiCode, "ph_pic_order_cnt_lsb");
02605   picHeader->setPocLsb(uiCode);
02606   if( picHeader->getGdrPicFlag() )
02607   {
02608     READ_UVLC(uiCode, "ph_recovery_poc_cnt");               picHeader->setRecoveryPocCnt( uiCode );
02609   }
02610   else
02611   {
02612     picHeader->setRecoveryPocCnt( -1 );
02613   }
02614 
02615   std::vector<bool> phExtraBitsPresent = sps->getExtraPHBitPresentFlags();
02616   for (int i=0; i< sps->getNumExtraPHBytes() * 8; i++)
02617   {
02618     // extra bits are ignored (when present)
02619     if (phExtraBitsPresent[i])
02620     {
02621       READ_FLAG(uiCode, "ph_extra_bit[ i ]");
02622     }
02623   }
02624 
02625   if (sps->getPocMsbCycleFlag())
02626   {
02627     READ_FLAG(uiCode, "ph_poc_msb_present_flag"); picHeader->setPocMsbPresentFlag(uiCode != 0);
02628     if (picHeader->getPocMsbPresentFlag())
02629     {
02630       READ_CODE(sps->getPocMsbCycleLen(), uiCode, "ph_poc_msb_cycle_val");
02631       picHeader->setPocMsbVal(uiCode);
02632     }
02633   }
02634 
02635 
02636   // alf enable flags and aps IDs
02637   picHeader->setCcAlfEnabledFlag(COMPONENT_Cb, false);
02638   picHeader->setCcAlfEnabledFlag(COMPONENT_Cr, false);
02639   if (sps->getALFEnabledFlag())
02640   {
02641     if (pps->getAlfInfoInPhFlag())
02642     {
02643       READ_FLAG(uiCode, "ph_alf_enabled_flag");
02644       picHeader->setAlfEnabledFlag(COMPONENT_Y, uiCode);
02645 
02646       int alfCbEnabledFlag = 0;
02647       int alfCrEnabledFlag = 0;
02648       if (uiCode)
02649       {
02650         READ_CODE(3, uiCode, "ph_num_alf_aps_ids_luma");
02651         int numAps = uiCode;
02652         picHeader->setNumAlfAps(numAps);
02653 
02654         std::vector<int> apsId(numAps, -1);
02655         for (int i = 0; i < numAps; i++)
02656         {
02657           READ_CODE(3, uiCode, "ph_alf_aps_id_luma");
02658           apsId[i] = uiCode;
02659         }
02660         picHeader->setAlfAPSs(apsId);
02661 
02662         if (sps->getChromaFormatIdc() != CHROMA_400)
02663         {
02664           READ_CODE(1, uiCode, "ph_alf_cb_enabled_flag");   alfCbEnabledFlag = uiCode;
02665           READ_CODE(1, uiCode, "ph_alf_cr_enabled_flag");   alfCrEnabledFlag = uiCode;
02666         }
02667         else
02668         {
02669           alfCbEnabledFlag = 0;
02670           alfCrEnabledFlag = 0;
02671         }
02672         if (alfCbEnabledFlag || alfCrEnabledFlag)
02673         {
02674           READ_CODE(3, uiCode, "ph_alf_aps_id_chroma");
02675           picHeader->setAlfApsIdChroma(uiCode);
02676         }
02677         if (sps->getCCALFEnabledFlag())
02678         {
02679           READ_FLAG(uiCode, "ph_cc_alf_cb_enabled_flag");
02680           picHeader->setCcAlfEnabledFlag(COMPONENT_Cb, uiCode != 0);
02681           picHeader->setCcAlfCbApsId(-1);
02682           if (picHeader->getCcAlfEnabledFlag(COMPONENT_Cb))
02683           {
02684             // parse APS ID
02685             READ_CODE(3, uiCode, "ph_cc_alf_cb_aps_id");
02686             picHeader->setCcAlfCbApsId(uiCode);
02687           }
02688           // Cr
02689           READ_FLAG(uiCode, "ph_cc_alf_cr_enabled_flag");
02690           picHeader->setCcAlfEnabledFlag(COMPONENT_Cr, uiCode != 0);
02691           picHeader->setCcAlfCrApsId(-1);
02692           if (picHeader->getCcAlfEnabledFlag(COMPONENT_Cr))
02693           {
02694             // parse APS ID
02695             READ_CODE(3, uiCode, "ph_cc_alf_cr_aps_id");
02696             picHeader->setCcAlfCrApsId(uiCode);
02697           }
02698         }
02699       }
02700       else
02701       {
02702         picHeader->setNumAlfAps(0);
02703       }
