03173 
03174     // mvd L1 zero flag
03175     if (!pps->getRplInfoInPhFlag() || picHeader->getRPL(1)->getNumRefEntries() > 0)
03176     {
03177       READ_FLAG(uiCode, "ph_mvd_l1_zero_flag");
03178     }
03179     else
03180     {
03181       uiCode = 1;
03182     }
03183     picHeader->setMvdL1ZeroFlag(uiCode != 0);
03184 
03185     // picture level BDOF disable flags
03186     if (sps->getBdofControlPresentInPhFlag() && (!pps->getRplInfoInPhFlag() || picHeader->getRPL(1)->getNumRefEntries() > 0))
03187     {
03188       READ_FLAG(uiCode, "ph_bdof_disabled_flag");  picHeader->setBdofDisabledFlag(uiCode != 0);
03189     }
03190     else
03191     {
03192       if (sps->getBdofControlPresentInPhFlag() == 0)
03193       {
03194         picHeader->setBdofDisabledFlag(1 - (int)(sps->getBDOFEnabledFlag()));
03195       }
03196       else
03197       {
03198         picHeader->setBdofDisabledFlag(1);
03199       }
03200     }
03201 
03202   // picture level DMVR disable flags
03203     if (sps->getDmvrControlPresentInPhFlag() && (!pps->getRplInfoInPhFlag() || picHeader->getRPL(1)->getNumRefEntries() > 0))
03204     {
03205       READ_FLAG(uiCode, "ph_dmvr_disabled_flag");  picHeader->setDmvrDisabledFlag(uiCode != 0);
03206     }
03207     else
03208     {
03209       if (sps->getDmvrControlPresentInPhFlag() == 0)
03210       {
03211         picHeader->setDmvrDisabledFlag(1 - (int)(sps->getUseDMVR()));
03212       }
03213       else
03214       {
03215         picHeader->setDmvrDisabledFlag(1);
03216       }
03217     }
03218 
03219   // picture level PROF disable flags
03220     if (sps->getProfControlPresentInPhFlag())
03221     {
03222       READ_FLAG(uiCode, "ph_prof_disabled_flag");  picHeader->setProfDisabledFlag(uiCode != 0);
03223     }
03224     else
03225     {
03226       picHeader->setProfDisabledFlag(0);
03227     }
03228 
03229     if( (pps->getUseWP() || pps->getWPBiPred()) && pps->getWpInfoInPhFlag() )
03230     {
03231       parsePredWeightTable(picHeader, pps, sps);
03232     }
03233   }
03234   // inherit constraint values from SPS
03235   if (!sps->getSplitConsOverrideEnabledFlag() || !picHeader->getSplitConsOverrideFlag())
03236   {
03237     picHeader->setMinQTSizes(sps->getMinQTSizes());
03238     picHeader->setMaxMTTHierarchyDepths(sps->getMaxMTTHierarchyDepths());
03239     picHeader->setMaxBTSizes(sps->getMaxBTSizes());
03240     picHeader->setMaxTTSizes(sps->getMaxTTSizes());
03241   }
03242   else
03243   {
03244     picHeader->setMinQTSizes(minQT);
03245     picHeader->setMaxMTTHierarchyDepths(maxBTD);
03246     picHeader->setMaxBTSizes(maxBTSize);
03247     picHeader->setMaxTTSizes(maxTTSize);
03248   }
03249   // ibc merge candidate list size
03250   if (pps->getQpDeltaInfoInPhFlag())
03251   {
03252     int iCode = 0;
03253     READ_SVLC(iCode, "ph_qp_delta");
03254     picHeader->setQpDelta(iCode);
03255   }
03256 
03257   // joint Cb/Cr sign flag
03258   if (sps->getJointCbCrEnabledFlag())
03259   {
03260     READ_FLAG( uiCode, "ph_joint_cbcr_sign_flag" );
03261     picHeader->setJointCbCrSignFlag(uiCode != 0);
03262   }
03263   else
03264   {
03265     picHeader->setJointCbCrSignFlag(false);
03266   }
03267 
03268   // sao enable flags
03269   if(sps->getSAOEnabledFlag())
03270   {
03271     if (pps->getSaoInfoInPhFlag())
03272     {
03273       READ_FLAG(uiCode, "ph_sao_luma_enabled_flag");
03274       picHeader->setSaoEnabledFlag(CHANNEL_TYPE_LUMA, uiCode != 0);
03275 
03276       if (sps->getChromaFormatIdc() != CHROMA_400)
03277       {
03278         READ_FLAG(uiCode, "ph_sao_chroma_enabled_flag");
03279         picHeader->setSaoEnabledFlag(CHANNEL_TYPE_CHROMA, uiCode != 0);
03280       }
03281     }
03282     else
03283     {
03284       picHeader->setSaoEnabledFlag(CHANNEL_TYPE_LUMA,   true);
03285       picHeader->setSaoEnabledFlag(CHANNEL_TYPE_CHROMA, sps->getChromaFormatIdc() != CHROMA_400);
03286     }
03287   }
03288   else
03289   {
03290     picHeader->setSaoEnabledFlag(CHANNEL_TYPE_LUMA,   false);
03291     picHeader->setSaoEnabledFlag(CHANNEL_TYPE_CHROMA, false);
03292   }
03293 
03294 
03295 
03296   // deblocking filter controls
03297   if (pps->getDeblockingFilterControlPresentFlag())
03298   {
03299     if ( pps->getDbfInfoInPhFlag() )
03300     {
03301       READ_FLAG( uiCode, "ph_deblocking_params_present_flag" );
03302       picHeader->setDeblockingFilterOverrideFlag( uiCode != 0 );
03303     }
03304     else
03305     {
03306       picHeader->setDeblockingFilterOverrideFlag(false);
03307     }
03308 
03309     if(picHeader->getDeblockingFilterOverrideFlag())
03310     {
03311       if (!pps->getPPSDeblockingFilterDisabledFlag())
03312       {
03313         READ_FLAG(uiCode, "ph_deblocking_filter_disabled_flag");
03314         picHeader->setDeblockingFilterDisable(uiCode != 0);
03315       }
03316       else
03317       {
03318         picHeader->setDeblockingFilterDisable(false);
03319       }
03320       if (!picHeader->getDeblockingFilterDisable())
03321       {
03322         READ_SVLC( iCode, "ph_beta_offset_div2" );
03323         picHeader->setDeblockingFilterBetaOffsetDiv2(iCode);
03324         CHECK(  picHeader->getDeblockingFilterBetaOffsetDiv2() < -12 ||
03325                 picHeader->getDeblockingFilterBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration");
03326 
03327         READ_SVLC( iCode, "ph_tc_offset_div2" );
03328         picHeader->setDeblockingFilterTcOffsetDiv2(iCode);
03329         CHECK(  picHeader->getDeblockingFilterTcOffsetDiv2() < -12 ||
03330                 picHeader->getDeblockingFilterTcOffsetDiv2() > 12, "Invalid deblocking filter configuration");
03331 
03332         if( pps->getPPSChromaToolFlag() )
03333         {
03334           READ_SVLC( iCode, "ph_cb_beta_offset_div2" );
03335           picHeader->setDeblockingFilterCbBetaOffsetDiv2(iCode);
03336           CHECK(  picHeader->getDeblockingFilterCbBetaOffsetDiv2() < -12 ||
03337                   picHeader->getDeblockingFilterCbBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration");
03338 
03339           READ_SVLC( iCode, "ph_cb_tc_offset_div2" );
03340           picHeader->setDeblockingFilterCbTcOffsetDiv2(iCode);
03341           CHECK(  picHeader->getDeblockingFilterCbTcOffsetDiv2() < -12 ||
03342                   picHeader->getDeblockingFilterCbTcOffsetDiv2() > 12, "Invalid deblocking filter configuration");
03343 
03344           READ_SVLC( iCode, "ph_cr_beta_offset_div2" );
03345           picHeader->setDeblockingFilterCrBetaOffsetDiv2(iCode);
03346           CHECK(  picHeader->getDeblockingFilterCrBetaOffsetDiv2() < -12 ||
03347                   picHeader->getDeblockingFilterCrBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration");
03348 
03349           READ_SVLC( iCode, "ph_cr_tc_offset_div2" );
03350           picHeader->setDeblockingFilterCrTcOffsetDiv2(iCode);
03351           CHECK(  picHeader->getDeblockingFilterCrTcOffsetDiv2() < -12 ||
03352                   picHeader->getDeblockingFilterCrTcOffsetDiv2() > 12, "Invalid deblocking filter configuration");
03353         }
03354         else
03355         {
03356           picHeader->setDeblockingFilterCbBetaOffsetDiv2 ( picHeader->getDeblockingFilterBetaOffsetDiv2() );
03357           picHeader->setDeblockingFilterCbTcOffsetDiv2   ( picHeader->getDeblockingFilterTcOffsetDiv2()   );
03358           picHeader->setDeblockingFilterCrBetaOffsetDiv2 ( picHeader->getDeblockingFilterBetaOffsetDiv2() );
03359           picHeader->setDeblockingFilterCrTcOffsetDiv2   ( picHeader->getDeblockingFilterTcOffsetDiv2()   );
03360         }
03361       }
03362     }
03363     else
03364     {
03365       picHeader->setDeblockingFilterDisable       ( pps->getPPSDeblockingFilterDisabledFlag() );
03366       picHeader->setDeblockingFilterBetaOffsetDiv2( pps->getDeblockingFilterBetaOffsetDiv2() );
03367       picHeader->setDeblockingFilterTcOffsetDiv2  ( pps->getDeblockingFilterTcOffsetDiv2() );
03368       picHeader->setDeblockingFilterCbBetaOffsetDiv2( pps->getDeblockingFilterCbBetaOffsetDiv2() );
03369       picHeader->setDeblockingFilterCbTcOffsetDiv2  ( pps->getDeblockingFilterCbTcOffsetDiv2() );
03370       picHeader->setDeblockingFilterCrBetaOffsetDiv2( pps->getDeblockingFilterCrBetaOffsetDiv2() );
03371       picHeader->setDeblockingFilterCrTcOffsetDiv2  ( pps->getDeblockingFilterCrTcOffsetDiv2() );
03372     }
03373   }
03374   else
03375   {
03376     picHeader->setDeblockingFilterDisable       ( false );
03377     picHeader->setDeblockingFilterBetaOffsetDiv2( 0 );
03378     picHeader->setDeblockingFilterTcOffsetDiv2  ( 0 );
03379     picHeader->setDeblockingFilterCbBetaOffsetDiv2( 0 );
03380     picHeader->setDeblockingFilterCbTcOffsetDiv2  ( 0 );
03381     picHeader->setDeblockingFilterCrBetaOffsetDiv2(0);
03382     picHeader->setDeblockingFilterCrTcOffsetDiv2(0);
03383   }
03384 
03385 
03386   // picture header extension
03387   if(pps->getPictureHeaderExtensionPresentFlag())
03388   {
03389     READ_UVLC(uiCode,"ph_extension_length");
03390     for(int i=0; i<uiCode; i++)
03391     {
03392       uint32_t ignore_;
03393       READ_CODE(8,ignore_,"ph_extension_data_byte");
03394     }
03395   }
03396 
03397   if( readRbspTrailingBits )
03398   {
03399     xReadRbspTrailingBits();
03400   }
03401 }
03402 
03403 void  HLSyntaxReader::checkAlfNaluTidAndPicTid(Slice* pcSlice, PicHeader* picHeader, ParameterSetManager *parameterSetManager)
03404 {
03405   SPS* sps = parameterSetManager->getSPS(picHeader->getSPSId());
03406   PPS* pps = parameterSetManager->getPPS(picHeader->getPPSId());
03407   int curPicTid = pcSlice->getTLayer();
03408   APS* aps;
03409   const std::vector<int>&   apsId = picHeader->getAlfAPSs();
03410 
03411   if (sps->getALFEnabledFlag() && pps->getAlfInfoInPhFlag() && picHeader->getAlfEnabledFlag(COMPONENT_Y))
03412   {
03413     //luma
03414     for (int i = 0; i < picHeader->getNumAlfAps(); i++)
03415     {
03416       aps = parameterSetManager->getAPS(apsId[i], ALF_APS);
03417       CHECK(aps->getTemporalId() > curPicTid, "The TemporalId of the APS NAL unit having aps_params_type equal to ALF_APS and adaptation_parameter_set_id equal to ph_alf_aps_id_luma[ i ] shall be less than or equal to the TemporalId of the picture associated with the PH.");
03418       if( pcSlice->getNalUnitLayerId() != aps->getLayerId() )
03419       {
03420         CHECK( aps->getLayerId() > pcSlice->getNalUnitLayerId(), "Layer Id of APS cannot be greater than layer Id of VCL NAL unit the refer to it" );
03421         CHECK( pcSlice->getSPS()->getVPSId() == 0, "VPSId of the referred SPS cannot be 0 when layer Id of APS and layer Id of current slice are different" );
03422         for (int i = 0; i < pcSlice->getVPS()->getNumOutputLayerSets(); i++ )
03423         {
03424           bool isCurrLayerInOls = false;
03425           bool isRefLayerInOls = false;
03426           for( int j = pcSlice->getVPS()->getNumLayersInOls(i) - 1; j >= 0; j-- )
03427           {
03428             if( pcSlice->getVPS()->getLayerIdInOls(i, j) == pcSlice->getNalUnitLayerId() )
03429             {
03430               isCurrLayerInOls = true;
03431             }
03432             if( pcSlice->getVPS()->getLayerIdInOls(i, j) == aps->getLayerId() )
03433             {
03434               isRefLayerInOls = true;
03435             }
03436           }
03437           CHECK( isCurrLayerInOls && !isRefLayerInOls, "When VCL NAl unit in layer A refers to APS in layer B, all OLS that contains layer A shall also contains layer B" );
03438         }
03439       }
03440     }
03441     //chroma
03442     if (picHeader->getAlfEnabledFlag(COMPONENT_Cb) || picHeader->getAlfEnabledFlag(COMPONENT_Cr))
03443     {
03444       int chromaAlfApsId = picHeader->getAlfApsIdChroma();
03445       aps = parameterSetManager->getAPS(chromaAlfApsId, ALF_APS);
03446       CHECK(aps->getTemporalId() > curPicTid, "The TemporalId of the APS NAL unit having aps_params_type equal to ALF_APS and adaptation_parameter_set_id equal to ph_alf_aps_id_chroma shall be less than or equal to the TemporalId of the picture associated with the PH.");
03447       if( pcSlice->getNalUnitLayerId() != aps->getLayerId() )
03448       {
03449         CHECK( aps->getLayerId() > pcSlice->getNalUnitLayerId(), "Layer Id of APS cannot be greater than layer Id of VCL NAL unit the refer to it" );
03450         CHECK( pcSlice->getSPS()->getVPSId() == 0, "VPSId of the referred SPS cannot be 0 when layer Id of APS and layer Id of current slice are different" );
03451         for (int i = 0; i < pcSlice->getVPS()->getNumOutputLayerSets(); i++ )
03452         {
03453           bool isCurrLayerInOls = false;
03454           bool isRefLayerInOls = false;
03455           for( int j = pcSlice->getVPS()->getNumLayersInOls(i) - 1; j >= 0; j-- )
03456           {
03457             if( pcSlice->getVPS()->getLayerIdInOls(i, j) == pcSlice->getNalUnitLayerId() )
03458             {
03459               isCurrLayerInOls = true;
03460             }
03461             if( pcSlice->getVPS()->getLayerIdInOls(i, j) == aps->getLayerId() )
03462             {
03463               isRefLayerInOls = true;
03464             }
03465           }
03466           CHECK( isCurrLayerInOls && !isRefLayerInOls, "When VCL NAl unit in layer A refers to APS in layer B, all OLS that contains layer A shall also contains layer B" );
03467         }
03468       }
03469     }
03470   }
03471 }
03472 void HLSyntaxReader::parseSliceHeader (Slice* pcSlice, PicHeader* picHeader, ParameterSetManager *parameterSetManager, const int prevTid0POC, const int prevPicPOC)
03473 {
03474   uint32_t  uiCode;
03475   int   iCode;
03476 
03477 #if ENABLE_TRACING
03478   xTraceSliceHeader();
03479 #endif
03480   PPS* pps = NULL;
03481   SPS* sps = NULL;
03482   READ_FLAG(uiCode, "sh_picture_header_in_slice_header_flag");
03483   pcSlice->setPictureHeaderInSliceHeader(uiCode);
03484   if (uiCode)
03485   {
03486     parsePictureHeader(picHeader, parameterSetManager, false);
03487     picHeader->setValid();
03488   }
03489   CHECK(picHeader==0, "Invalid Picture Header");
03490   CHECK(picHeader->isValid()==false, "Invalid Picture Header");
03491   checkAlfNaluTidAndPicTid(pcSlice, picHeader, parameterSetManager);
03492   pps = parameterSetManager->getPPS( picHeader->getPPSId() );
03494   CHECK(pps==0, "Invalid PPS");
03495   sps = parameterSetManager->getSPS(pps->getSPSId());
03497   CHECK(sps==0, "Invalid SPS");
03498   if (sps->getProfileTierLevel()->getConstraintInfo()->getPicHeaderInSliceHeaderConstraintFlag())
03499   {
03500     CHECK(pcSlice->getPictureHeaderInSliceHeader() == false, "PH shall be present in SH, when pic_header_in_slice_header_constraint_flag is equal to 1");
03501   }
03502   CHECK(pcSlice->getPictureHeaderInSliceHeader() && pps->getRplInfoInPhFlag() == 1, "When sh_picture_header_in_slice_header_flag is equal to 1, rpl_info_in_ph_flag shall be equal to 0");
03503   CHECK(pcSlice->getPictureHeaderInSliceHeader() && pps->getDbfInfoInPhFlag() == 1, "When sh_picture_header_in_slice_header_flag is equal to 1, dbf_info_in_ph_flag shall be equal to 0");
03504   CHECK(pcSlice->getPictureHeaderInSliceHeader() && pps->getSaoInfoInPhFlag() == 1, "When sh_picture_header_in_slice_header_flag is equal to 1, sao_info_in_ph_flag shall be equal to 0");
03505   CHECK(pcSlice->getPictureHeaderInSliceHeader() && pps->getAlfInfoInPhFlag() == 1, "When sh_picture_header_in_slice_header_flag is equal to 1, alf_info_in_ph_flag shall be equal to 0");
03506   CHECK(pcSlice->getPictureHeaderInSliceHeader() && pps->getWpInfoInPhFlag() == 1, "When sh_picture_header_in_slice_header_flag is equal to 1, wp_info_in_ph_flag shall be equal to 0");
03507   CHECK(pcSlice->getPictureHeaderInSliceHeader() && pps->getQpDeltaInfoInPhFlag() == 1, "When sh_picture_header_in_slice_header_flag is equal to 1, qp_delta_info_in_ph_flag shall be equal to 0");
03508   CHECK(pcSlice->getPictureHeaderInSliceHeader() && sps->getSubPicInfoPresentFlag() == 1, "When sps_subpic_info_present_flag is equal to 1, the value of sh_picture_header_in_slice_header_flag shall be equal to 0");
03509   CHECK(sps->getSubPicInfoPresentFlag() == 1 && sps->getVirtualBoundariesEnabledFlag() == 1 && sps->getVirtualBoundariesPresentFlag() == 0,
03510         "when sps_subpic_info_present_flag is equal to 1 and sps_virtual_boundaries_enabled_flag is equal to 1, sps_virtual_boundaries_present_flag shall be equal 1");
03511 
03512   const ChromaFormat chFmt = sps->getChromaFormatIdc();
03513   const uint32_t numValidComp=getNumberValidComponents(chFmt);
03514   const bool bChroma=(chFmt!=CHROMA_400);
03515 
03516   // picture order count
03517   uiCode = picHeader->getPocLsb();
03518   int iPOClsb = uiCode;
03519   int iMaxPOClsb = 1 << sps->getBitsForPOC();
03520   int iPOCmsb;
03521   if (pcSlice->getIdrPicFlag())
03522   {
03523     if (picHeader->getPocMsbPresentFlag())
03524     {
03525       iPOCmsb = picHeader->getPocMsbVal()*iMaxPOClsb;
03526     }
03527     else
03528     {
03529       iPOCmsb = 0;
03530     }
03531     pcSlice->setPOC(iPOCmsb + iPOClsb);
03532   }
03533   else
03534   {
03535     int iPrevPOC = prevTid0POC;
03536     int iPrevPOClsb = iPrevPOC & (iMaxPOClsb - 1);
03537     int iPrevPOCmsb = iPrevPOC - iPrevPOClsb;
03538     if (picHeader->getPocMsbPresentFlag())
03539     {
03540       iPOCmsb = picHeader->getPocMsbVal()*iMaxPOClsb;
03541     }
03542     else
03543     {
03544       if ((iPOClsb < iPrevPOClsb) && ((iPrevPOClsb - iPOClsb) >= (iMaxPOClsb / 2)))
03545       {
03546         iPOCmsb = iPrevPOCmsb + iMaxPOClsb;
03547       }
03548       else if ((iPOClsb > iPrevPOClsb) && ((iPOClsb - iPrevPOClsb) > (iMaxPOClsb / 2)))
03549       {
03550         iPOCmsb = iPrevPOCmsb - iMaxPOClsb;
03551       }
03552       else
03553       {
03554         iPOCmsb = iPrevPOCmsb;
03555       }
03556     }
03557     pcSlice->setPOC(iPOCmsb + iPOClsb);
03558   }
03559 
03560   if (sps->getSubPicInfoPresentFlag())
03561   {
03562     uint32_t bitsSubPicId;
03563     bitsSubPicId = sps->getSubPicIdLen();
03564     READ_CODE(bitsSubPicId, uiCode, "sh_subpic_id");    pcSlice->setSliceSubPicId(uiCode);
03565   }
03566   else
03567   {
03568     pcSlice->setSliceSubPicId(0);
03569   }
03570 
03571   // raster scan slices
03572   uint32_t sliceAddr = 0;
03573   if(pps->getRectSliceFlag() == 0)
03574   {
03575     // slice address is the raster scan tile index of first tile in slice
03576     if( pps->getNumTiles() > 1 )
03577     {
03578       int bitsSliceAddress = ceilLog2(pps->getNumTiles());
03579       READ_CODE(bitsSliceAddress, uiCode, "sh_slice_address");  sliceAddr = uiCode;
03580     }
03581   }
03582   // rectangular slices
03583   else
03584   {
03585     // slice address is the index of the slice within the current sub-picture
03586     uint32_t currSubPicIdx = pps->getSubPicIdxFromSubPicId( pcSlice->getSliceSubPicId() );
03587     SubPic currSubPic = pps->getSubPic(currSubPicIdx);
03588     if( currSubPic.getNumSlicesInSubPic() > 1 )
03589     {
03590       int bitsSliceAddress = ceilLog2(currSubPic.getNumSlicesInSubPic());
03591       READ_CODE(bitsSliceAddress, uiCode, "sh_slice_address");  sliceAddr = uiCode;
03592       CHECK(sliceAddr >= currSubPic.getNumSlicesInSubPic(), "Invalid slice address");
03593     }
03594     uint32_t picLevelSliceIdx = sliceAddr;
03595     for(int subpic = 0; subpic < currSubPicIdx; subpic++)
03596     {
03597       picLevelSliceIdx += pps->getSubPic(subpic).getNumSlicesInSubPic();
03598     }
03599     pcSlice->setSliceMap( pps->getSliceMap(picLevelSliceIdx) );
03600     pcSlice->setSliceID(picLevelSliceIdx);
03601   }
03602 
03603   std::vector<bool> shExtraBitsPresent = sps->getExtraSHBitPresentFlags();
03604   for (int i=0; i< sps->getNumExtraSHBytes() * 8; i++)
03605   {
03606     // extra bits are ignored (when present)
03607     if (shExtraBitsPresent[i])
03608     {
03609       READ_FLAG(uiCode, "sh_extra_bit[ i ]");
03610     }
03611   }
03612 
03613   if(pps->getRectSliceFlag() == 0)
03614   {
03615     uint32_t numTilesInSlice = 1;
03616     if( pps->getNumTiles() > 1 )
03617     {
03618       if (((int)pps->getNumTiles() - (int)sliceAddr) > 1)
03619       {
03620         READ_UVLC(uiCode, "sh_num_tiles_in_slice_minus1");        numTilesInSlice = uiCode + 1;
03621       }
03622       if (!pps->getRectSliceFlag() && sps->getProfileTierLevel()->getConstraintInfo()->getOneSlicePerPicConstraintFlag())
03623       {
03624         CHECK(pps->getNumTiles() != uiCode + 1, "When pps_rect_slice_flag is equal to 0 and one_slice_per_pic_constraint_flag equal to 1, the value of sh_num_tiles_in_slice_minus1 present in each slice header shall be equal to NumTilesInPic - 1");
03625       }
03626     }
03627     CHECK(sliceAddr >= pps->getNumTiles(), "Invalid slice address");
03628     pcSlice->initSliceMap();
03629     pcSlice->setSliceID(sliceAddr);
03630 
03631     for( uint32_t tileIdx = sliceAddr; tileIdx < sliceAddr + numTilesInSlice; tileIdx++ )
03632     {
03633       uint32_t tileX = tileIdx % pps->getNumTileColumns();
03634       uint32_t tileY = tileIdx / pps->getNumTileColumns();
03635       CHECK(tileY >= pps->getNumTileRows(), "Number of tiles in slice exceeds the remaining number of tiles in picture");
03636 
03637       pcSlice->addCtusToSlice(pps->getTileColumnBd(tileX), pps->getTileColumnBd(tileX + 1),
03638                               pps->getTileRowBd(tileY), pps->getTileRowBd(tileY + 1), pps->getPicWidthInCtu());
03639    }
03640   }
03641 
03642   if (picHeader->getPicInterSliceAllowedFlag())
03643   {
03644     READ_UVLC (    uiCode, "sh_slice_type" );            pcSlice->setSliceType((SliceType)uiCode);
03645     VPS *vps = parameterSetManager->getVPS(sps->getVPSId());
03646     if (pcSlice->isIRAP() && (sps->getVPSId() == 0 || pcSlice->getPOC() != prevPicPOC || vps->getIndependentLayerFlag(vps->getGeneralLayerIdx(pcSlice->getNalUnitLayerId())) == 1))
03647     {
03648       CHECK(uiCode != 2, "When nal_unit_type is in the range of IDR_W_RADL to CRA_NUT, inclusive, and vps_independent_layer_flag[ GeneralLayerIdx[ nuh_layer_id ] ] is equal to 1 or the current picture is the first picture in the current AU, sh_slice_type shall be equal to 2");
03649     }
03650   }
03651   else
03652   {
03653     pcSlice->setSliceType(I_SLICE);
03654   }
03655   if (!picHeader->getPicIntraSliceAllowedFlag())
03656   {
