04167     if (sps->getSAOEnabledFlag() && !pps->getSaoInfoInPhFlag())
04168     {
04169       READ_FLAG(uiCode, "sh_sao_luma_used_flag");  pcSlice->setSaoEnabledFlag(CHANNEL_TYPE_LUMA, (bool)uiCode);
04170 
04171       if (bChroma)
04172       {
04173         READ_FLAG(uiCode, "sh_sao_chroma_used_flag");  pcSlice->setSaoEnabledFlag(CHANNEL_TYPE_CHROMA, (bool)uiCode);
04174       }
04175     }
04176 
04177 
04178     if (pps->getDeblockingFilterControlPresentFlag())
04179     {
04180       if (pps->getDeblockingFilterOverrideEnabledFlag() && !pps->getDbfInfoInPhFlag())
04181       {
04182         READ_FLAG ( uiCode, "sh_deblocking_params_present_flag" );        pcSlice->setDeblockingFilterOverrideFlag(uiCode ? true : false);
04183       }
04184       else
04185       {
04186         pcSlice->setDeblockingFilterOverrideFlag(0);
04187       }
04188       if(pcSlice->getDeblockingFilterOverrideFlag())
04189       {
04190         if (!pps->getPPSDeblockingFilterDisabledFlag())
04191         {
04192           READ_FLAG(uiCode, "sh_deblocking_filter_disabled_flag");   pcSlice->setDeblockingFilterDisable(uiCode ? 1 : 0);
04193         }
04194         else
04195         {
04196           pcSlice->setDeblockingFilterDisable(false);
04197         }
04198         if(!pcSlice->getDeblockingFilterDisable())
04199         {
04200           READ_SVLC( iCode, "sh_luma_beta_offset_div2" );                     pcSlice->setDeblockingFilterBetaOffsetDiv2( iCode );
04201           CHECK(  pcSlice->getDeblockingFilterBetaOffsetDiv2() < -12 ||
04202                   pcSlice->getDeblockingFilterBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration");
04203           READ_SVLC( iCode, "sh_luma_tc_offset_div2" );                       pcSlice->setDeblockingFilterTcOffsetDiv2( iCode );
04204           CHECK(  pcSlice->getDeblockingFilterTcOffsetDiv2() < -12 ||
04205                   pcSlice->getDeblockingFilterTcOffsetDiv2() > 12, "Invalid deblocking filter configuration");
04206 
04207           if( pps->getPPSChromaToolFlag() )
04208           {
04209             READ_SVLC( iCode, "sh_cb_beta_offset_div2" );                  pcSlice->setDeblockingFilterCbBetaOffsetDiv2( iCode );
04210             CHECK( pcSlice->getDeblockingFilterCbBetaOffsetDiv2() < -12 ||
04211               pcSlice->getDeblockingFilterCbBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
04212             READ_SVLC( iCode, "sh_cb_tc_offset_div2" );                    pcSlice->setDeblockingFilterCbTcOffsetDiv2( iCode );
04213             CHECK( pcSlice->getDeblockingFilterCbTcOffsetDiv2() < -12 ||
04214               pcSlice->getDeblockingFilterCbTcOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
04215 
04216             READ_SVLC( iCode, "sh_cr_beta_offset_div2" );                  pcSlice->setDeblockingFilterCrBetaOffsetDiv2( iCode );
04217             CHECK( pcSlice->getDeblockingFilterCrBetaOffsetDiv2() < -12 ||
04218               pcSlice->getDeblockingFilterCrBetaOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
04219             READ_SVLC( iCode, "sh_cr_tc_offset_div2" );                    pcSlice->setDeblockingFilterCrTcOffsetDiv2( iCode );
04220             CHECK( pcSlice->getDeblockingFilterCrTcOffsetDiv2() < -12 ||
04221               pcSlice->getDeblockingFilterCrTcOffsetDiv2() > 12, "Invalid deblocking filter configuration" );
04222           }
04223           else
04224           {
04225             pcSlice->setDeblockingFilterCbBetaOffsetDiv2 ( pcSlice->getDeblockingFilterBetaOffsetDiv2() );
04226             pcSlice->setDeblockingFilterCbTcOffsetDiv2   ( pcSlice->getDeblockingFilterTcOffsetDiv2()   );
04227             pcSlice->setDeblockingFilterCrBetaOffsetDiv2 ( pcSlice->getDeblockingFilterBetaOffsetDiv2() );
04228             pcSlice->setDeblockingFilterCrTcOffsetDiv2   ( pcSlice->getDeblockingFilterTcOffsetDiv2()   );
04229           }
04230         }
04231       }
04232       else
04233       {
04234         pcSlice->setDeblockingFilterDisable       ( picHeader->getDeblockingFilterDisable() );
04235         pcSlice->setDeblockingFilterBetaOffsetDiv2( picHeader->getDeblockingFilterBetaOffsetDiv2() );
04236         pcSlice->setDeblockingFilterTcOffsetDiv2  ( picHeader->getDeblockingFilterTcOffsetDiv2() );
04237         pcSlice->setDeblockingFilterCbBetaOffsetDiv2( picHeader->getDeblockingFilterCbBetaOffsetDiv2() );
04238         pcSlice->setDeblockingFilterCbTcOffsetDiv2  ( picHeader->getDeblockingFilterCbTcOffsetDiv2() );
04239         pcSlice->setDeblockingFilterCrBetaOffsetDiv2(picHeader->getDeblockingFilterCrBetaOffsetDiv2());
04240         pcSlice->setDeblockingFilterCrTcOffsetDiv2(picHeader->getDeblockingFilterCrTcOffsetDiv2());
04241       }
04242     }
04243     else
04244     {
04245       pcSlice->setDeblockingFilterDisable       ( false );
04246       pcSlice->setDeblockingFilterBetaOffsetDiv2( 0 );
04247       pcSlice->setDeblockingFilterTcOffsetDiv2  ( 0 );
04248       pcSlice->setDeblockingFilterCbBetaOffsetDiv2( 0 );
04249       pcSlice->setDeblockingFilterCbTcOffsetDiv2  ( 0 );
04250       pcSlice->setDeblockingFilterCrBetaOffsetDiv2( 0 );
04251       pcSlice->setDeblockingFilterCrTcOffsetDiv2  ( 0 );
04252     }
04253 
04254   // dependent quantization
04255   if( sps->getDepQuantEnabledFlag() )
04256   {
04257     READ_FLAG(uiCode, "sh_dep_quant_used_flag");
04258     pcSlice->setDepQuantEnabledFlag(uiCode != 0);
04259   }
04260   else
04261   {
04262     pcSlice->setDepQuantEnabledFlag(false);
04263   }
04264 
04265   // sign data hiding
04266   if( sps->getSignDataHidingEnabledFlag() && !pcSlice->getDepQuantEnabledFlag() )
04267   {
04268     READ_FLAG( uiCode, "sh_sign_data_hiding_used_flag" );
04269     pcSlice->setSignDataHidingEnabledFlag( uiCode != 0 );
04270   }
04271   else
04272   {
04273     pcSlice->setSignDataHidingEnabledFlag(false);
04274   }
04275 
04276   // signal TS residual coding disabled flag
04277   if (sps->getTransformSkipEnabledFlag() && !pcSlice->getDepQuantEnabledFlag() && !pcSlice->getSignDataHidingEnabledFlag())
04278   {
04279     READ_FLAG(uiCode, "sh_ts_residual_coding_disabled_flag");
04280     pcSlice->setTSResidualCodingDisabledFlag( uiCode != 0 );
04281   }
04282   else
04283   {
04284     pcSlice->setTSResidualCodingDisabledFlag( false );
04285   }
04286 
04287   if( pcSlice->getFirstCtuRsAddrInSlice() == 0 )
04288   {
04289     pcSlice->setDefaultClpRng( *sps );
04290 
04291   }
04292 
04293   if(pps->getSliceHeaderExtensionPresentFlag())
04294   {
04295     READ_UVLC(uiCode,"sh_slice_header_extension_length");
04296     for(int i=0; i<uiCode; i++)
04297     {
04298       uint32_t ignore_;
04299       READ_CODE(8,ignore_,"sh_slice_header_extension_data_byte");
04300     }
04301   }
04302 
04303   std::vector<uint32_t> entryPointOffset;
04304 
04305   pcSlice->resetNumberOfSubstream();
04306   pcSlice->setNumSubstream(sps, pps);
04307 
04308   pcSlice->setNumEntryPoints( sps, pps );
04309   if( pcSlice->getNumEntryPoints() > 0 )
04310   {
04311     uint32_t offsetLenMinus1;
04312     READ_UVLC( offsetLenMinus1, "sh_entry_offset_len_minus1" );
04313     entryPointOffset.resize( pcSlice->getNumEntryPoints() );
04314     for( uint32_t idx = 0; idx < pcSlice->getNumEntryPoints(); idx++ )
04315     {
04316       READ_CODE( offsetLenMinus1 + 1, uiCode, "sh_entry_point_offset_minus1" );
04317       entryPointOffset[idx] = uiCode + 1;
04318     }
04319   }
04320 
04321 #if RExt__DECODER_DEBUG_BIT_STATISTICS
04322   CodingStatistics::IncrementStatisticEP(STATS__BYTE_ALIGNMENT_BITS,m_pcBitstream->readByteAlignment(),0);
04323 #else
04324   m_pcBitstream->readByteAlignment();
04325 #endif
04326 
04327   pcSlice->clearSubstreamSizes();
04328 
04329   if( pcSlice->getNumEntryPoints() > 0 )
04330   {
04331     int endOfSliceHeaderLocation = m_pcBitstream->getByteLocation();
04332 
04333     // Adjust endOfSliceHeaderLocation to account for emulation prevention bytes in the slice segment header
04334     for ( uint32_t curByteIdx  = 0; curByteIdx<m_pcBitstream->numEmulationPreventionBytesRead(); curByteIdx++ )
04335     {
04336       if ( m_pcBitstream->getEmulationPreventionByteLocation( curByteIdx ) < endOfSliceHeaderLocation )
04337       {
04338         endOfSliceHeaderLocation++;
04339       }
04340     }
04341 
04342     int  curEntryPointOffset     = 0;
04343     int  prevEntryPointOffset    = 0;
04344     for (uint32_t idx=0; idx<entryPointOffset.size(); idx++)
04345     {
04346       curEntryPointOffset += entryPointOffset[ idx ];
04347 
04348       int emulationPreventionByteCount = 0;
04349       for ( uint32_t curByteIdx  = 0; curByteIdx<m_pcBitstream->numEmulationPreventionBytesRead(); curByteIdx++ )
04350       {
04351         if ( m_pcBitstream->getEmulationPreventionByteLocation( curByteIdx ) >= ( prevEntryPointOffset + endOfSliceHeaderLocation ) &&
04352              m_pcBitstream->getEmulationPreventionByteLocation( curByteIdx ) <  ( curEntryPointOffset  + endOfSliceHeaderLocation ) )
04353         {
04354           emulationPreventionByteCount++;
04355         }
04356       }
04357 
04358       entryPointOffset[ idx ] -= emulationPreventionByteCount;
04359       prevEntryPointOffset = curEntryPointOffset;
04360       pcSlice->addSubstreamSize(entryPointOffset [ idx ] );
04361     }
04362   }
04363   return;
04364 }
04365 
04366 void HLSyntaxReader::getSlicePoc(Slice* pcSlice, PicHeader* picHeader, ParameterSetManager *parameterSetManager, const int prevTid0POC)
04367 {
04368   uint32_t  uiCode;
04369   uint32_t  pocLsb;
04370   PPS* pps = NULL;
04371   SPS* sps = NULL;
04372 
04373   CHECK(picHeader==0, "Invalid Picture Header");
04374   CHECK(picHeader->isValid()==false, "Invalid Picture Header");
04375   pps = parameterSetManager->getPPS( picHeader->getPPSId() );
04377   CHECK(pps==0, "Invalid PPS");
04378   sps = parameterSetManager->getSPS(pps->getSPSId());
04380   CHECK(sps==0, "Invalid SPS");
04381 
04382   DTRACE_UPDATE( g_trace_ctx, std::make_pair( "final", 0 ) );
04383 
04384   READ_FLAG(uiCode, "sh_picture_header_in_slice_header_flag");
04385   if (uiCode == 0)
04386   {
04387     pocLsb = picHeader->getPocLsb();
04388   }
04389   else
04390   {
04391     uint32_t phGdrOrIrapPicFlag;
04392     READ_FLAG(phGdrOrIrapPicFlag, "ph_gdr_or_irap_pic_flag");
04393     READ_FLAG(uiCode, "ph_non_ref_pic_flag");
04394     if (phGdrOrIrapPicFlag)
04395     {
04396       READ_FLAG(uiCode, "ph_gdr_pic_flag");
04397     }
04398     READ_FLAG(uiCode, "ph_inter_slice_allowed_flag");
04399     if (uiCode)
04400     {
04401       READ_FLAG(uiCode, "ph_intra_slice_allowed_flag");
04402     }
04403     // parameter sets
04404     READ_UVLC(uiCode, "ph_pic_parameter_set_id");
04405     // picture order count
04406     READ_CODE(sps->getBitsForPOC(), pocLsb, "ph_pic_order_cnt_lsb");
04407   }
04408   int maxPocLsb = 1 << sps->getBitsForPOC();
04409   int pocMsb;
04410   if (pcSlice->getIdrPicFlag())
04411   {
04412     if (picHeader->getPocMsbPresentFlag())
04413     {
04414       pocMsb = picHeader->getPocMsbVal()*maxPocLsb;
04415     }
04416     else
04417     {
04418       pocMsb = 0;
04419     }
04420     pcSlice->setPOC(pocMsb + pocLsb);
04421   }
04422   else
04423   {
04424     int prevPoc = prevTid0POC;
04425     int prevPocLsb = prevPoc & (maxPocLsb - 1);
04426     int prevPocMsb = prevPoc - prevPocLsb;
04427     if (picHeader->getPocMsbPresentFlag())
04428     {
04429       pocMsb = picHeader->getPocMsbVal()*maxPocLsb;
04430     }
04431     else
04432     {
04433       if ((pocLsb < prevPocLsb) && ((prevPocLsb - pocLsb) >= (maxPocLsb / 2)))
04434       {
04435         pocMsb = prevPocMsb + maxPocLsb;
04436       }
04437       else if ((pocLsb > prevPocLsb) && ((pocLsb - prevPocLsb) > (maxPocLsb / 2)))
04438       {
04439         pocMsb = prevPocMsb - maxPocLsb;
04440       }
04441       else
04442       {
04443         pocMsb = prevPocMsb;
04444       }
04445     }
04446     pcSlice->setPOC(pocMsb + pocLsb);
04447   }
04448   DTRACE_UPDATE( g_trace_ctx, std::make_pair( "final", 1 ) );
04449 }
04450 
04451 void HLSyntaxReader::parseConstraintInfo(ConstraintInfo *cinfo)
04452 {
04453   uint32_t symbol;
04454   READ_FLAG(symbol, "gci_present_flag"); cinfo->setGciPresentFlag(symbol ? true : false);
04455   if (cinfo->getGciPresentFlag())
04456   {
04457     /* general */
04458     READ_FLAG(symbol, "gci_intra_only_constraint_flag");                 cinfo->setIntraOnlyConstraintFlag(symbol ? true : false);
04459     READ_FLAG(symbol, "gci_all_layers_independent_constraint_flag");     cinfo->setAllLayersIndependentConstraintFlag(symbol ? true : false);
04460     READ_FLAG(symbol, "gci_one_au_only_constraint_flag");                cinfo->setOnePictureOnlyConstraintFlag(symbol ? true : false); 
04461 
04462     /* picture format */
04463     READ_CODE(4, symbol, "gci_sixteen_minus_max_bitdepth_constraint_idc"); cinfo->setMaxBitDepthConstraintIdc(symbol>8 ? 16 : (16 - symbol));
04464     CHECK(symbol>8, "gci_sixteen_minus_max_bitdepth_constraint_idc shall be in the range 0 to 8, inclusive");
04465     READ_CODE(2, symbol, "gci_three_minus_max_chroma_format_constraint_idc"); cinfo->setMaxChromaFormatConstraintIdc((ChromaFormat)(3 - symbol));
04466 
04467     /* NAL unit type related */
04468     READ_FLAG(symbol, "gci_no_mixed_nalu_types_in_pic_constraint_flag"); cinfo->setNoMixedNaluTypesInPicConstraintFlag(symbol > 0 ? true : false);
04469     READ_FLAG(symbol, "gci_no_trail_constraint_flag");                   cinfo->setNoTrailConstraintFlag(symbol > 0 ? true : false);
04470     READ_FLAG(symbol, "gci_no_stsa_constraint_flag");                    cinfo->setNoStsaConstraintFlag(symbol > 0 ? true : false);
04471     READ_FLAG(symbol, "gci_no_rasl_constraint_flag");                    cinfo->setNoRaslConstraintFlag(symbol > 0 ? true : false);
04472     READ_FLAG(symbol, "gci_no_radl_constraint_flag");                    cinfo->setNoRadlConstraintFlag(symbol > 0 ? true : false);
04473     READ_FLAG(symbol, "gci_no_idr_constraint_flag");                     cinfo->setNoIdrConstraintFlag(symbol > 0 ? true : false);
04474     READ_FLAG(symbol, "gci_no_cra_constraint_flag");                     cinfo->setNoCraConstraintFlag(symbol > 0 ? true : false);
04475     READ_FLAG(symbol, "gci_no_gdr_constraint_flag");                     cinfo->setNoGdrConstraintFlag(symbol > 0 ? true : false);
04476     READ_FLAG(symbol, "gci_no_aps_constraint_flag");                     cinfo->setNoApsConstraintFlag(symbol > 0 ? true : false);
04477     READ_FLAG(symbol, "gci_no_idr_rpl_constraint_flag");                 cinfo->setNoIdrRplConstraintFlag(symbol > 0 ? true : false);
04478 
04479     /* tile, slice, subpicture partitioning */
04480     READ_FLAG(symbol, "gci_one_tile_per_pic_constraint_flag");           cinfo->setOneTilePerPicConstraintFlag(symbol > 0 ? true : false);
04481     READ_FLAG(symbol, "gci_pic_header_in_slice_header_constraint_flag"); cinfo->setPicHeaderInSliceHeaderConstraintFlag(symbol > 0 ? true : false);
04482     READ_FLAG(symbol, "gci_one_slice_per_pic_constraint_flag");          cinfo->setOneSlicePerPicConstraintFlag(symbol > 0 ? true : false);
04483     READ_FLAG(symbol, "gci_no_rectangular_slice_constraint_flag");       cinfo->setNoRectSliceConstraintFlag(symbol > 0 ? true : false);
04484     READ_FLAG(symbol, "gci_one_slice_per_subpic_constraint_flag");       cinfo->setOneSlicePerSubpicConstraintFlag(symbol > 0 ? true : false);
04485     READ_FLAG(symbol, "gci_no_subpic_info_constraint_flag");             cinfo->setNoSubpicInfoConstraintFlag(symbol > 0 ? true : false);
04486 
04487     /* CTU and block partitioning */
04488     READ_CODE(2, symbol, "gci_three_minus_max_log2_ctu_size_constraint_idc");   cinfo->setMaxLog2CtuSizeConstraintIdc(((3 - symbol) + 5));
04489     READ_FLAG(symbol, "gci_no_partition_constraints_override_constraint_flag"); cinfo->setNoPartitionConstraintsOverrideConstraintFlag(symbol > 0 ? true : false);
04490     READ_FLAG(symbol, "gci_no_mtt_constraint_flag");                            cinfo->setNoMttConstraintFlag(symbol > 0 ? true : false);
04491     READ_FLAG(symbol, "gci_no_qtbtt_dual_tree_intra_constraint_flag");          cinfo->setNoQtbttDualTreeIntraConstraintFlag(symbol > 0 ? true : false);
04492 
04493     /* intra */
04494     READ_FLAG(symbol, "gci_no_palette_constraint_flag");                 cinfo->setNoPaletteConstraintFlag(symbol > 0 ? true : false);
04495     READ_FLAG(symbol, "gci_no_ibc_constraint_flag");                     cinfo->setNoIbcConstraintFlag(symbol > 0 ? true : false);
04496     READ_FLAG(symbol, "gci_no_isp_constraint_flag");                     cinfo->setNoIspConstraintFlag(symbol > 0 ? true : false);
04497     READ_FLAG(symbol, "gci_no_mrl_constraint_flag");                     cinfo->setNoMrlConstraintFlag(symbol > 0 ? true : false);
04498     READ_FLAG(symbol, "gci_no_mip_constraint_flag");                     cinfo->setNoMipConstraintFlag(symbol > 0 ? true : false);
04499     READ_FLAG(symbol, "gci_no_cclm_constraint_flag");                    cinfo->setNoCclmConstraintFlag(symbol > 0 ? true : false);
04500 
04501     /* inter */
04502     READ_FLAG(symbol, "gci_no_ref_pic_resampling_constraint_flag");      cinfo->setNoRprConstraintFlag(symbol > 0 ? true : false);
04503     READ_FLAG(symbol, "gci_no_res_change_in_clvs_constraint_flag");      cinfo->setNoResChangeInClvsConstraintFlag(symbol > 0 ? true : false);
04504     READ_FLAG(symbol, "gci_no_weighted_prediction_constraint_flag");     cinfo->setNoWeightedPredictionConstraintFlag(symbol > 0 ? true : false);
04505     READ_FLAG(symbol, "gci_no_ref_wraparound_constraint_flag");          cinfo->setNoRefWraparoundConstraintFlag(symbol > 0 ? true : false);
04506     READ_FLAG(symbol, "gci_no_temporal_mvp_constraint_flag");            cinfo->setNoTemporalMvpConstraintFlag(symbol > 0 ? true : false);
04507     READ_FLAG(symbol, "gci_no_sbtmvp_constraint_flag");                  cinfo->setNoSbtmvpConstraintFlag(symbol > 0 ? true : false);
04508     READ_FLAG(symbol, "gci_no_amvr_constraint_flag");                    cinfo->setNoAmvrConstraintFlag(symbol > 0 ? true : false);
04509     READ_FLAG(symbol, "gci_no_bdof_constraint_flag");                    cinfo->setNoBdofConstraintFlag(symbol > 0 ? true : false);
04510     READ_FLAG(symbol, "gci_no_smvd_constraint_flag");                    cinfo->setNoSmvdConstraintFlag(symbol > 0 ? true : false);
04511     READ_FLAG(symbol, "gci_no_dmvr_constraint_flag");                    cinfo->setNoDmvrConstraintFlag(symbol > 0 ? true : false);
04512     READ_FLAG(symbol, "gci_no_mmvd_constraint_flag");                    cinfo->setNoMmvdConstraintFlag(symbol > 0 ? true : false);
04513     READ_FLAG(symbol, "gci_no_affine_motion_constraint_flag");           cinfo->setNoAffineMotionConstraintFlag(symbol > 0 ? true : false);
04514     READ_FLAG(symbol, "gci_no_prof_constraint_flag");                    cinfo->setNoProfConstraintFlag(symbol > 0 ? true : false);
04515     READ_FLAG(symbol, "gci_no_bcw_constraint_flag");                     cinfo->setNoBcwConstraintFlag(symbol > 0 ? true : false);
04516     READ_FLAG(symbol, "gci_no_ciip_constraint_flag");                    cinfo->setNoCiipConstraintFlag(symbol > 0 ? true : false);
04517     READ_FLAG(symbol, "gci_no_gpm_constraint_flag");                     cinfo->setNoGeoConstraintFlag(symbol > 0 ? true : false);
04518 
04519     /* transform, quantization, residual */
04520     READ_FLAG(symbol, "gci_no_luma_transform_size_64_constraint_flag");  cinfo->setNoLumaTransformSize64ConstraintFlag(symbol > 0 ? true : false);
04521     READ_FLAG(symbol, "gci_no_transform_skip_constraint_flag");          cinfo->setNoTransformSkipConstraintFlag(symbol > 0 ? true : false);
04522     READ_FLAG(symbol, "gci_no_bdpcm_constraint_flag");                   cinfo->setNoBDPCMConstraintFlag(symbol > 0 ? true : false);
04523     READ_FLAG(symbol, "gci_no_mts_constraint_flag");                     cinfo->setNoMtsConstraintFlag(symbol > 0 ? true : false);
04524     READ_FLAG(symbol, "gci_no_lfnst_constraint_flag");                   cinfo->setNoLfnstConstraintFlag(symbol > 0 ? true : false);
04525     READ_FLAG(symbol, "gci_no_joint_cbcr_constraint_flag");              cinfo->setNoJointCbCrConstraintFlag(symbol > 0 ? true : false);
04526     READ_FLAG(symbol, "gci_no_sbt_constraint_flag");                     cinfo->setNoSbtConstraintFlag(symbol > 0 ? true : false);
04527     READ_FLAG(symbol, "gci_no_act_constraint_flag");                     cinfo->setNoActConstraintFlag(symbol > 0 ? true : false);
04528     READ_FLAG(symbol, "gci_no_explicit_scaling_list_constraint_flag");   cinfo->setNoExplicitScaleListConstraintFlag(symbol > 0 ? true : false);
04529     READ_FLAG(symbol, "gci_no_dep_quant_constraint_flag");               cinfo->setNoDepQuantConstraintFlag(symbol > 0 ? true : false);
04530     READ_FLAG(symbol, "gci_no_sign_data_hiding_constraint_flag");        cinfo->setNoSignDataHidingConstraintFlag(symbol > 0 ? true : false);
04531     READ_FLAG(symbol, "gci_no_cu_qp_delta_constraint_flag");             cinfo->setNoCuQpDeltaConstraintFlag(symbol > 0 ? true : false);
04532     READ_FLAG(symbol, "gci_no_chroma_qp_offset_constraint_flag");        cinfo->setNoChromaQpOffsetConstraintFlag(symbol > 0 ? true : false);
04533 
04534     /* loop filter */
04535     READ_FLAG(symbol, "gci_no_sao_constraint_flag");                     cinfo->setNoSaoConstraintFlag(symbol > 0 ? true : false);
04536     READ_FLAG(symbol, "gci_no_alf_constraint_flag");                     cinfo->setNoAlfConstraintFlag(symbol > 0 ? true : false);
04537     READ_FLAG(symbol, "gci_no_ccalf_constraint_flag");                   cinfo->setNoCCAlfConstraintFlag(symbol > 0 ? true : false);
04538     READ_FLAG(symbol, "gci_no_lmcs_constraint_flag");                    cinfo->setNoLmcsConstraintFlag(symbol > 0 ? true : false);
04539     READ_FLAG(symbol, "gci_no_ladf_constraint_flag");                    cinfo->setNoLadfConstraintFlag(symbol > 0 ? true : false);
04540     READ_FLAG(symbol, "gci_no_virtual_boundaries_constraint_flag");      cinfo->setNoVirtualBoundaryConstraintFlag(symbol > 0 ? true : false);
04541     READ_CODE(8, symbol, "gci_num_reserved_bits");
04542     uint32_t const numReservedBits = symbol;
04543     for (int i = 0; i < numReservedBits; i++)
04544     {
04545       READ_FLAG(symbol, "gci_reserved_zero_bit");                    CHECK(symbol != 0, "gci_reserved_zero_bit not equal to zero");
04546     }
04547   }
04548   while (!isByteAligned())
04549   {
04550     READ_FLAG(symbol, "gci_alignment_zero_bit");                     CHECK(symbol != 0, "gci_alignment_zero_bit not equal to zero");
04551   }
04552 }
04553 
04554 
04555 void HLSyntaxReader::parseProfileTierLevel(ProfileTierLevel *ptl, bool profileTierPresentFlag, int maxNumSubLayersMinus1)
04556 {
04557   uint32_t symbol;
04558   if(profileTierPresentFlag)
04559   {
04560     READ_CODE(7 , symbol,   "general_profile_idc"              ); ptl->setProfileIdc  (Profile::Name(symbol));
04561     READ_FLAG(    symbol,   "general_tier_flag"                ); ptl->setTierFlag    (symbol ? Level::HIGH : Level::MAIN);
04562   }
04563 
04564   READ_CODE( 8, symbol, "general_level_idc" ); ptl->setLevelIdc( Level::Name( symbol ) );
04565 
04566   READ_FLAG(      symbol,   "ptl_frame_only_constraint_flag"   ); ptl->setFrameOnlyConstraintFlag(symbol);
04567   READ_FLAG(      symbol,   "ptl_multilayer_enabled_flag"      ); ptl->setMultiLayerEnabledFlag(symbol);
04568   CHECK((ptl->getProfileIdc() == Profile::MAIN_10 || ptl->getProfileIdc() == Profile::MAIN_10_444
04569          || ptl->getProfileIdc() == Profile::MAIN_10_STILL_PICTURE
04570          || ptl->getProfileIdc() == Profile::MAIN_10_444_STILL_PICTURE)
04571           && symbol,
04572         "ptl_multilayer_enabled_flag shall be equal to 0 for non-multilayer profiles");
04573 
04574   if(profileTierPresentFlag)
04575   {
04576     parseConstraintInfo(ptl->getConstraintInfo());
04577   }
04578 
04579   for (int i = maxNumSubLayersMinus1 - 1; i >= 0; i--)
04580   {
04581     READ_FLAG( symbol, "sub_layer_level_present_flag[i]"   ); ptl->setSubLayerLevelPresentFlag  (i, symbol);
04582   }
04583 
04584   while (!isByteAligned())
04585   {
04586     READ_FLAG(    symbol,   "ptl_reserved_zero_bit"         ); CHECK (symbol != 0, "ptl_reserved_zero_bit not equal to zero");
04587   }
04588 
04589   for (int i = maxNumSubLayersMinus1 - 1; i >= 0; i--)
04590   {
04591     if (ptl->getSubLayerLevelPresentFlag(i))
04592     {
04593       READ_CODE(8 , symbol,   "sub_layer_level_idc"                ); ptl->setSubLayerLevelIdc    (i, Level::Name(symbol));
04594     }
04595   }
04596   ptl->setSubLayerLevelIdc(maxNumSubLayersMinus1, ptl->getLevelIdc());
04597   for( int i = maxNumSubLayersMinus1 - 1; i >= 0; i-- )
04598   {
04599     if( !ptl->getSubLayerLevelPresentFlag( i ) )
04600     {
04601       ptl->setSubLayerLevelIdc( i, ptl->getSubLayerLevelIdc( i + 1 ) );
04602     }
04603   }
04604 
04605   if (profileTierPresentFlag)
04606   {
04607     READ_CODE(8, symbol, "ptl_num_sub_profiles");
04608     uint8_t numSubProfiles = symbol;
04609     ptl->setNumSubProfile(numSubProfiles);
04610     for (int i = 0; i < numSubProfiles; i++)
04611     {
04612       READ_CODE(32, symbol, "general_sub_profile_idc[i]");
04613       ptl->setSubProfileIdc(i, symbol);
04614     }
04615   }
04616 }
