04620 void HLSyntaxReader::parseTerminatingBit( uint32_t& ruiBit )
04621 {
04622   ruiBit = false;
04623   int iBitsLeft = m_pcBitstream->getNumBitsLeft();
04624   if(iBitsLeft <= 8)
04625   {
04626     uint32_t uiPeekValue = m_pcBitstream->peekBits(iBitsLeft);
04627     if (uiPeekValue == (1<<(iBitsLeft-1)))
04628     {
04629       ruiBit = true;
04630     }
04631   }
04632 }
04633 
04634 void HLSyntaxReader::parseRemainingBytes( bool noTrailingBytesExpected )
04635 {
04636   if (noTrailingBytesExpected)
04637   {
04638     CHECK( 0 != m_pcBitstream->getNumBitsLeft(), "Bits left although no bits expected" );
04639   }
04640   else
04641   {
04642     while (m_pcBitstream->getNumBitsLeft())
04643     {
04644       uint32_t trailingNullByte=m_pcBitstream->readByte();
04645       if (trailingNullByte!=0)
04646       {
04647         msg( ERROR, "Trailing byte should be 0, but has value %02x\n", trailingNullByte);
04648         THROW("Invalid trailing '0' byte");
04649       }
04650     }
04651   }
04652 }
