04660 
04662 void HLSyntaxReader::parsePredWeightTable( Slice* pcSlice, const SPS *sps )
04663 {
04664   const ChromaFormat    chFmt        = sps->getChromaFormatIdc();
04665   const int             numValidComp = int(getNumberValidComponents(chFmt));
04666   const bool            bChroma      = (chFmt!=CHROMA_400);
04667   const SliceType       eSliceType   = pcSlice->getSliceType();
04668   const int             iNbRef       = (eSliceType == B_SLICE ) ? (2) : (1);
04669   uint32_t            uiLog2WeightDenomLuma=0, uiLog2WeightDenomChroma=0;
04670   uint32_t            uiTotalSignalledWeightFlags = 0;
04671 
04672   int iDeltaDenom;
04673   // decode delta_luma_log2_weight_denom :
04674   READ_UVLC( uiLog2WeightDenomLuma, "luma_log2_weight_denom" );
04675   CHECK( uiLog2WeightDenomLuma > 7, "The value of luma_log2_weight_denom shall be in the range of 0 to 7" );
04676   if( bChroma )
04677   {
04678     READ_SVLC( iDeltaDenom, "delta_chroma_log2_weight_denom" );
04679     CHECK((iDeltaDenom + (int)uiLog2WeightDenomLuma)<0, "luma_log2_weight_denom + delta_chroma_log2_weight_denom shall be in the range of 0 to 7");
04680     CHECK((iDeltaDenom + (int)uiLog2WeightDenomLuma)>7, "luma_log2_weight_denom + delta_chroma_log2_weight_denom shall be in the range of 0 to 7");
04681     uiLog2WeightDenomChroma = (uint32_t)(iDeltaDenom + uiLog2WeightDenomLuma);
04682   }
04683 
04684   for ( int iNumRef=0 ; iNumRef<iNbRef ; iNumRef++ ) // loop over l0 and l1 syntax elements
04685   {
04686     RefPicList  eRefPicList = ( iNumRef ? REF_PIC_LIST_1 : REF_PIC_LIST_0 );
04687     for ( int iRefIdx=0 ; iRefIdx<pcSlice->getNumRefIdx(eRefPicList) ; iRefIdx++ )
04688     {
04689       WPScalingParam *wp = pcSlice->getWpScaling(eRefPicList, iRefIdx);
04690 
04691       wp[COMPONENT_Y].log2WeightDenom = uiLog2WeightDenomLuma;
04692       for(int j=1; j<numValidComp; j++)
04693       {
04694         wp[j].log2WeightDenom = uiLog2WeightDenomChroma;
04695       }
04696 
04697       uint32_t  uiCode;
04698       READ_FLAG( uiCode, iNumRef==0?"luma_weight_l0_flag[i]":"luma_weight_l1_flag[i]" );
04699       wp[COMPONENT_Y].presentFlag = (uiCode == 1);
04700       uiTotalSignalledWeightFlags += wp[COMPONENT_Y].presentFlag;
04701     }
04702     if ( bChroma )
04703     {
04704       uint32_t  uiCode;
04705       for ( int iRefIdx=0 ; iRefIdx<pcSlice->getNumRefIdx(eRefPicList) ; iRefIdx++ )
04706       {
04707         WPScalingParam *wp = pcSlice->getWpScaling(eRefPicList, iRefIdx);
04708         READ_FLAG( uiCode, iNumRef==0?"chroma_weight_l0_flag[i]":"chroma_weight_l1_flag[i]" );
04709         for(int j=1; j<numValidComp; j++)
04710         {
04711           wp[j].presentFlag = (uiCode == 1);
04712         }
04713         uiTotalSignalledWeightFlags += 2 * wp[COMPONENT_Cb].presentFlag;
04714       }
04715     }
04716     else
04717     {
04718       for ( int iRefIdx=0; iRefIdx<MAX_NUM_REF; iRefIdx++ )
04719       {
04720         WPScalingParam *wp = pcSlice->getWpScaling(eRefPicList, iRefIdx);
04721 
04722         wp[COMPONENT_Cb].presentFlag = false;
04723         wp[COMPONENT_Cr].presentFlag = false;
04724       }
04725     }
04726     for ( int iRefIdx=0 ; iRefIdx<pcSlice->getNumRefIdx(eRefPicList) ; iRefIdx++ )
04727     {
04728       WPScalingParam *wp = pcSlice->getWpScaling(eRefPicList, iRefIdx);
04729       if (wp[COMPONENT_Y].presentFlag)
04730       {
04731         int iDeltaWeight;
04732         READ_SVLC( iDeltaWeight, iNumRef==0?"delta_luma_weight_l0[i]":"delta_luma_weight_l1[i]" );
04733         CHECK( iDeltaWeight < -128, "delta_luma_weight_lx shall be in the rage of -128 to 127" );
04734         CHECK( iDeltaWeight >  127, "delta_luma_weight_lx shall be in the rage of -128 to 127" );
04735         wp[COMPONENT_Y].codedWeight = (iDeltaWeight + (1 << wp[COMPONENT_Y].log2WeightDenom));
04736         READ_SVLC(wp[COMPONENT_Y].codedOffset, iNumRef == 0 ? "luma_offset_l0[i]" : "luma_offset_l1[i]");
04737         const int range=sps->getSpsRangeExtension().getHighPrecisionOffsetsEnabledFlag() ? (1<<sps->getBitDepth(CHANNEL_TYPE_LUMA))/2 : 128;
04738         CHECK(wp[0].codedOffset < -range, "luma_offset_lx shall be in the rage of -128 to 127");
04739         CHECK(wp[0].codedOffset >= range, "luma_offset_lx shall be in the rage of -128 to 127");
04740       }
04741       else
04742       {
04743         wp[COMPONENT_Y].codedWeight = (1 << wp[COMPONENT_Y].log2WeightDenom);
04744         wp[COMPONENT_Y].codedOffset = 0;
04745       }
04746       if ( bChroma )
04747       {
04748         if (wp[COMPONENT_Cb].presentFlag)
04749         {
04750           int range=sps->getSpsRangeExtension().getHighPrecisionOffsetsEnabledFlag() ? (1<<sps->getBitDepth(CHANNEL_TYPE_CHROMA))/2 : 128;
04751           for ( int j=1 ; j<numValidComp ; j++ )
04752           {
04753             int iDeltaWeight;
04754             READ_SVLC( iDeltaWeight, iNumRef==0?"delta_chroma_weight_l0[i]":"delta_chroma_weight_l1[i]" );
04755             CHECK( iDeltaWeight < -128, "delta_chroma_weight_lx shall be in the rage of -128 to 127" );
04756             CHECK( iDeltaWeight >  127, "delta_chroma_weight_lx shall be in the rage of -128 to 127" );
04757             wp[j].codedWeight = (iDeltaWeight + (1 << wp[j].log2WeightDenom));
04758 
04759             int iDeltaChroma;
04760             READ_SVLC( iDeltaChroma, iNumRef==0?"delta_chroma_offset_l0[i]":"delta_chroma_offset_l1[i]" );
04761             CHECK( iDeltaChroma <  -4*range, "delta_chroma_offset_lx shall be in the range of -4 * 128 to 4 * 127" );
04762             CHECK( iDeltaChroma >  4*(range-1), "delta_chroma_offset_lx shall be in the range of -4 * 128 to 4 * 127" );
04763             int pred          = (range - ((range * wp[j].codedWeight) >> (wp[j].log2WeightDenom)));
04764             wp[j].codedOffset = Clip3(-range, range - 1, (iDeltaChroma + pred));
04765           }
04766         }
04767         else
04768         {
04769           for ( int j=1 ; j<numValidComp ; j++ )
04770           {
04771             wp[j].codedWeight = (1 << wp[j].log2WeightDenom);
04772             wp[j].codedOffset = 0;
04773           }
04774         }
04775       }
04776     }
04777 
04778     for ( int iRefIdx=pcSlice->getNumRefIdx(eRefPicList) ; iRefIdx<MAX_NUM_REF ; iRefIdx++ )
04779     {
04780       WPScalingParam *wp = pcSlice->getWpScaling(eRefPicList, iRefIdx);
04781 
04782       wp[COMPONENT_Y].presentFlag  = false;
04783       wp[COMPONENT_Cb].presentFlag = false;
04784       wp[COMPONENT_Cr].presentFlag = false;
04785     }
04786   }
04787   CHECK(uiTotalSignalledWeightFlags>24, "Too many weight flag signalled");
04788 }
