04790 void HLSyntaxReader::parsePredWeightTable(PicHeader *picHeader, const PPS *pps, const SPS *sps)
04791 {
04792   WPScalingParam *   wp;
04793   const ChromaFormat chFmt                     = sps->getChromaFormatIdc();
04794   const int          numValidComp              = int(getNumberValidComponents(chFmt));
04795   const bool         chroma                    = (chFmt != CHROMA_400);
04796   uint32_t           log2WeightDenomLuma       = 0;
04797   uint32_t           log2WeightDenomChroma     = 0;
04798   uint32_t           totalSignalledWeightFlags = 0;
04799 
04800   int deltaDenom;
04801   READ_UVLC(log2WeightDenomLuma, "luma_log2_weight_denom");
04802   CHECK(log2WeightDenomLuma > 7, "The value of luma_log2_weight_denom shall be in the range of 0 to 7");
04803   if (chroma)
04804   {
04805     READ_SVLC(deltaDenom, "delta_chroma_log2_weight_denom");
04806     CHECK((deltaDenom + (int) log2WeightDenomLuma) < 0, "luma_log2_weight_denom + delta_chroma_log2_weight_denom shall be in the range of 0 to 7");
04807     CHECK((deltaDenom + (int) log2WeightDenomLuma) > 7, "luma_log2_weight_denom + delta_chroma_log2_weight_denom shall be in the range of 0 to 7");
04808     log2WeightDenomChroma = (uint32_t)(deltaDenom + log2WeightDenomLuma);
04809   }
04810 
04811   uint32_t numLxWeights;
04812   READ_UVLC(numLxWeights, "num_l0_weights");
04813   picHeader->setNumL0Weights(numLxWeights);
04814   picHeader->setNumL1Weights(0);
04815 
04816   bool moreSyntaxToBeParsed = true;
04817   for (int numRef = 0; numRef < NUM_REF_PIC_LIST_01 && moreSyntaxToBeParsed; numRef++)
04818   {
04819     RefPicList refPicList = (numRef ? REF_PIC_LIST_1 : REF_PIC_LIST_0);
04820     for (int refIdx = 0; refIdx < numLxWeights; refIdx++)
04821     {
04822       wp = picHeader->getWpScaling(refPicList, refIdx);
04823 
04824       wp[COMPONENT_Y].log2WeightDenom = log2WeightDenomLuma;
04825       for (int j = 1; j < numValidComp; j++)
04826       {
04827         wp[j].log2WeightDenom = log2WeightDenomChroma;
04828       }
04829 
04830       uint32_t uiCode;
04831       READ_FLAG(uiCode, numRef == 0 ? "luma_weight_l0_flag[i]" : "luma_weight_l1_flag[i]");
04832       wp[COMPONENT_Y].presentFlag = (uiCode == 1);
04833       totalSignalledWeightFlags += wp[COMPONENT_Y].presentFlag;
04834     }
04835     if (chroma)
04836     {
04837       uint32_t uiCode;
04838       for (int refIdx = 0; refIdx < numLxWeights; refIdx++)
04839       {
04840         wp = picHeader->getWpScaling(refPicList, refIdx);
04841         READ_FLAG(uiCode, numRef == 0 ? "chroma_weight_l0_flag[i]" : "chroma_weight_l1_flag[i]");
04842         for (int j = 1; j < numValidComp; j++)
04843         {
04844           wp[j].presentFlag = (uiCode == 1);
04845         }
04846         totalSignalledWeightFlags += 2 * wp[COMPONENT_Cb].presentFlag;
04847       }
04848     }
04849     else
04850     {
04851       for ( int refIdx=0; refIdx<MAX_NUM_REF; refIdx++ )
04852       {
04853         wp                = picHeader->getWpScaling(refPicList, refIdx);
04854         wp[1].presentFlag = false;
04855         wp[2].presentFlag = false;
04856       }
04857     }
04858     for (int refIdx = 0; refIdx < numLxWeights; refIdx++)
04859     {
04860       wp = picHeader->getWpScaling(refPicList, refIdx);
04861       if (wp[COMPONENT_Y].presentFlag)
04862       {
04863         int deltaWeight;
04864         READ_SVLC(deltaWeight, numRef == 0 ? "delta_luma_weight_l0[i]" : "delta_luma_weight_l1[i]");
04865         CHECK(deltaWeight < -128, "delta_luma_weight_lx shall be in the rage of -128 to 127");
04866         CHECK(deltaWeight > 127, "delta_luma_weight_lx shall be in the rage of -128 to 127");
04867         wp[COMPONENT_Y].codedWeight = (deltaWeight + (1 << wp[COMPONENT_Y].log2WeightDenom));
04868         READ_SVLC(wp[COMPONENT_Y].codedOffset, numRef == 0 ? "luma_offset_l0[i]" : "luma_offset_l1[i]");
04869         const int range = sps->getSpsRangeExtension().getHighPrecisionOffsetsEnabledFlag() ? (1 << sps->getBitDepth(CHANNEL_TYPE_LUMA)) / 2 : 128;
04870         CHECK(wp[0].codedOffset < -range, "luma_offset_lx shall be in the rage of -128 to 127");
04871         CHECK(wp[0].codedOffset >= range, "luma_offset_lx shall be in the rage of -128 to 127");
04872       }
04873       else
04874       {
04875         wp[COMPONENT_Y].codedWeight = (1 << wp[COMPONENT_Y].log2WeightDenom);
04876         wp[COMPONENT_Y].codedOffset = 0;
04877       }
04878       if (chroma)
04879       {
04880         if (wp[COMPONENT_Cb].presentFlag)
04881         {
04882           int range = sps->getSpsRangeExtension().getHighPrecisionOffsetsEnabledFlag() ? (1 << sps->getBitDepth(CHANNEL_TYPE_CHROMA)) / 2 : 128;
04883           for (int j = 1; j < numValidComp; j++)
04884           {
04885             int deltaWeight;
04886             READ_SVLC(deltaWeight, numRef == 0 ? "delta_chroma_weight_l0[i]" : "delta_chroma_weight_l1[i]");
04887             CHECK( deltaWeight < -128, "delta_chroma_weight_lx shall be in the rage of -128 to 127" );
04888             CHECK( deltaWeight >  127, "delta_chroma_weight_lx shall be in the rage of -128 to 127" );
04889             wp[j].codedWeight = (deltaWeight + (1 << wp[j].log2WeightDenom));
04890 
04891             int deltaChroma;
04892             READ_SVLC(deltaChroma, numRef == 0 ? "delta_chroma_offset_l0[i]" : "delta_chroma_offset_l1[i]");
04893             CHECK( deltaChroma <  -4*range, "delta_chroma_offset_lx shall be in the range of -4 * 128 to 4 * 127" );
04894             CHECK( deltaChroma >=  4*range, "delta_chroma_offset_lx shall be in the range of -4 * 128 to 4 * 127" );
04895             int pred          = (range - ((range * wp[j].codedWeight) >> (wp[j].log2WeightDenom)));
04896             wp[j].codedOffset = Clip3(-range, range - 1, (deltaChroma + pred));
04897           }
04898         }
04899         else
04900         {
04901           for (int j = 1; j < numValidComp; j++)
04902           {
04903             wp[j].codedWeight = (1 << wp[j].log2WeightDenom);
04904             wp[j].codedOffset = 0;
04905           }
04906         }
04907       }
04908     }
04909 
04910     for (int refIdx = numLxWeights; refIdx < MAX_NUM_REF; refIdx++)
04911     {
04912       wp = picHeader->getWpScaling(refPicList, refIdx);
04913 
04914       wp[0].presentFlag = false;
04915       wp[1].presentFlag = false;
04916       wp[2].presentFlag = false;
04917     }
04918 
04919     if (numRef == 0)
04920     {
04921       if (pps->getWPBiPred() && picHeader->getRPL(1)->getNumRefEntries() > 0)
04922       {
04923         READ_UVLC(numLxWeights, "num_l1_weights");
04924       }
04925       else
04926       {
04927         numLxWeights = 0;
04928       }
04929       moreSyntaxToBeParsed = (numLxWeights == 0) ? false : true;
04930       picHeader->setNumL1Weights(numLxWeights);
04931     }
04932   }
04933   CHECK(totalSignalledWeightFlags > 24, "Too many weight flag signalled");
04934 }
04935 
04939 void HLSyntaxReader::parseScalingList(ScalingList *scalingList, bool aps_chromaPrsentFlag)
04940 {
04941   uint32_t  code;
04942   bool scalingListCopyModeFlag;
04943   scalingList->setChromaScalingListPresentFlag(aps_chromaPrsentFlag);
04944   for (int scalingListId = 0; scalingListId < 28; scalingListId++)
04945   {
04946     if (aps_chromaPrsentFlag || scalingList->isLumaScalingList(scalingListId))
04947   {
04948     READ_FLAG(code, "scaling_list_copy_mode_flag");
04949     scalingListCopyModeFlag = (code) ? true : false;
04950     scalingList->setScalingListCopyModeFlag(scalingListId, scalingListCopyModeFlag);
04951 
04952     scalingList->setScalingListPreditorModeFlag(scalingListId, false);
04953     if (!scalingListCopyModeFlag)
04954     {
04955       READ_FLAG(code, "scaling_list_predictor_mode_flag");
04956       scalingList->setScalingListPreditorModeFlag(scalingListId, code);
04957     }
04958 
04959     if ((scalingListCopyModeFlag || scalingList->getScalingListPreditorModeFlag(scalingListId)) && scalingListId!= SCALING_LIST_1D_START_2x2 && scalingListId!= SCALING_LIST_1D_START_4x4 && scalingListId!= SCALING_LIST_1D_START_8x8) //Copy Mode
04960     {
04961       READ_UVLC(code, "scaling_list_pred_matrix_id_delta");
04962       scalingList->setRefMatrixId(scalingListId, (uint32_t)((int)(scalingListId)-(code)));
04963     }
04964     else if (scalingListCopyModeFlag || scalingList->getScalingListPreditorModeFlag(scalingListId))
04965     {
04966       scalingList->setRefMatrixId(scalingListId, (uint32_t)((int)(scalingListId)));
04967     }
04968     if (scalingListCopyModeFlag)//copy
04969     {
04970       if (scalingListId >= SCALING_LIST_1D_START_16x16)
04971       {
04972         scalingList->setScalingListDC(scalingListId,
04973           ((scalingListId == scalingList->getRefMatrixId(scalingListId)) ? 16
04974             : (scalingList->getRefMatrixId(scalingListId) < SCALING_LIST_1D_START_16x16) ? scalingList->getScalingListAddress(scalingList->getRefMatrixId(scalingListId))[0] : scalingList->getScalingListDC(scalingList->getRefMatrixId(scalingListId))));
04975       }
04976       scalingList->processRefMatrix(scalingListId, scalingList->getRefMatrixId(scalingListId));
04977     }
04978     else
04979     {
04980       decodeScalingList(scalingList, scalingListId, scalingList->getScalingListPreditorModeFlag(scalingListId));
04981     }
04982   }
04983   else
04984   {
04985     scalingListCopyModeFlag = true;
04986     scalingList->setScalingListCopyModeFlag(scalingListId, scalingListCopyModeFlag);
04987     scalingList->setRefMatrixId(scalingListId, (uint32_t)((int)(scalingListId)));
04988     if (scalingListId >= SCALING_LIST_1D_START_16x16)
04989     {
04990       scalingList->setScalingListDC(scalingListId, 16);
04991     }
04992     scalingList->processRefMatrix(scalingListId, scalingList->getRefMatrixId(scalingListId));
04993   }
04994   }
04995 
04996   return;
04997 }
04998 
05004 void HLSyntaxReader::decodeScalingList(ScalingList *scalingList, uint32_t scalingListId, bool isPredictor)
05005 {
05006   int matrixSize = (scalingListId < SCALING_LIST_1D_START_4x4) ? 2 : (scalingListId < SCALING_LIST_1D_START_8x8) ? 4 : 8;
05007   int i, coefNum = matrixSize * matrixSize;
05008   int data;
05009   int scalingListDcCoefMinus8 = 0;
05010   int nextCoef = (isPredictor) ? 0 : SCALING_LIST_START_VALUE;
05011   ScanElement *scan = g_scanOrder[SCAN_UNGROUPED][SCAN_DIAG][gp_sizeIdxInfo->idxFrom(matrixSize)][gp_sizeIdxInfo->idxFrom(matrixSize)];
05012   int *dst = scalingList->getScalingListAddress(scalingListId);
05013 
05014   int PredListId = scalingList->getRefMatrixId(scalingListId);
05015   CHECK(isPredictor && PredListId > scalingListId, "Scaling List error predictor!");
05016   const int *srcPred = (isPredictor) ? ((scalingListId == PredListId) ? scalingList->getScalingListDefaultAddress(scalingListId) : scalingList->getScalingListAddress(PredListId)) : NULL;
05017   if(isPredictor && scalingListId == PredListId)
05018     scalingList->setScalingListDC(PredListId, SCALING_LIST_DC);
05019   int predCoef = 0;
05020 
05021   if (scalingListId >= SCALING_LIST_1D_START_16x16)
05022   {
05023     READ_SVLC(scalingListDcCoefMinus8, "scaling_list_dc_coef_minus8");
05024     nextCoef += scalingListDcCoefMinus8;
05025     if (isPredictor)
05026     {
05027       predCoef = (PredListId >= SCALING_LIST_1D_START_16x16) ? scalingList->getScalingListDC(PredListId) : srcPred[0];
05028     }
05029     scalingList->setScalingListDC(scalingListId, (nextCoef + predCoef + 256) & 255);
05030   }
05031 
05032   for(i = 0; i < coefNum; i++)
05033   {
05034     if (scalingListId >= SCALING_LIST_1D_START_64x64 && scan[i].x >= 4 && scan[i].y >= 4)
05035     {
05036       dst[scan[i].idx] = 0;
05037       continue;
05038     }
05039     READ_SVLC( data, "scaling_list_delta_coef");
05040     nextCoef += data;
05041     predCoef = (isPredictor) ? srcPred[scan[i].idx] : 0;
05042     dst[scan[i].idx] = (nextCoef + predCoef + 256) & 255;
05043   }
05044 }
05045 
05046 bool HLSyntaxReader::xMoreRbspData()
05047 {
05048   int bitsLeft = m_pcBitstream->getNumBitsLeft();
05049 
05050   // if there are more than 8 bits, it cannot be rbsp_trailing_bits
05051   if (bitsLeft > 8)
05052   {
05053     return true;
05054   }
05055 
05056   uint8_t lastByte = m_pcBitstream->peekBits(bitsLeft);
05057   int cnt = bitsLeft;
05058 
05059   // remove trailing bits equal to zero
05060   while ((cnt>0) && ((lastByte & 1) == 0))
05061   {
05062     lastByte >>= 1;
05063     cnt--;
05064   }
05065   // remove bit equal to one
05066   cnt--;
05067 
05068   // we should not have a negative number of bits
05069   CHECK (cnt<0, "Negative number of bits");
05070 
05071   // we have more data, if cnt is not zero
05072   return (cnt>0);
05073 }
05074 
05075 
05076 void HLSyntaxReader::alfFilter( AlfParam& alfParam, const bool isChroma, const int altIdx )
05077 {
05078   uint32_t code;
05079 
05080   // derive maxGolombIdx
05081   AlfFilterShape alfShape( isChroma ? 5 : 7 );
05082   const int numFilters = isChroma ? 1 : alfParam.numLumaFilters;
05083   short* coeff = isChroma ? alfParam.chromaCoeff[altIdx] : alfParam.lumaCoeff;
05084   Pel*   clipp = isChroma ? alfParam.chromaClipp[altIdx] : alfParam.lumaClipp;
05085 
05086 
05087   // Filter coefficients
05088   for( int ind = 0; ind < numFilters; ++ind )
05089   {
05090 
05091     for( int i = 0; i < alfShape.numCoeff - 1; i++ )
05092     {
05093       READ_UVLC( code, isChroma ? "alf_chroma_coeff_abs" : "alf_luma_coeff_abs" );
05094       coeff[ ind * MAX_NUM_ALF_LUMA_COEFF + i ] = code;
05095       if( coeff[ ind * MAX_NUM_ALF_LUMA_COEFF + i ] != 0 )
05096       {
05097         READ_FLAG( code, isChroma ? "alf_chroma_coeff_sign" : "alf_luma_coeff_sign" );
05098         coeff[ ind * MAX_NUM_ALF_LUMA_COEFF + i ] = ( code ) ? -coeff[ ind * MAX_NUM_ALF_LUMA_COEFF + i ] : coeff[ ind * MAX_NUM_ALF_LUMA_COEFF + i ];
05099        }
05100       CHECK( isChroma &&
05101              ( coeff[ind * MAX_NUM_ALF_LUMA_COEFF + i] > 127 || coeff[ind * MAX_NUM_ALF_LUMA_COEFF + i] < -128 )
05102              , "AlfCoeffC shall be in the range of -128 to 127, inclusive" );
05103     }
05104   }
05105 
05106   // Clipping values coding
05107   if ( alfParam.nonLinearFlag[isChroma] )
05108   {
05109 
05110     // Filter coefficients
05111     for( int ind = 0; ind < numFilters; ++ind )
05112     {
05113 
05114       for( int i = 0; i < alfShape.numCoeff - 1; i++ )
05115       {
05116         READ_CODE(2, code, isChroma ? "alf_chroma_clip_idx" : "alf_luma_clip_idx");
05117         clipp[ind * MAX_NUM_ALF_LUMA_COEFF + i] = code;
05118       }
05119     }
05120   }
05121   else
05122   {
05123     for( int ind = 0; ind < numFilters; ++ind )
05124     {
05125       std::fill_n( clipp + ind * MAX_NUM_ALF_LUMA_COEFF, alfShape.numCoeff, 0 );
05126     }
05127   }
05128 }
